local _, ns = ...

-- NPC gossip, quest greetings and speech: hash of the English text -> Danish.
-- The English keys follow PolishForever's hashing scheme (github.com/JSlomian/PolishForever, MIT; its data CC BY 4.0).
ns.Gossip = {
    [4057477108] = "\"...\"$B$BKroppen af tauren-druiden ligger stille og ubevægelig.  Det ser ud til, at han endelig er gået fra denne verden over til det store hinsides, han fik lovet.",
    [758949016] = "\"En færdighed for dem, der vil overvinde forhindringer.\"  Jeg tror, det er sådan Fælyssa beskriver sit færdighedssæt. \n\nHvis du tror som hun, så find vej til Cenarion-enklaven i den nordlige del af Darnassos, hvor hun underviser sin klasse.",
    [3738880286] = "\"En færdighed for dem, der vil overvinde forhindringer.\"  Jeg tror, det er sådan Fælyssa beskriver sit færdighedssæt.  \n\nHvis du tror som hun, så find vej til Cenarion-enklaven i den nordlige del af Darnassos, hvor hun underviser sin klasse.",
    [3221195903] = "\"Darnassisk?\"$B$BNattelvedruiden ser forventningsfuldt på dig, men det er tydeligt, at I ikke kan tale sammen.  Uforfærdet peger hun på sig selv og smiler.  Hun peger på dig og smiler endnu en gang.  Til sidst vinker hun flere gange ned ad stien mod nord.$B$BMon hun antyder, at der er en druide, du kan tale med, længere oppe ad vejen?",
    [2168339167] = "\"Godt arbejde med at samle ressourcer til krigen,\" sagde de, \"Få en forfremmelse,\" sagde de.  Det de egentlig mente var \"Du er placeret uden for en insektrede i Silitus sammen med en flok svedige dværge, Kødnes!\"$B$BTak for forfremmelsen, Kaptajn!",
    [1604754618] = "\"Kadgars Mystiske Dagbog, Bind 8.\" Jeg tror, det er den, jeg ville have.",
    [4250663860] = "\"Magiske Sygdomme\", nej. \"Magiske Matricer\", nej. Ahh, her er vi \"Magiske Mysterier\".",
    [932525210] = "\"Magiske Strømme og Hvordan De Påvirker Verden\", af Maginor Dummas. Det er den, jeg ledte efter.",
    [2128649029] = "\"Tyrahe?\"$B$BTauren-druiden ser forventningsfuldt på dig, men det er tydeligt, at I ikke kan tale sammen.  Uforfærdet peger hun på sig selv og smiler.  Hun peger på dig og smiler endnu en gang.  Til sidst vinker hun flere gange ned ad stien mod syd.$B$BMon hun antyder, at der er en druide, du kan tale med, længere nede ad vejen?",
    [3170076008] = "\"Arkanistens Kogebog\" er også væk! Det er en katastrofe!",
    [3550011905] = "$950w, soldat.",
    [3988955680] = "$962w Stormspids-kommandør(er) og $950w Stormspids-løjtnant(er).",
    [462061971] = "$962w, soldat.",
    [3895484112] = "$964w, unge $c.",
    [1426411412] = "$966w Frostulv-kommandør(er) og $964w Frostulv-løjtnant(er), soldat.",
    [3559379500] = "$966w, unge $c.",
    [4265862851] = "$C - Jeg vil fortære dit lys!",
    [1228118658] = "$C, hvad? Jeg er Krazek, Baron Tyranbrands sekretær. Jeg ved alt om, hvad der foregår i denne jungle og videre ud. Måske er du interesseret i at vide den aktuelle pris på olie i Skralleby? Nej? Leder du efter arbejde, måske? Det kan jeg hjælpe dig med.",
    [805745666] = "$C, selv vores hårdeste krigere og spejdere får brug for helingens kunst i den krig, der kommer ved Ahn'Kiraj. Og når der ikke er nogen magisk heling at hente, må de stole på vores indsats her.$B$BHidtil har jeg samlet $2088w runestofbandager ud af de $2090w, der er nødvendige. Hvis du er villig, bør vi tale videre om, hvordan du kan gøre din del.",
    [2044212658] = "$C, jeg har brug for flere kobberbarrer! Der bliver en krig klar ved Portene til Ahn'Kiraj, og vi har brug for forsyninger! Alliancen har samlet $1997w, og vi skal bruge $1998w kobberbarrer i alt. Hvis jeg ikke får de kobberbarrer, ender mit hoved på et fad!",
    [2798695601] = "$C, lyt venligst til, hvad jeg har at sige. Alliancen og Horden forbereder sig på krig mod Silitiderne og deres herrer i Ahn'Kiraj. Enhver hjælp, du kan yde, vil blive meget værdsat. Som du kan se, samler jeg thoriumbarrer her til krigsindsatsen. Vi skal samle $2012w i alt, og lige nu har vi $2011w.",
    [1155362226] = "$C, Horden har samlet alt, hvad den behøver til Ahn'Kiraj-krigen! Nu venter vi på, at den pjattede Alliance skal indhente os. Når de gør det, begynder vi at transportere alt til Silitus. Der går ikke længe, efter opbygningen dér er færdig, før krigen begynder!",
    [1129934706] = "$C, takket være mange hænders arbejde har vi formået at samle alle de runestofbandager, som Alliancen mener, den har brug for til den kommende konflikt. Var jeg dig, ville jeg spørge nogle af de andre her, om de stadig har indsamlingsopgaver, der skal løses.",
    [2704044541] = "$C, vi skammer os ikke over at sige, at vi har brug for al den hjælp, vi kan få i vores kamp i Krigssang-Gulch.  Men der er større ære at vinde nu end nogensinde før, hvis du vælger at lægge dine evner til vores side.  Desuden vil Sølvvinge-vagterne helt sikkert se mere positivt på din indsats på vores vegne.  Vil du deltage i kampen?",
    [2162384220] = "$C, vi har et stort behov for din hjælp i Krigssang-Gulch mod Sølvvinge-vagterne.  Og der er endnu større ære og ry at hente hos Krigssang-forriderne!  Har du modet til at gå i kamp?",
    [843584149] = "$C, vi har brug for din assistance i Krigssang-Gulch.  Vil du hjælpe os i kampen mod Krigssang-forriderne?",
    [3240860509] = "$g Hey der, sødeste, leder du efter et lift til Grommegol? Jeg har hørt, at det bliver ganske hedt nede i de jungler, måske kunne jeg følge med dig på en kort ferie og vise dig en rigtig jungle-kat. : Kom, tag en tur til de vidunderlige, smukke, tropiske jungler i Kvælerdorn. Sådan er det, du også kan bruge din tid på at solbade ved det krystalblå vand, mens jeg står her i den uudholdelige hede med intet andet at kigge på end min bror Frizza hele dagen! God rejse!;",
    [3924421361] = "$G Mester:Dame; $n! Mester Kang har spurgt til dig! Måske er det din tid!",
    [4244209333] = "$G Hr.:Frøken;, hvis jeg ikke vidste bedre, ville jeg tro, du var en af de 'særlige' folk. Vi kalder dem Trolde.$B$BVindslot havde ingen problemer med Mørkjernsdværgene, for hans oldefars, oldefars, tipoldefars bedste ven var jo en Mørkejern. Hvilket nok også er grunden til, at den hær af Mørkjernsdværge ikke slog ham ihjel på stedet.",
    [3021200696] = "$G Ridder : Frue;, ja $g ridder : frue;! Menig Portner melder sig til tjeneste og er klar til at hjælpe dig med dine behov for indsamling af mellemlæder. Krigen mod Ahn'Kiraj er på vej, og vi må være så forberedte, som vi kan.$B$BSom du kan se, har vi samlet præcis $2063w stykker mellemlæder, og jeg har fået til opgave at samle i alt $2064w.",
    [3070031173] = "$n angriber! Hjælp!",
    [132993897] = "$n bragte os sprit!  Lad os feste!",
    [432736753] = "$n har erobret Alliance-flaget!",
    [1797860539] = "$n har erobret Horde-flaget!",
    [3851648502] = "$n gør krav på smedjen!  Hvis ingen udfordrer det, vil Alliancen kontrollere den om 1 minut!",
    [2560980372] = "$n gør krav på smedjen!  Hvis ingen udfordrer det, vil Horden kontrollere den om 1 minut!",
    [994993941] = "$n gør krav på gården!  Hvis ingen udfordrer det, vil Alliancen kontrollere den om 1 minut!",
    [3356891270] = "$n gør krav på gården!  Hvis ingen udfordrer det, vil Horden kontrollere den om 1 minut!",
    [291086723] = "$n gør krav på savværket!  Hvis ingen udfordrer det, vil Alliancen kontrollere det om 1 minut!",
    [618007827] = "$n gør krav på savværket!  Hvis ingen udfordrer det, vil Horden kontrollere det om 1 minut!",
    [1483905336] = "$n gør krav på minen!  Hvis ingen udfordrer den, vil Alliancen kontrollere den om 1 minut!",
    [171907437] = "$n gør krav på minen!  Hvis ingen udfordrer den, vil Horden kontrollere den om 1 minut!",
    [2986583412] = "$n gør krav på Snefald-gravpladsen!  Hvis ingen udfordrer den, vil Alliancen kontrollere den!",
    [1615039882] = "$n gør krav på Snefald-gravpladsen!  Hvis ingen udfordrer den, vil Horden kontrollere den!",
    [367264263] = "$n gør krav på stalden!  Hvis ingen udfordrer den, vil Alliancen kontrollere den om 1 minut!",
    [2568973889] = "$n gør krav på stalden!  Hvis ingen udfordrer den, vil Horden kontrollere den om 1 minut!",
    [2607614396] = "$n kommer hurtigt ind!  Gør jer klar til kamp!",
    [3902687581] = "$n kommer lige imod os!",
    [192008944] = "$n kommer hurtigt herhen!  Gør jer klar til angreb!",
    [2637098388] = "$n har angrebet smedjen!",
    [170655880] = "$n har angrebet gården!",
    [3458060584] = "$n har angrebet savværket!",
    [600446525] = "$n har angrebet minen!",
    [1027686075] = "$n har angrebet stalden!",
    [1362080063] = "$n har forsvaret smedjen!",
    [2411265110] = "$n har forsvaret gården!",
    [4147664875] = "$n har forsvaret savværket!",
    [210465990] = "$n har forsvaret minen!",
    [3767346058] = "$N har forsvaret den sydlige gård!",
    [4070315380] = "$n har forsvaret stalden!",
    [1291124012] = "$n er på vej herhen i fart! Tid til hævn!",
    [906899801] = "$n er på vej herhen i fart! Til våben!",
    [2202910203] = "$n DRÆB! $G Han:Hun; dræber dig nu! LØB! LØB!",
    [3032858610] = "$n løb Handsken igennem!  Tre hurra for $n!",
    [1701617607] = "$n!  Forræder mod Ragnarøs!",
    [396486456] = "$n!  Jeg er færdig!",
    [3181639068] = "$n!  Vores forsyninger slipper op, og indtil vi får flere, kan vi ikke sætte store landangreb i gang mod Kampens Mark!$B$BTal med Stormspids-kvartermesteren.  Han fortæller dig, hvad du kan gøre for at forsyne vores angrebsstyrker.",
    [800429095] = "$n!  Forbered dig på at møde din undergang!",
    [1899373691] = "$n!  Hvad laver du og taler med mig?  Du burde være ude og kæmpe mod Horden!$B$BJeg har angrebsordrer til en af vores feltmarskaller på Kampens Mark, men jeg har brug for nogen, jeg kan stole på.$B$BMåske hvis dit omdømme hos Stormspids-militsen var højere, kunne jeg stole på dig...",
    [3172669237] = "$n!  Du er tilbage!  Og ikke et øjeblik for tidligt!",
    [2649967596] = "$n! Endelig!$B$BDu skal tage dette fyrtårn og plante det i den østlige krater på de centrale slagmarker. Min flyvning angriber, når fyrtårnet udstråler sine koordinater!",
    [459272537] = "$n! Hjælp!",
    [2478487950] = "$n! Hvordan har du haft det, $g dreng : pige;? Vis mig, hvad du har lært, siden jeg så dig sidst, så ser vi, om der er noget nyt, jeg kan lære dig.",
    [3402842373] = "$n! Jeg holder øje med dig!",
    [3906032601] = "$n! DETTE OMRÅDE ER SPÆRRET FRA!",
    [2534106085] = "$n! Er du kommet tilbage bare for at tale med mig? Hvor er det dog omtænksomt af dig, og du ser også ret sød ud i det outfit!$B$BDu aner ikke, hvor godt det får mig til at have det at se dig. Det kan blive ret ensomt heroppe, med de fleste af disse vildbasser, der ikke kan se mig, og alt det. Det er en stor ting, du har gjort for os alle, og jeg glemmer det aldrig!$B$BTak, fordi du kiggede forbi og sagde hej, og vær nu ikke sådan en fremmed.",
    [1287182203] = "$n, Mester af Den Bronze Drageflugt, har slået Basse-gongen. De gamle porte til Ahn'Kiraj åbner sig og afslører rædslerne fra en glemt krig...",
    [2812871395] = "$n, hva'? Hov! Borger $n, kom herhen. Højlord Bolvar Fordrågon har bedt alle brugbare helte fra Alliancen om at mødes med ham i Stormvinds Fæstning. Du er lige blevet rekrutteret, makker! Kom i gang!",
    [1327541244] = "$n, har du overhovedet nogen anelse om, hvad vi står over for i Alterac-dalen?  Er du klar til at kæmpe mod Frostulv-klanen?",
    [3248522189] = "$n, hvordan kan jeg yderligere styrke din træning i Jordmoderens øjne?",
    [2702409821] = "$n, jeg har brug for din hjælp igen.",
    [2758259605] = "$n, jeg har skabt renselsestotemet.",
    [951264918] = "$n, jeg har de oplysninger, du søger...",
    [2673769233] = "$N, jeg fornemmer, at det store udyr nærmer sig...",
    [3602621878] = "$n, jeg smutter, før et af disse bæster får smag for mig!",
    [4125984468] = "$n, jeg vil gerne have et ord med dig.",
    [1771129485] = "$n, jeg sørger for, at alle mine venner i Kartellet ved, at du har reddet mit liv i dag.  Her - jeg skal kunne rejse let, så hjælp dig selv til mit lager af skrædder- og læderarbejdsforsyninger!  Tak igen - vi ses!",
    [175010721] = "$N, jeg er kommet for at finde ud af, hvor udbredte effekterne af Ondmos er over hele Mørkekysten. Korruptionen af Teldrasil og vores omkringliggende lande bekymrer virkelig druiderne i Cenarion-kredsen og alle nattealferne.$B$BDet er mit mål at finde ud af, hvorfor det er sket, og at sætte en stopper for det.",
    [3035451598] = "$n, det er godt at se dig.  Vores krig mod de andre elementarherrer raser endnu, men din indsats hjælper med at sikre vores sejr.",
    [3975502130] = "$N, nu er det tid til det sidste skridt; vi må aktivere alteret.",
    [2027056916] = "$n, det er godt at se veteraner som dig i marken!  Jeg må desværre melde, at vores forsyninger lige nu er for små til at sætte store landangreb i gang mod Horden.$B$BTal med vores kvartermester; han har forsyningsmissioner til rådighed.",
    [2283092014] = "$n, det er godt at se dig igen!  Har du det sjovt på Mørkemånens Marked?$B$BVil du armbryde?  Nej, selvfølgelig ikke... du vil jo beholde din arm!",
    [35744239] = "$n, må din død stå som et eksempel for alle, der udfordrer Defias-broderskabet!",
    [4172660555] = "$n, mine pligter er udført, og jeg tager nu min afsked.  Held og lykke til dig, min $gkammerat:dame;, og husk at holde Klokken, Hjulet og Lyset i gang!",
    [2378146608] = "$n, min skikkelse har nu skiftet! Min ånds sande styrke vender nu tilbage til mig... Skovens forbandede greb slipper mig.",
    [837077522] = "$n, mine sår er alvorlige.  Tilgiv mit langsomme tempo, men mine skader tillader mig ikke at gå hurtigere.",
    [3957141483] = "$n, ingen ondt A-Mig. A-Mig, god.",
    [1993033680] = "$n, læg meget nøje mærke til, hvad jeg gør, og følg mine instrukser præcist. At ignorere mine ord er at underskrive din egen dødsdom, for Opgaveleder Fizzule er MEGET velbevandret i krigerens og skurkenes veje.",
    [1199488202] = "$n, kig venligst på prøven af Vylestamm-ranken, som jeg tog fra hulerne, så du ved, hvad du skal lede efter...",
    [935464659] = "$n, tilkald mig igen, når du skal udføre ritualet igen.",
    [2119773424] = "$n, det var det! Jeg har endelig regnet den ud!",
    [717931119] = "$n, Sølvvinge-vagterne skal knuses!  Er du klar til Krigssang-Gulch?",
    [48074464] = "$n, Stormspids-vagten har brug for din hjælp i kampen mod Frostulv-klanen i Alterac-dalen, nu mere end nogensinde.  Mulighederne for ære og anseelse er også større end nogensinde! Vil du være med i slaget?",
    [838049931] = "$n, oversættelsen er færdig!",
    [2970110187] = "$n, dette kom til dig i morges.",
    [678773698] = "$n, under mosset ser dette hjerte ud som et frø!",
    [513354787] = "$n, at låse hemmeligheden bag disse halsbånd ligger hinsides mine evner...",
    [2597055506] = "$n, var det? Det er et ganske fint stykke arbejde, du har der. Jeg tager dig på og lærer dig at lave rustninger, der passer til Kong Magni selv.",
    [1412347321] = "$n, vi har nok forsyninger til at sætte landangreb i gang mod Kampens Mark.  Hvis du vil sende ordrerne, og din rang er høj nok, så tal med Sergent Jazra Blodsnerre i Frostulv-landsbyen.",
    [67974231] = "$n, vi har nok forsyninger til at sætte landangreb i gang.  Hvis din anseelse hos Stormspids-vagten er høj nok, så tal med Korporal Norreg Stormspids.",
    [343957985] = "$n, hvad venter du på?  Find Feltmarskal på Kampens Mark og giv ham angrebsordrerne.  Når han får ordrerne, vil han og hans tropper storme ind i Horden og ikke tage nogen fanger!",
    [1496865724] = "$n, hvad venter du på?  Find Feltmarskal Teravænne på Kampens Mark og giv ham angrebsordrerne.  Når han får ordrerne, vil han og hans tropper storme ind i Horden og ikke tage nogen fanger!",
    [2841704928] = "$n, du er klar til den ultimative opgave.  De flammende runer indridset i gulvet i Den Smeltede Kerne er kanaler til ildens rige, og deres tilstedeværelse er både en fornærmelse mod os og en kilde til kraft for Ildherrerne.  De skal slukkes!$B$BFor at slukke en rune skal du tage et hætteglas Aqual-kvintessens.  Hæld det på runen, så går dens flamme ud, hvilket gør den ubrugelig og svækker vores fjende!",
    [3903208835] = "$n, du har forstyrret min hvile!",
    [4089185421] = "$n, du vender tilbage!  Ånderne fra mit sidste måltid sagde, at du ville komme og se mig, og at vi ville drøfte forretninger.$B$BHar de ret?",
    [2237465622] = "$N.  Disse skaller fortæller mig meget, men jeg frygter, at der nu er rejst mange flere spørgsmål...",
    [3658467736] = "$R kød... skal æde!",
    [3652172065] = "%s forlader blokken, han holdt oppe i døråbningen, og kigger hen mod lokkemaden.",
    [2478538584] = "%s modtager $ns offergave og begynder at synge...",
    [3381655524] = "%s modtager relikvierne fra $n.",
    [4060428166] = "%s anerkender din underdanighed og vifter så afvisende med hånden mod dig.",
    [1039098747] = "%s aktiverer sig!",
    [694687077] = "%s tilføjer dissen til Blodblad-spirerne.",
    [1928993273] = "%s og hans invaderende styrker dukker op midt i en tumultagtig ildebrand i det nordvestlige Silitus.",
    [214115178] = "%s og Plyndrer Kær stormer ind i slaget...",
    [1339861109] = "%s og Plyndrer Kær lader deres ulve hvile sig lidt og drikke...",
    [2646619997] = "%s svarer på Blyg-Rotams kald.",
    [1299301518] = "%s virker fortabt i eftertanke.",
    [362748072] = "%s bevæbnet. Ørnerede-gryfon på vej.",
    [3115514691] = "%s bevæbner sig. T-minus 60 sekunder.",
    [732401472] = "%s ankommer!",
    [1081098465] = "%s samler runestoffet, urterne og det hellige vand til hestepanseret.",
    [2228080631] = "%s angriber et nyt mål!",
    [2286565295] = "%s angriber Kæmpens Banner!",
    [1836239765] = "%s angriber pikken!",
    [1267939853] = "%s angriber!",
    [71302419] = "%s forsøger at besværge Dødspagt over sine tjenere!",
    [2476427663] = "%s forsøger at få hjælp!",
    [2101560904] = "%s forsøger at løbe væk i frygt!",
    [2195741828] = "%s gøer i forventning.",
    [766595392] = "%s bliver omtåget",
    [3741286444] = "%s bliver rasende over at se en unge dø!",
    [1054177436] = "%s bliver rasende!",
    [140759761] = "%s bliver udmattet!",
    [2169810524] = "%s begynder et skabelsesritual...",
    [1996563328] = "%s begynder en fremkaldelsesbesværgelse...",
    [518003839] = "%s begynder at støbe en modbesværgelse...",
    [1919980657] = "%s begynder at messe en mærkelig besværgelse...",
    [361181886] = "%s begynder at messe, mens han blander brøndstenene og ambrekornene foran Stammeilden.",
    [2953661549] = "%s begynder at messe...",
    [3689837376] = "%s begynder nedtællingen.",
    [4276481152] = "%s begynder at fremstille...",
    [4243793033] = "%s begynder at rode i apotekerens ejendele.",
    [4287423744] = "%s begynder at lede i sin rygsæk...",
    [1282966290] = "%s begynder ritualet.",
    [450162769] = "%s begynder at fikle med brillerne foran stenen.",
    [243520324] = "%s begynder at udsende røg og fatter ild! Du får en fornemmelse af, at du bør LØBE!",
    [1629895608] = "%s begynder at boble!",
    [4198965124] = "%s begynder at besværge en Stor Helbred!",
    [3969611168] = "%s begynder at besværge en kraftfuld besværgelse.",
    [1233882945] = "%s begynder at besværge en besværgelse, mens du tager kappen fra ham.",
    [1202734459] = "%s begynder at besværge en besværgelse på Grimklo.",
    [3159244458] = "%s begynder at besværge en besværgelse over hjerterne og tungerne.",
    [183895707] = "%s begynder at kanalisere sin energi og fokuserer på stenen.",
    [3719897271] = "%s begynder at kombinere krystaller i forskellige farver.",
    [2881056648] = "%s begynder at revne og briste.",
    [3510579792] = "%s begynder at revne og åbne sig...",
    [2328792567] = "%s begynder at fremstille...",
    [2455611316] = "%s begynder at danse.",
    [3818433409] = "%s begynder at grave...",
    [2932277945] = "%s begynder at drive hen...",
    [2723602995] = "%s begynder at flagre hurtigere med sine enorme vinger. Han gør sig klar til flugt.",
    [360034949] = "%s begynder at gløde og ryge!",
    [1182851020] = "%s begynder grådigt at sluge maden.",
