    [2473033908] = "Hvor er Ældre Himmelseer?",
    [1948115815] = "Hvor er Ældre Snekrone?",
    [3285266377] = "Hvor er Ældre Splitfjeld?",
    [280033778] = "Hvor er Ældre Stjernelysning?",
    [4239299254] = "Hvor er Ældre Stjernesang?",
    [1277572454] = "Hvor er Ældre Stjernevæver?",
    [3849732637] = "Hvor er Ældre Stenborg?",
    [2900943361] = "Hvor er Ældre Stenspir?",
    [3232017615] = "Hvor er Ældre Stormbryn?",
    [3583796781] = "Hvor er Ældre Tordenhorn?",
    [1355969261] = "Hvor er Ældre Vildmanke?",
    [1192213088] = "Hvor er Ældre Vindløb?",
    [1503004505] = "Hvor er Ældre Vindtotem?",
    [353911988] = "Hvor er Ældre Vinterhov?",
    [1945972955] = "Hvor er alle?",
    [984929586] = "Hvor er Feltmarskal Teravænne?",
    [4209168505] = "Hvor er han? Gå ind ad næste dør, til Legendens Arme. Han smeder særlige våben til store helte dér. Ær ham, så viser han dig måske, hvordan man smeder legendernes ting.",
    [345542654] = "Hvor er det, I gerne vil hen $g dreng : pige;? For blot få mønter kan mine gryffer få jer derhen hurtigere end selv den hurtigste hest.",
    [2867232205] = "Hvor er Auktionshuset?  Det ligger lige ved Jernsmedes porte, når I træder ind i vores fine by.  I finder det lige over for Hvælvet.",
    [2616625430] = "Hvor er Frostulv-kvartermesteren?",
    [4097375361] = "Hvor er nøglen til denne lås?",
    [1906330400] = "Hvor er Sølvhånden?  Vi har brug for deres hjælp!",
    [1210290937] = "Hvor er Stormspids-kvartermesteren?",
    [3438528618] = "Hvor er Tirts assistent?",
    [2256236811] = "Hvor er Un'Goro-krateret?",
    [168096276] = "Hvor er Krigsherre Krom'zør?",
    [2137186641] = "Hvor er Krigsmester Garrik?",
    [1769035202] = "Hvor er dit Stationsmedaljon, lille ven?  Du må ikke tale med en hertug uden bevis for din titel...",
    [4119960816] = "Hvor skal jeg lede efter Ekko?",
    [2626150813] = "Dér hvor de to elskende faldt, ville et træ blomstre. Alverne kalder det Hjertetræet. Det vil helt sikkert tjene dine formål.",
    [19665864] = "Hvortil gå? Hvad gøre? Så mange valg, der alle ender i smerte, ender i død.",
    [1485376415] = "Dér hvor Trolde og spedalske gnomer strejfer rundt, står vores hjem - Nisseborgen.$B$BVores familier gik tabt, vores hjem blev fordrevet. Spredt for vinden.$B$BÅh, hvor jeg længes efter de sorgløse dage i Nisseborgen, men de dage er forbi. Vi må gøre modstand! Vi må redde Nisseborgen!",
    [3497360824] = "Hvor var jeg? Åh ja, så vi blev taget til fange. Mine elitevagter blev henrettet på stedet. De skånede mig og førte prinsessen væk med væder. Jeg blev ført til forvaringshallerne i Slaggruben og derefter overført til dette fængsel.$B$BJeg kan kun antage, at jeg stadig er i live, fordi de ønsker at afpresse en løsesum for mit ynkelige liv. Eller måske af grusomhed, som en måde at lade mig spille de begivenheder, der fandt sted i mit sind, om og om igen. Anger er den grusomste fangevogter af alle, $r.",
    [3355236197] = "Hvor skal vi hen?",
    [3618224721] = "Hvor vil du gerne flyve hen?",
    [1670213534] = "Hvor er mit flæsk?",
    [3624610157] = "Hvor er min snurretop? Jeg havde den lige her et sted...",
    [2011282339] = "Hvor er resten af karlene?",
    [408772222] = "Hvor er vandet, Emma? Hent vandet, Emma? Hvis'et ikke var for mig, ville den flok ikke vide, hvordan vand ser ud.",
    [3806529529] = "Hvor... Hvor er jeg?",
    [1744725366] = "Puh! Jeg tror, jeg spiste for meget. Må løsne bæltet et par huller.",
    [378221796] = "Puh! Det var noget hårdt arbejde, $r. Jeg har ikke set Svøben så aggressiv siden...$B$B<Vagt Didder synker en klump.>$B$BSiden den sidste krig...",
    [2913613776] = "Puh... Jeg trænger til en smøg og et fint gnomkvinde-kys – ikke nødvendigvis i den rækkefølge!$B$BJeg har siddet fast i maven på det dér ting i månedsvis! Hvilken dag er det i øvrigt? Ah, glem det. Det eneste der tæller er, at jeg endelig er ude.$B$BJUHUUU!",
    [3236230617] = "Hvilken slagmark har du interesse for?",
    [7039161] = "Hvilken slagmark søger du din herlighed på?",
    [2655437767] = "Hvilken klasse-træner leder du efter?",
    [3568520498] = "Hvilken klasse-træner mon ye leder efter?",
    [198420833] = "Hvilken skal jeg spise først? Så svært at vælge. De lugter alle så lækkert...",
    [2013405349] = "Hvilken erhvervstræner leder du efter?",
    [3759860179] = "Hvilken erhvervstræner mon ye leder efter?",
    [587887715] = "Hvilket erhverv?",
    [788448651] = "Hvilken træner søger du?",
    [2125740298] = "Hvilken vej skal du gå? Tja, det eneste råd jeg kan give er, at du tager hvilken vej du vil!$B$BJeg kan ikke huske noget!",
    [1101218007] = "Det ville jo forklare, hvorfor du sidder i en fængselscelle nederst i et bjerg, ikke, dværg?",
    [2748658982] = "Selvom Sindra ikke er så boblende som hendes eliksirer, er hendes venlige væsen velegnet til at lære sit håndværk fra sig.  Du finder hende lige øst for Kroen i Dolanår.",
    [1799194428] = "Mens Greta fokuserer sin energi på genopretningen af Jaedenar og dem, hun mener er mest ansvarlige for korruptionen her i Ondskoven, bruger jeg min tid på at undersøge de effekter, korruptionen har haft på landet.$B$BHvordan har den påvirket landets væsener? Hvad skal der gøres for at standse deres smerte og lidelse?$B$BDesværre går korruptionen så dybt, at evig søvn alt for ofte er svaret.",
    [3012674707] = "Mens jeg lever for at tjene Moder Jord og Horden, kan jeg ikke lade være med at føle mig en smule nervøs, nu hvor vi har samlet alt, vi har brug for. Vi har i det mindste lidt tid, indtil Alliancen er færdig med deres indsamlingsarbejde. Derefter skal det hele sendes til Cenarion-fæstningen i Silitus, og krigen vil nok følge kort efter.",
    [3534640845] = "Mens det er sandt, at Alliancen har fuldført alle sine krigsindsatsopgaver, lad dig ikke slå ud af det, $r. Tiden er af største vigtighed, men vi foretrækker langt mere, at du hjælper med Hordens indsamlinger nøje og grundigt. Det forekommer mig bedre end at begå en fejl, der kunne koste nogen livet, når krigen for alvor begynder. Er du ikke enig, $c?",
    [280265738] = "Mens min bror, Drazial, fokuserer sin analyse på bæsternes mere fysiske natur i de hærgede lande, har jeg en tendens til at fokusere på dyrelivets mere hjernebaserede og åndelige sider.$B$BDet er rigtigt, at bæsterne udviser ekstremt usædvanlig styrke, smidighed og udholdenhed, men nogle af dem besidder også stor intelligens og regenerative evner, som ikke er bundet til deres fysiske væsen.$B$BMåske ville du være interesseret i at hjælpe med at fremme min forskning, $r?",
    [1851479097] = "Selvom intet kan ændre fortiden, kan tiden hele alle sår. Tak, fordi du viste mig, at det er muligt, $n. Jeg ønsker dig alt godt.",
    [1583038428] = "Selvom Theramøre er berømt for sin enestående træning af krigere, er jeg bange for, at jeg ikke kan hjælpe dig.",
    [2858172845] = "Selvom der ingen Ingeniørtræner er i Gryde-by, findes der en nede i Undergrunden.  For at komme derhen skal du gå til bagsiden af Ruinerne af Herrelande syd for byen og tage elevatoren ned.  Når du kommer derhen, så spørg en Undergrunden-vogter om mere præcise anvisninger.",
    [868473188] = "Selvom vi ingen Alkymitræner har her i Blodhov-landsbyen, er der en i Tordenklippe mod nord.  Følg vejen derhen og spørg en af Skrænt-vagterne om anvisninger, når du kommer op til toppen.",
    [433068042] = "Selvom du måske prøver at få det til at virke, vil I til sidst gå hver jeres vej.",
    [2449552779] = "Pisksmæk",
    [412423964] = "Hvirvelaksis!  Jeg har din scepter!  Jeg befaler dig at træde ind i denne verden!",
    [2832580316] = "Hvid sikkerhedskort-indsættelse vellykket...$B$BUdleverer sikkerhedsniveau beta-enhed.\n\n01010011 01110000 01101001 01101100 00100000 01101011 01110010 01101001 01100111 01110011 01110011 01110000 01101001 01101100",
    [3352442167] = "Hvidrække-posten startede som en lille jagtlejr... Nu vil alle slå sig ned og kalde dette hjem.$B$B<Motega trækker på sin skulder>",
    [4089050830] = "Hvem er Skaberne?",
    [3303886671] = "Hvem er Jordvæsnerne?",
    [1401426490] = "Hvem er du, og hvorfor forstyrrer du mig? Åh, rigtigt – eliksirelev. Ja. Hvad kan jeg gøre for dig?",
    [696302270] = "Hvem er du?  Hvor er jeg?  Jeg føler mig... så svag...",
    [3627295463] = "Hvem er du? Hvad vil du have fra mig?",
    [1443590981] = "Hvem kontrollerer Østlige Frostulv-tårn?",
    [2181837472] = "Hvem kontrollerer Koldtand-minen?",
    [2730585790] = "Hvem kontrollerer Dun Baldrian Nordbunkeren?",
    [3364389806] = "Hvem kontrollerer Dun Baldrian Sydbunkeren?",
    [3014399933] = "Hvem kontrollerer Frostulv-kirkegården?",
    [886912598] = "Hvem kontrollerer Frostulv-lettelseshytte?",
    [3394803801] = "Hvem kontrollerer Isblod-kirkegården?",
    [905923001] = "Hvem kontrollerer Isblod-tårnet?",
    [3630248801] = "Hvem kontrollerer Isvinge-bunkeren?",
    [44937341] = "Hvem kontrollerer Jerndyb-minen?",
    [1282910587] = "Hvem kontrollerer Snefald-gravpladsen?",
    [3848462783] = "Hvem kontrollerer Stenhjerte-bunkeren?",
    [1875694695] = "Hvem kontrollerer Stenhjerte-gravpladsen?",
    [2241367004] = "Hvem kontrollerer Stormspids-hjælpestationen?",
    [3831188898] = "Hvem kontrollerer Stormspids-kirkegården?",
    [4086106947] = "Hvem kontrollerer Vestlige Frostulv-tårn?",
    [2224870385] = "Hvem kontrollerer Tårnpegen?",
    [1717594704] = "Hvem tør angribe Sølvvinge-forposten?!?",
    [3196628844] = "Hvem tør vække Akvementas?",
    [4160867671] = "Hvem tør vække Arkedas? Hvem tør trodse Skabernes vrede?",
    [3712080244] = "Hvem tør forstyrre Eldre'Thalas' hellighed? Mød mig, I kujoner!",
    [1252370172] = "Hvem vover at forstyrre mig?  Dø, $n!",
    [2544326236] = "Hvem vover at forstyrre min meditation?",
    [138257844] = "Hvem vover at forstyrre vores herre?",
    [2952707184] = "Hvem vover at blande sig i Defias-broderskabets anliggender?  Dø, $C!",
    [2382430603] = "Hvem vover at blande sig med Arugals Sønner?",
    [3676148642] = "Hvem vover at trænge ind på Sortklippe-klanen?  Død over denne $R!",
    [2282291286] = "Hvem vover at stjæle mit dyrebare ridedyr?  I skal betale for jeres frækhed, dødelige!",
    [3962342033] = "Hvem vover at træde ind i mit domæne!  Kom!  Kom, og bliv forbrugt!",
    [1787354270] = "HVEM VOVER AT TILKALDE LOKHOLAR?",
    [2844640310] = "Hvem vover at tilkalde mig?",
    [33213096] = "Hvem vover at tilkalde tomhedens kraft?",
    [175607957] = "Hvem vover at nærme sig denne kedel?  Smag på mit mørke sværd!",
    [615423856] = "Hvem vover at udfordre mig i mit domæne?!",
    [2505214192] = "Hvem vover at forstyrre min evige hvile?  Jeres død vil være langsom og smertefuld!",
    [2605200664] = "Hvem vover at provokere budbringeren fra Edwin Van Kløft?  Dø, $R!",
    [3956023460] = "Hvem vover at søge mig ud?!",
    [1024163883] = "Hvem vover at krænke helligdommen i mit domæne? Vær advaret: alle, der overtræder her, er dømt!",
    [3639357520] = "Hvem vover?! Jeg vil tilintetgøre dig!",
    [990853419] = "HVEM VOVER?! Du skal tilintetgøres!",
    [2000980486] = "Hvem skal jeg dræbe? Peg mig bare i deres retning, Kommandør.",
    [1187632017] = "Hvem skal jeg dræbe?",
    [3679471671] = "Hvem går der?",
    [3818424134] = "Hvem har forstyrret gudindens alter?",
    [3591917990] = "Hvem har den hurtigste bil?  Hvem ved det?!?",
    [2331418652] = "Hvem har tilkaldt Amanen?",
    [1456152194] = "Hvem er den forudsigelige, udyr? Tror du virkelig, at vi ville tilkalde dig oven på Malfurion? Din forløsning kommer, Eranikas. Du skal renses for denne galskab - denne korruption.",
    [2866757503] = "Hvem er denne $c, der træder frem for Søshires Hof i Stormvinds rige?  Oplys dit ærinde inden for denne by, $R.  Orktruslen mod riget er alt for stor til at spilde tiden på tom snak.",
    [4107988466] = "Hvem er denne Lar'korvi, du talte om?",
    [3365800407] = "Hvem er denne blotte $r, der blander sig i det, der er forbi?  Må sagnet om Stalvan dø sammen med dig!",
    [734534130] = "Hvem er denne svage $C, der udfordrer min styrke?  Dø, tosse!",
    [640661228] = "Hvem er denne svage $R?  En ækel indtrænger, siger jeg.  Dø, tosse!",
    [1299111264] = "HVEM DRÆBTE GOR'TESH!?!? HVEM GJORDE DET HER?!",
    [2415638430] = "Hvem ved? Under alle omstændigheder var det sidste jeg så til hende. Måske kan Frankal give dig bedre oplysninger.$B$BIkke for at afvige fra emnet her, for jeg er sikker på, at arbejdet du udfører for Kommandøren er vigtigt, men vi er på sporet af noget kæmpe stort her. KÆMPE STORT! Vores anmodninger til Jernsmede om en hær er hidtil faldet på døve ører. Tilsyneladende er vi for tyndt spredt til at beskytte riget, eller sådan noget vrøvl. Når du har taget din rapport tilbage til Kommandøren, så kom tilbage hertil med nogle venner. Vi har brug for din hjælp!",
    [1430874722] = "Hvem siger, at orker ikke er kloge? Der skal en masse hjerne til for at være ingeniør!",
    [1589094471] = "Hvem sendte dig hertil? Du er ikke klar til min undervisning endnu! Du får besked, når du er klar.",
    [3221205321] = "Hvem ville være dum nok til at betræde Stor-Formandens tårn?",
    [2500867146] = "Hvem er næste?",
    [645525163] = "Hvem er rigets mest populære helt, spørger du?  Nå, her er de aktuelle stillinger!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BHorden i alt: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BAlliancen i alt: $2206w$B$BHvis du vil afgive din stemme, så sørg for at aflevere dine gaveindsamlinger!",
    [2133651389] = "Hvem er der?",
    [1817180367] = "Hov nu, $c, Pele'kejki tænker, at du ikke ved alt det stof, der er på vej til Silitus. Pele'kejki sagde, at det sidste af det ville komme derhen om mindre end $2113w dage, og så vil en vildfaren tosse slå på gongongen uden for Ahn'Kiraj-portene for at åbne dem og starte krigen.",
    [2513472983] = "Hov nu, $c, Pele'kejki tænker, at du ikke ved alt det stof, der er på vej til Silitus. Pele'kejki sagde, at det sidste af det ville komme derhen om mindre end en dag, og så vil en vildfaren tosse slå på gongongen uden for Ahn'Kiraj-portene for at åbne dem og starte krigen.",
    [3843593814] = "Hov! Se lige den plet i midten!",
    [2877649420] = "Hov! Det her er langt mere, end jeg havde regnet med, du står alene, Slank!",
    [1067386828] = "Hov!...Hov!...Ahh!  Det var tæt på.  Hovsa!...Åh smerten, kære dreng, smerten!",
    [2664405501] = "Hov, hov, min ven. Et øjeblik...",
    [1997405185] = "Hov, hov, stop lige, Dadånga-pige.",
    [3204693197] = "Hov...Hov..Aaaaahhh!",
    [1905141010] = "Hovsa!",
    [2196166592] = "Hvorfor ... vil du ... bare dø-øøø?",
    [753100383] = "Hvorfor går vi den vej?",
    [2402008928] = "Hvorfor er du her, $n?  Har du bly i støvlerne?$B$BDu har angrebsordrerne - Krigsmester Garrik har brug for dem i Kampens Mark, før han kan indlede sit angreb!  Af sted!",
    [1249564587] = "Hvorfor er du her?",
    [2441050941] = "Kan vi ikke bare forskyde arrayet for at kompensere for variansen i fluxen?",
    [2180562787] = "Hvorfor lave mad, når alt smager af aske i munden?  Hvis du altså har en gryde tilbage. Meget godt, tag mod syd fra Gryde-by til Undergrunden og spørg en Undergrunden-vogter der efter yderligere anvisninger til deres Madlavningstræner.  For at komme derned kan du tage elevatorerne ned fra bagsiden af Ruinerne af Herrelande.",
    [2423506305] = "Hvorfor skulle jeg sidde fast med denne frastødende, kraftløse undskyldning for en heksemester?",
    [2984309172] = "Hvorfor dræbte du mig, $n?",
    [1882215216] = "Hvorfor samlede Herre Vyletunge ikke begge dele af scepteret til ét?",
    [2317189206] = "Hvorfor tog du ikke bare af sted?",
    [4184737898] = "Hvorfor går vi altid den samme vej?",
    [2518231898] = "Hvorfor skal vi overhovedet lære det her?",
    [756160183] = "Hvorfor jager du mig, din mekaniske Yeti?! HVORFOR?!",
    [2918300687] = "Hvorfor bliver du ved med at sige, at han døde? Hvem har fortalt dig, at han døde? Jeg har aldrig sagt, at han døde.$B$BHan forsvandt, det er alt.$B$BDu må vide, at vi tilsyneladende var havnet midt i en stor kamp mellem ork og Mørkejern-dværge. Orkerne, de snavsede, elendige hunde, de nu engang er, var ude tidligt og satte nogle fælder op og andre djævelske ting, som du sikkert ikke ville forstå.",
    [674996512] = "Hvorfor løber du fra mig, Lodder!",
    [95640237] = "Hvorfor siger du, at det her er et tilfælde, Rabbe?",
    [2570950674] = "Hvorfor tager vi ikke fat på dig nu, Hændel? Dame Stoltmoor vil tale med dig tilbage i tårnet.",
    [2956419686] = "Hvorfor prøver I ikke igen uden jeres billige taktikker, pyrkier! Eller er I for store kyllinger???",
    [4184620729] = "Hvorfor går du og Stenknort ikke et sted hen, hvor I kan være alene...",
    [2323409580] = "Hvorfor prøver du ikke at kigge i Løvens Stolthed Kro?  Kokken dér kan måske lære dig et par gode opskrifter.",
    [1110474371] = "Hvorfor er du kommet hertil, $c?",
    [3912886505] = "Hvorfor har du gjort så forfærdelige ting?",
    [1399412316] = "Hvorfor har du kaldt mig frem så tidligt?  Jeg har ikke nået min fulde kraft endnu!",
    [2149812260] = "Hvorfor er Stormvind-vagterne ikke kommet?",
    [2611616918] = "HVORFOR er han i Sortklippe-dybderne?",
    [3392395915] = "Hvorfor er det, at små væsener som nisser altid er fascineret af større væsener?",
    [1805304131] = "Hvorfor er det, at der aldrig ligger en gyrokronatom og flyder, når man har brug for en?",
    [1143144807] = "Hvorfor ikke tilintetgøre dem med Aspekternes samlede magt?",
    [2728102831] = "Hvorfor nu, $r? Jeg kan bare ikke forstå det. Så meget arbejde, der skal gøres...",
    [335113688] = "Hvorfor skulle jeg gide at reparere fælden?  Hvorfor ikke bare fjerne vagten på den gammeldags måde?",
    [2450900478] = "Tak skal du have, mit kæledyr.",
    [3577935629] = "Hvorfor skulle du nogensinde ville skade mig!? Kom. Venner kan vi blive!",
    [2118652682] = "Hvorfor skulle du ville tale med Kaplag?  Glem det.  Led efter ham oven på hulen i Barberbakkens sydvestlige hjørne.  Bare pas på, at du holder hænderne i dine egne lommer!",
    [277505786] = "Din lille!",
    [4007704056] = "Din lille...",
    [2380293839] = "Hvorfor løber du væk? Vi gør dit lig til Svøben.",
    [1804950992] = "Hvorfor i alverden man vil forlade de solrige kyster og det krystalblå vand, forstår jeg ikke en brik af. Her nede er det som paradis. Men fortæl ikke det til min bror Zapatta, han er allerede bitter nok over at sidde fast deroppe i Tirisfal hele dagen. Denne Zeppelin sætter dig af i Orgrimgrad, så du ikke skal bekymre dig om at skulle lytte til ham klynke. Men hvis du kommer til Tirisfal snart, så tag min advarsel til dig og start ham ikke i gang.",
    [1837910860] = "Hvorfor, du ligner en almindelig gadeunge!",
    [3095497428] = "Hvorfor... det er meget sødt af dig.  Jeg forstår, at du frivilligt giver af din tid til Børnenes Uge, ikke sandt, $c?  Ja, du fortjener ros.  Det er afgørende, at vi husker dem, der har det svært - især børnene.$B$BJeg skriver gerne en autograf til dig.  Værsgo.",
    [2365378729] = "HVORFOR? Hvorfor skete det her ... for mig? Hvor var du, Tyrande? Hvor var du, da jeg faldt fra Elunies nåde?",
    [1668992867] = "Onde, onde dødelige! Skoven græder. Elementerne krymper tilbage for ødelæggelsen. Ivas må rense jer fra denne verden!",
    [525847294] = "Vildnisse er af natur magiske; denne kraft blev givet dem af gudinden.",
    [3014566603] = "Vil nogen venligst give min lille killing et godt hjem?",
    [2958548585] = "Vil mareridtet nogensinde ende?!  Jeg kan ikke tvinge mig selv til at vågne!",
    [1118260479] = "Vil de ubarmhjertige angreb fra Svøben aldrig holde op?",
    [2075198003] = "Vil du sprænge den dør nu?",
    [3312629227] = "Vil du hjælpe os i vores store nød ved Arathi-bækkenet, $c?  Chancen for øget ære og anseelse har aldrig været større, og din hjælp vil helt sikkert være med til at vende strømmen mod Skænderne.  Kan vi regne med dig?",
    [92314126] = "Vil du hjælpe?",
    [656765617] = "Vindrytter-mester",
    [289727731] = "Vinder! Vi har sgu en vinder her!",
    [1752209748] = "Vinterhov? Jeg hører, han har det godt i Bytteviken.",
    [1618719319] = "Med alkymi kan du omdanne fundne urter til heling og andre slags eliksirer.",
    [854419401] = "Med Adelgar til at holde mig forsynet kan jeg klare alt mit arbejde her uden at jage en eneste urt. Hvis jeg aldrig mere skal se naturens undere, bliver det ikke for tidligt.",
    [3752236065] = "Med al respekt, Krigshøvding - hvorfor ikke lade dem blive ødelagt? Styrker det ikke vores position?",
    [1649211887] = "Med al den kamp, vi udkæmper, har vi selvfølgelig en Førstehjælpstræner i Barberbakken.  Find Rårk inde i kasernen på østsiden af byen.",
    [4011275499] = "Med alle de skruer, Brask har strammet, tror jeg, han har sluppet et par af sine egne, hvis I forstår mig.  Alligevel har han stadig et godt hoved til at konstruere de mest forbandede apparater.  I burde tage over og besøge ham i Stålgrills Depot.",
    [1212362408] = "Med lidt held får vi nogle gode ar i dag.",
    [3119894344] = "Med Uro fældet er vejen fri til det sidste kammer. Jeg kan transportere dig derhen, hvis du ønsker det.",
    [836074531] = "Med fornøjelse. De her ting stinker!",
    [305833236] = "Med fornøjelse...",
    [3903117740] = "Med fornøjelse... lad mig bare nyde det her øjeblik et minut længere.",
    [2411114243] = "Med noget af den teknologi, som modige gnomer fik fat i, da de vovede sig ind i Nisseborgen, er det lykkedes mig at konstruere min største opfindelse:  Materie-transporteren!    Det eneste, jeg mangler nu, er en dygtig gnomisk Ingeniør, der kan bygge et kraftigt fyrtårn indstillet på transporteren.",
    [3852511993] = "Nu hvor kedlerne er brudt op, kan vi indføre modgiftsstoffet i omgivelserne.  Det burde give Svøben en smag af deres egen medicin, så at sige!$B$BTal med Alkymist Arbinton om oplysninger om de reagenser, der skal bruges i kedlerne.  Jeg står for alle rapporter om, hvordan vi samlet set klarer os med at vende pesten mod Svøben!",
    [3075410403] = "Nu hvor kedlerne er brudt op, kan vi indføre modgiftsstoffet i omgivelserne.  Det burde give Svøben en smag af deres egen medicin, så at sige!$B$BTal med Apoteker Tøvers om oplysninger om de reagenser, der skal bruges i kedlerne.  Jeg står for alle rapporter om, hvordan vi samlet set klarer os med at vende pesten mod Svøben!",
    [450293145] = "Med Moder Jords velsignelse begynder vi.",
    [635735125] = "Med kejserne fældet er den magiske beskyttelse, der blokerer for teleportering inde i templet, kraftigt svækket. Hvis du ønsker det, kan jeg flytte dig til kejsernes hule.",
    [1269611260] = "Med de klæder, Mi'Lynn syr, kunne man tro, at hendes nål var velsignet af Elunie selv.  Medmindre din nål er så velsignet, må du hellere besøge hende og lytte til hendes lærdomme.  Du finder hende på Håndværkernes Terrasse i det nordøstlige Darnassos.",
    [2940558019] = "Med Herre Varimatras' billigelse vokser Dødsstalkernes rækker. Flere klinger til at slå til mod vores fjender, når de mindst venter det.",
    [3649110517] = "Med din hjælp kan jeg undersøge disse tunneller.",
    [3830543456] = "Træk dine tropper tilbage, bror, så lover jeg dig en hurtig anden død!",
    [1631018958] = "Inden for denne ildcirkel må jeg besværge den besværgelse, der skal forvise de dræbte Hugtandsherrernes ånder.",
    [2844854082] = "Uden et formål vandrer de... Men mange finder tilbage til de hellige områder, som de engang svor at beskytte.",
    [4058669687] = "Uden kendskab til besværgelserne, der kræves for at forene de to dele, kunne Herre Vyletunge ikke bruge scepteret. Men nu hvor jeg er fri for forbandelsen fra Vyletunges korruption, kan jeg hjælpe dig, hvis du vil bringe mig de to dele -- både hovedet og scepterets stang.",
    [2546644049] = "Ulveryttere, til Frostdolk-passet!",
    [3192217350] = "Ulvene kommer hen ad denne vej, som om de flygter fra...noget.",
    [4163744487] = "Kvinder...",
    [2699178449] = "Der går ikke længe, før Mørkemånens Marked åbner.  Kom tilbage senere og tjek, om vi er færdige.",
    [1168858525] = "Juhu! Endelig kommer vi væk herfra. Det bliver dog hårdt. Hold øje med ballade.",
    [2153975258] = "Juhu, så kører vi! Alle har samlet alt, og det hele bliver luftbåret med zeppelin til Silitus, mens vi taler sammen. Det sidste skulle være der om mindre end et døgn. Når det hele er der, og scepteret er samlet, kan krigen mod de beskidte insekter begynde. Som man siger: 'Skib den!'",
    [1702596091] = "Vu Plings udholdenhed er simpelthen forbløffende.  Når jeg så ham øve sine våbenteknikker i timevis, fik jeg ondt af attrappen bagefter.  Jeg kan ikke komme i tanke om nogen, der er bedre egnet til at træne dig i væbnet kamp.",
    [3891240458] = "Juhu! Nu er de i gang!",
    [4102302520] = "JUHU!",
    [2708929525] = "JUHU! Klaret!",
    [1438962320] = "Ryget siger, at Vance Underdunkel har taget et fast værelse ovenpå i Galgeenden Kro i den sydøstlige ende af byen.  Jeg tror, han er lige ved læsesalen.",
    [1572145831] = "Arbejdsskrald!",
    [3912028179] = "Arbejd, I hunde! Læg ryggen i det!",
    [3127854070] = "Verden af Krigskunst og Coca-Cola (R) har slået sig sammen om at bringe dig iKoke-Verden af Krigskunst Sommerforfremmelsen.  Se efter koder under kapslerne på særligt markerede Coca-Cola-flasker.  Vend så tilbage hertil og indtast koden for at vinde en virtuel genstand.",
    [2708791255] = "Orm kommer på krogen, krogen kommer i vandet. Fisk er i vandet, vores fisk.",
    [122656675] = "Værdiløse $n!  Dine venner slutter sig snart nok til dig!",
    [1523672741] = "Hva' kan jeg gøre for dig?",
    [1822875017] = "Ville en flue uden vinger så kaldes en gang?",
    [998607739] = "Ville nogen af jer nægte jer selv sådan en død? Sådan en ære?",
    [1989244276] = "Ville det ikke være herligt, hvis du på en eller anden måde formåede at besejre mig, men ikke før jeg kunne ødelægge det eneste håb, Kalimdør måske har? Jeg er svimmel af forventning. Snart... Snart bliver det til støv.",
    [665388268] = "Kan du tro, at jeg i min mørkeste time, på højden af mit væsen, slog fejl?$B$BMens jeg flygtede fra den hensynsløse ødelæggelse, som de styrker, der overvældede os, forårsagede, var de eneste lyde, jeg kunne høre, skrigene fra mine soldater og mit eget hjerte, der hamrede hurtigt.$B$BEt lille stykke tid senere vendte jeg tilbage til Det Sønderrevne Land i håb om at redde mine mænd og genoprette min ære. I stedet blev jeg taget til fange og tortureret, indtil jeg var død.$B$BDet, jeg fandt ud af under min inkvisition og den efterfølgende pine, var rystende.",
    [1600128713] = "Vil du have en flyvetur til Rutteran-landsbyen, sponsoreret af Cenarion-kredsen?",
    [3678761484] = "Vil du have en flyvetur til Tordenklippe, sponsoreret af Cenarion-kredsen?",
    [3448898499] = "Vil du have noget mere at spise, herre?",
    [1003668280] = "Vil du hellere betro dine varer til en kobold?",
    [1481360800] = "Ville-være-indtrængere, frygter jeg.",
    [4081467106] = "Ville det ikke få vævet til at gå i opløsning, hvis det ikke var forankret ordentligt, før støbningen starter?",
    [2918030964] = "Wow!  $n, det drømmestøv er stærkt stads!",
    [3873428952] = "Wow!  Disse tønder er fyldt med stærkt stads!  De løfter mig lige ud af støvlerne!",
    [3502427241] = "Wow! Ser ud til, at vi allerede har samlet alt det tykke læder, de tror, vi får brug for. Det gik hurtigt. Du ved, der er nok andre herude, der kunne bruge din hjælp, hvis du vil række dem en hånd.",
    [3461416130] = "Wow! Vi klarede det... ved ikke helt hvorfor vi troede, vi havde brug for din slags. Tal ikke desto mindre med Smidt Skrableskrue; han vil give dig din løn!",
    [585636828] = "Wow, alt dette for en kærlighedseliksir. Håber, han er det værd.",
    [602344663] = "Wow, det er 3 grader Krakkenhed. Bliv ved med at lede.",
    [1184097014] = "Wow, den her er bare ubrugelig. Lad mig prøve igen.",
    [3691395168] = "Wow, du er sindssyg, ikke?",
    [2534916263] = "Wulan i Skyggebytte-landsbyen kan sælge dig \"Ekspertkogebogen\".  Den skal du bruge, hvis du vil forbedre dig selv.",
    [436242031] = "Vushulay, Stormheksen.$B$BHendes magt er himlens, regnens og den splintrede jords magt.  Må hun igen herske som mor over Gurubashi.  $B$BVushulay bor nu langt herfra.  En dag vender hun måske tilbage...",
    [2858679403] = "Vushulay, Stormheksen.$B$BHendes magt er himlens, regnens og den splintrede jords magt.  Må hun igen herske som mor over Gurubashi.$B$BVushulay raser nu nær galskabens rand.",
    [2508878586] = "Xon'te vil stalde dine ekstra kæledyr.  Find ham i Æresdalen ved stalden mellem arenaen og Jægerens Hal.  Og skrid nu!",
    [188088919] = "Ja mand, du vil have Jandines Arboret.  Sagde jeg lige det?  Ære være!  Jeg må være træt!  Følg de træ-trapper bag Asorans Marked i Visdommens Dal op i Slæbet, så finder du Jandine deroppe på øverste niveau.",
    [1789979365] = "Du følger måske ikke Lysets veje som en Ridder af Sølvhånden, men du kan altid bede os om hjælp.",
    [809575327] = "Ja mand, jeg er Snadrins assistent.  Dette frivillige arbejde er min måde at komme igennem Heksedoktor-stimen på.  Eftersom du hjælper ham, hjælper jeg dig gratis.  Hvad skal der lappes?",
    [357733626] = "Jo rigtig! <PH>",
    [2732704996] = "I får et par minutter til at vågne, men lad os snart komme i gang.",
    [2587194632] = "Jo, jeg ved det, det ser ud til, at vi allerede har alle de mithrilbarrer, vi skal bruge til krigen. Men du ved, der er stadig masser af folk herude, der nok kan bruge din hjælp lige nu.  Tak, mand.",
    [3441618234] = "Jep, jeg kan lære dig at fiske.",
    [1072985051] = "Jo, han er død, det er rigtigt.  Det gør dig til den nye konge... ja, jer alle sammen!  Gordøk er nu jeres, chef!  I burde snakke med mig, så I kan lære alt, der er at vide om at være konge!  Jeg var... er hans assistent!  Ja, det er derfor, de kalder mig den snedige!",
    [2683417952] = "ARRRG! Sjaskebi, hvad har du gjort?! Han er blevet skør! Luk lemmene! Hiss masten! ARRRG! Hver mand for sig selv!",
    [3441305637] = "Arrr... du må hellere ikke spilde min tid, makker!",
    [2223009047] = "Yaw Skarpmanke venter dig i den nordlige udkant af landsbyen.  Han kan lære dig jægerens veje.",
    [413831918] = "YAW! Øh, til frontlinjen med dig!",
    [99837867] = "Yawww!",
    [437224426] = "Jubii!",
    [1421250107] = "Du har brug for vejvisning, $gdreng : pige;?",
    [2870055229] = "Du generede mig med det? Du ville have det bedre med at binde en død kanin på ryggen og løbe gennem en trolds hule, end at bære det stykke skrald.",
    [1751821369] = "Du kan nok høre Tognar hamre løs på ambolten, når du er i Kharanøs.  Men hvis du ikke har fået voks ud af ørerne for nylig, så tag dig da bare en tur ind i smedjen.",
    [3583011725] = "Du har min godkendelse, $n. Du kan smede klinger bedre end nogen, jeg har trænet i årevis. Hvis du vil lave et rigtigt våben, skal du dog tale med Myolør Sønderraseri. Den dværg vil sætte dig på rette spor.",
    [3441921664] = "Du har lidt færdighed med hammer og ambolt, men ikke nok. Gå hen og tal med Dansker Lindgren, han gør dig klar til at lære det, jeg har at lære dig.",
    [2103917931] = "Du har lidt færdighed i våbenfremstilling $g dreng : pige;,meget imponerende faktisk. Tag nu en hammer, så lad os se, om du kan smede et rigtigt våben.",
    [2026270073] = "I har smedens udseende over jer. Sod under neglene, stål i knoglerne. Ja, smedeblod i årerne, det er ingen tvivl om. Det betyder, at I er kommet til mig for at lære et par ting, så grib en hammer, $g knægt : pige;. Lad os se, hvad jeg kan lære jer.",
    [752331556] = "I ved mere end jeg gør, det er sikkert. Men tag en snak med min far. Han vil have jer til at bevise jer selv, men han er faktisk en fin lærer. Hans navn er Rådgath, og I finder ham ved ambolterne, hvor han smeder stål for gamle Bengus.",
    [1239119534] = "I lærer hurtigt, $g knægt : pige;, meget hurtigere end jeg kan følge med. Hvis I vil fortsætte jeres træning, foreslår jeg, at I besøger min lærer. Hans navn er Rådgath, Rådgath Stenskæg, og I finder ham i Jernsmede ved Den Store Smedje.",
    [1370850469] = "I ser lidt fortabt ud.  Kan jeg hjælpe jer med at finde noget?",
    [1527691342] = "Leder I efter Hogrål?  Nå, har I kigget i krostuen?  Åh!  Hvis I leder efter en skurk, og en dværg af slagsen oveni købet, så skal I starte på kroen!  Gå og tag et kig, for pokker.",
    [1594911128] = "I ved måske ikke det, men ud over at være en dygtig skrædder er Jormund også en kæmpedræber!  Han må have hørt nogle af os dele historier, for han råbte, at han havde slået syv ihjel med ét slag!  \n\nI bør besøge hans butik på nordsiden af Den Store Smedje og se, om han vil fortælle jer historien!",
    [3208410751] = "Har I brug for træning?  Nå, Azar Stærkhammer er altid klar til at vise de yngre korsriddere et par ting.  Hvorfor går I ikke og besøger ham på Tordenbryg-destilleriet.",
    [1325878081] = "I bør være på vej, $g knægt : pige;. Mit kæledyr her er sulten, og han kan lide lugten af jer.",
    [1454495530] = "I bør tjekke Stålgrills Depot for Brask.  Når han ikke fikler med en mærkelig apparat, snakker han som regel med pilotene om deres damptanks.",
    [1380811154] = "I bør kigge forbi i Jernsmede, hvis I har sat jeres sind på fortryllelse.  Jeg tror, jeg så en butik ved grif-mesteren, sidst jeg var deroppe.",
    [1466366327] = "I er sikker på, at I ikke vil lære at blive kriger?  Nå, det er jeres hud på slagmarken.  Hvis I virkelig vil lære at vifte med fingeren, så tal bedst med Magis Gnistkappe på Tordenbryg-destilleriet.",
    [214277980] = "I vil trænes i brugen af et våben, ikke sandt?  Nå, stå ikke der med hængekæbe, tal op, $gknøs : pigebarn;!",
    [2996724137] = "I finder ikke en grif-mester hvor som helst i Dun Frostbakke, $gknægt : pige;.  I må til Jernsmede, hvis I vil tage en grif et sted hen.",
    [3492027472] = "I finder ingen skindere herude i Dun Frostbakke, $gknægt : pige;, de findes mest i Jernsmede, hvis I vil have træning.",
    [2486760973] = "I kommer til at feste på mit blad denne Vinterslør!  Jaargh!",
    [1263573242] = "I finder helt sikkert Maxan Ambol derinde på Tordenbryg-destilleriet, hvor han hælder et par stykker ned.  Hvorfor tager I ikke en pint og ser, om han vil lære jer noget nyt.",
    [3793229572] = "I er en fin fortryller, uden tvivl! Nu er det tid for jer at komme videre. Jeg vil have jer til at tale med Gimble Tidseldunsen, ovenpå. Han er lidt af en særling, men han vil pege jer i den rigtige retning herfra!",
    [1134246850] = "I er ud over min evne at lære, $n. Gå og plag Tælle Bærbrus; hun er en gnom, der bor i Tinkerbyen i Jernsmede. Og siden du alligevel er på vej derop, så giv Kaja min kærlighed.",
    [2298654119] = "I er kommet til det rette sted, $gknægt : pige;!  Folk kommer hertil fra hele verden for at blive trænet til smed.  I finder Bengus Dybsmedje hamrende løs på et ambolt midt i vores fine by, lige ved selve Den Store Smedje.",
    [2699695491] = "I har lidt færdigheder på jer. Nok til at lære jer et par ting, vil jeg vædde på. Lad os se, hvad jeg kan lære jer, skal vi?",
    [2290290428] = "Hva'?",
    [3213349853] = "Ja ja, jeg ved godt, at Dadånga ikke kan lide røg.  Men ud fra lugten at dømme, lader det til, at Dadånga heller ikke kan lide at bade.",
    [1491115595] = "Ja! De klarede det! De fangede sprite-pileskytterne klarede det!",
    [1167764293] = "Ja, jeg vil ikke være her, hvis Myzrael vågner.  De siger, hun har et ondt temperament...",
    [1257023544] = "Ja, jeg skal selv aflevere nogle ting.  Find det ved at gå nordpå ad vejen til Orgrimgrad og spørg en af Orgrimgrad-fodsoldaterne der.",
    [389304076] = "Ja, jeg viser dig et par ting. Vi må se, hvordan du klarer dig, måske overrasker du mig!",
    [2341797010] = "Ja, jeg har hørt gennem rygtebørsen, at jeg nok får se dig før eller siden. Men jeg tager ikke bare hvem som helst, jeg skal først sikre mig, at du har, hvad der skal til. Er du villig til at tage min lille prøve og finde ud af det?",
    [1557560629] = "Ja, ingen problem, $n! Undskyld... troede, du var færdig med den allerede.",
    [2142737245] = "Ja, okay, chef. Ingen problem.",
    [3001722598] = "Ja, selvfølgelig, gå til gamle Storfaderen Vinter og fortæl, hvad du ønsker dig til dette Vintersløret.$B$BHo ho, skynd dig.",
    [101302565] = "Ja, det må være Austil de Mæthe.  Han hænger altid ud i krostuen i den sydøstlige ende af byen.  Den hedder Galgeenden Kro, den kan du ikke overse.",
    [3275636339] = "Ja, du kender et par ting! Hvis du vil lære mere, må du tale med Georgio Bolerojakke i Stormvind.",
    [372281175] = "Ja, du finder altid Clyde Fiskesen fiskende ved bredden af Klarvandssøen lige øst for Gryde-by.  Pas bare på psykopaterne med masker, mens du er derude.  Vi måtte lukke børnenes sommerlejr sidste år.",
    [1012829454] = "Ja, du er en rigtig klogeskalle.  Hvor klog tror du egentlig, du er, Glip'kik?",
    [1056688924] = "Ja? Selvfølgelig er jeg smed. Hvad, tror du, at dværge er de eneste, der er værd deres vægt i ambolte? Fint, så lad være. Gå og find en dværg til at hjælpe dig!",
    [1454625511] = "Ja? I afbrød mig, så I må have en forbandet god grund til det.",
    [553060268] = "Års kvalitetsavl og masser af omsorg giver mig æren af at vise dig disse heste!  Tag dig venligst tid til at overveje dem som dit ridedyr.  En hest er en ledsager for evigheden, ven.  Sælg dig ikke selv for billigt - hent dit ridedyr her i dag!",
    [1421623899] = "Jiiii haaaw! Mulveriks flåde er klar til at rulle. Alle kampdygtige Horde-soldater skal anmode om et fyrtårn og gøre deres yderste for at plante det, så mine Krigsryttere kan finde målet til luftangrebet.",
    [3489419035] = "Indsættelse af gult sikkerhedskort vellykket.  Udleverer sikkerhedsniveau chi-enhed.\n\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001",
    [1743138551] = "Jep, du leder efter Christopher Dragekul i Handelskvarteret.  Han står på den østlige platform.",
    [2324615959] = "Jep.",
    [2745857691] = "Jep. Har du aldrig hørt om Jernfjende? Den legendariske orkedræbende hammer? Jep, jep, det var gamle Vindsors hammer. Han fortalte mig, at Franklorn Smedeværk selv lavede hammeren til sin store, store, store farfar. DEN Franklorn Smedeværk: Mørkejernet, der stod bag stenbåret arkimetekt... byggeværk-ting. Han sagde også, at hammeren havde en tvilling, som Franklorn beholdt for sig selv. Tror han kaldte den Jernfel eller sådan noget.",
    [285642635] = "Du er en velsignelse, uden tvivl, $n. Tak.",
    [3419694908] = "Leder I efter en alkymitræner?  Jeg kommer lige derfra.  I finder Frk. Bærbrus nede i Tinkerbyen, hvor gnomerne samles.  \n\n::sukker:: ...hvorfor, hvorfor tog jeg ikke den blå eliksir.",
    [3395367790] = "Vil I lære at bruge et nyt våben, ikke?  Nå, I bør tale med Bixa eller Bulivyf i Tømmerlinjens Våbenlager, så $gknægt : pige;.  De kender deres våben fra økser til... øh... tohåndssværd.",
    [3045172855] = "I er ingen kriger... I ville ikke engang holde en dag under min træning!  $B$BEn $c, der tror $ghan er : hun er; en kriger.  Ha!",
    [4163690241] = "Jeres færdighed er ikke uden fortjeneste, men jeg må stille jer én sidste prøve, før jeg tager jer med.",
    [1455541544] = "Ja $g herre : frue;! Jeg har fået ordre om at rapportere, at Alliancen har samlet alt det krigsmateriel, der er nødvendigt. Jeg har fået at vide, at vi blot venter på, at Horden færdiggør deres del, hvorefter alt sendes til Silitus. Tak $g herre : frue;!",
    [1508373425] = "Ja $gbror : søster;, hvordan kan jeg hjælpe dig?",
    [371899256] = "Ja $gherre:frue;.",
    [1671075588] = "Ja, det er jeg.",
    [4221113120] = "Ja, jeg har tjekket, jeg mangler det venstre stykke!",
    [4220787442] = "Ja, jeg har tjekket, jeg mangler det øverste stykke!",
    [1738148619] = "Ja, det gør jeg.",
    [4099014756] = "Ja, det har jeg, Kommandør.",
    [1807914087] = "Ja frue, forretningen går strygende!",
    [555849548] = "Ja, min $g søn : datter;? Hvad kan jeg hjælpe med?",
    [3601190737] = "Ja, min herre.",
    [1471450604] = "Ja ja ja!  Du er lige den $r, jeg leder efter!$B$BSæt dig!  Vi har meget at drøfte!!",
    [551110689] = "Ja!  Jeg er helbredt!  Jeg er hel... hov, rejste mig for hurtigt!",
    [2475712112] = "Ja! Jeg vil have mere af den fabelagtige Nøggenfogger-eliksir!",
    [2276509082] = "Ja!?",
    [1438668383] = "Ja, $c?",
    [844441719] = "Ja, $c? Melder du dig til tjeneste?",
    [1749283705] = "Ja, $n. Elementerne rører sig. Snart løslader vi deres kraft over vores fjender. De skal vakle under slagene!",
    [555810585] = "Ja, Augustin.  Jeg vil gerne gøre forretninger.",
    [1512988178] = "Ja, Knoglelie. Se, det var vores tenor, en gnaven kujon ved navn Don Juljo, der fik mig i gang med det hele. På sine rejser rundt i Herrelande samlede Don Juljo mange interessante færdigheder, og en af dem var evnen til at tage knoglerne fra faldne Svøben-soldater og smede dem til et dødbringende sæt læderrustning - perfekt tilpasset en skurk.",
    [3962493817] = "Ja, men du vil finde det mere givende hvis du har færdighed i urtekundskab!  Du skal pleje og dyrke særlige frø -- ikke svinge en økse blindt eller gestikulere vildt efter forbipasserende skygger.  Selvom den Evergrønne Pung du får gør det muligt for selv den simpleste klods at dyrke noget, vil dem med lidt anlæg få mere rigelige resultater.",
    [1916213002] = "Ja, men du vil finde det mere givende hvis du har færdighed i urtekundskab!  Du skal pleje og dyrke særlige frø.  Selvom den Evergrønne Pung du får gør det muligt for selv en nybegynder at dyrke noget, vil dem der viser lidt anlæg for urtekundskab få mere rigelige resultater.",
    [491095015] = "Ja, kom. Min herre og jeg venter.",
    [2839004] = "Ja, kommandør!",
    [1839496014] = "Ja, det er jeg. Hvad kommer det dig ved?",
    [3576057763] = "Ja, jeg regnede med at du ville komme tilbage. Jeg sendte Kora ud tidligere, og hun fandt Dartels Stav, forladt i skoven.$B$BVi arbejdede så hårdt for at hente den tilbage, $n. Pas venligst på at du ikke håndterer den så skødesløst i fremtiden.",
    [1164363710] = "Ja, jeg har set shamanen du leder efter. Sidst jeg så hende, var hun vest herfra. Hun gemmer sig i bakkerne over Barbermanke-stammen. Hvis du er snedig, kan du finde en sti til hendes hytte i bakkerne. Den er ikke langt nord herfra. Den sti burde lade dig finde hende uden at skulle kæmpe dig gennem Tornesvinene.",
    [2932427327] = "Ja, det har jeg. Lær mig det.",
    [2851993245] = "Ja, jeg må videre.",
    [3323225965] = "Ja, jeg tilbyder træning. Men den er ikke billig.",
    [2147604565] = "Ja, jeg taler et sprog du forstår, $r.  Vi er ikke dyr, men de fleste af jeres slags bliver ved med at behandle os sådan!  Vores forskelle bleger dog i forhold til tragedien der er overgået dette land.  Værsgo, læg dine forskelle med mit folk til side og hør min døende bøn.$B$BJeg kom til dette land for at lappe det jeg kunne, og nu bliver det til intet, medmindre I kan hjælpe mig.  Jeg beder om sådan hjælp med mit sidste åndedrag.",
    [2679396859] = "Ja, jeg synes du har potentiale. Måske kan jeg vise dig et par ting.",
    [2777707675] = "Ja, jeg fik forseglet relikken igen, $n.",
    [1160635316] = "Ja, jeg leverer ordrerne til Krigsmester Garrik!",
    [2133193335] = "Ja, jeg har drevet denne butik i et stykke tid nu. Forretningen har været ret god på det seneste. Masser af nye eventyrere kommer forbi...",
    [2252818328] = "Ja, Borgmester.",
    [54908719] = "Ja, frue!",
    [321616066] = "Ja, herre!",
    [367445219] = "Ja, gør endelig.",
    [3031403976] = "Ja, kald den venligst tilbage!",
    [2889122208] = "Ja, løb! Det får blodet til at pumpe hurtigere!",
    [3630825074] = "Ja, sir!",
    [263921457] = "Ja, sir! Tak, sir!",
    [3930496808] = "Ja, sir. Tak, sir!",
    [3198107873] = "Ja, det er sandt. Korsriddere og præster træner ens deres færdigheder og forsker i store sandheder bag Katedralens mure.",
    [100151378] = "Ja, Tærte. Alt hvad dit hjerte begærer...",
    [656906099] = "Ja, det skal vi!",
    [1063402484] = "Ja, vel...lad os gå videre til mindesmærket for heltene fra de to Store Krige, Heltenes Dal. Følg efter mig.",
    [3720237750] = "Ja, ja, al Hordens og Alliancens krigsmateriel bliver sendt over til Silitus og burde være der inden for $2113w dage. Ved du hvad der sker så, $c? Vi skynder os og venter. Forhåbentlig er nogen ved at samle stykkerne af Scepteret fra de Skiftende Sande, for at åbne portene til Ahn'Kiraj skal det ringes med mod Basse-gongen på Basse-podiet.",
    [3405465713] = "Ja, ja, al Hordens og Alliancens krigsmateriel bliver sendt over til Silitus og burde være der inden for en dag. Ved du hvad der sker så, $c? Vi skynder os og venter. Forhåbentlig er nogen ved at samle stykkerne af Scepteret fra de Skiftende Sande, for at åbne portene til Ahn'Kiraj skal det ringes med mod Basse-gongen på Basse-podiet.",
    [3166263815] = "Ja, ja, rolig nu, $c, der er intet at bekymre sig om. Heldigvis, da du første gang gav mig den venstre del, stillede jeg mig ind på den, så at kalde den tilbage fra hvor end du 'har glemt' den, er virkelig ikke noget problem.$B$BVær så god, og prøv denne gang at passe bedre på den.",
    [2613959834] = "Ja, ja, jeg træner dig. Der er ingen grund til at hæve stemmen.",
    [2581025708] = "Ja, ja. Hmm, det ser ud til at krydshenvise til en anden tome. Må vist finde den også.",
    [3409881648] = "Ja, ja. Jeg ser dig.$B$BVær på vej. Du har måske vundet nogles tillid, men det skal mere end det for at bevise det over for mig!",
    [3464467986] = "Ja, du hørte rigtigt, $c, alle vores indsamlinger er fuldendt, og det sidste krigsmateriel burde ankomme til Silitus inden for $2113w dage. Jeg har fået at vide at når alt er samlet dernede, og vores tropper er klar, så vil en fra jeres helterække ringe med gongen uden for Ahn'Kiraj, med Scepteret fra de Skiftende Sande allerede samlet til at gøre det med. Jeg håber vi ikke skal vente for længe på at det sker.",
    [3678777661] = "Ja, du hørte rigtigt, $c, alle vores indsamlinger er fuldendt, og det sidste krigsmateriel burde ankomme til Silitus inden for en dag. Jeg har fået at vide at når alt er samlet dernede, og vores tropper er klar, så vil en fra jeres helterække ringe med gongen uden for Ahn'Kiraj, med Scepteret fra de Skiftende Sande allerede samlet til at gøre det med. Jeg håber vi ikke skal vente for længe på at det sker.",
    [1008643113] = "Ja, unge, du behøver ikke overbevise mig om sådanne ting, Krigshøvdingen og jeg har en lang historie sammen. Din hengivenhed er dog noteret.$B$BSom jeg sagde, havde Flænse fundet et nyt hjem til sit folk, og jeg var blandt dem der trætte fulgte med.$B$BFra én konflikt opstod andre... utallige andre. Det var i kampene om Sortklippe-spiret mellem Sortklippe-klanen og Mørkejern-dværgene at mine sønner begge blev dræbt. Det var da jeg indså at min tid blandt Sortklippe-klanen var kommet til ende.",
    [4106507045] = "Ja.",
    [4268628547] = "Ja.  Giv mig besværgelsen til at tilkalde avataren.",
    [4234518089] = "Ja. $n. Jeg har lokaliseret Skovherren. Vi må fordoble vores indsats! Der skal bruges flere krystaller!",
    [956833376] = "Ja. Det gør jeg.",
    [172408129] = "Ja. Det har jeg.",
    [96735035] = "Ja?",
    [1863673702] = "Ja? Jeg har et brystpanser at færdiggøre, så det må være godt.",
    [3259238469] = "Jaaah, det'sh sandt, jeg er blind som en flagermuush! Og fuld som en ... øh, fuld som shå'n en shom bliver fuld.$B$BJeg shiger dig hvad, $r. Det'sh drikken der holder mine shanser skarpe. Det'sh almen viden at når man mister en shans, bliver ens andre shanser mere vågne. Min fulde shans er utrolig på det seneste.",
    [3368101785] = "Jaaa... Vagter, kom jeres herre til hjælp!",
    [784341291] = "Og du tror at genfindelsen af Askebringer på en eller anden måde vil vende slagets gang? Lad mig lukke dig ind i en lille hemmelighed, Kommandør: Kraften i Askebringer kom fra manden der skulle svinge den... Jeg var der, Kommandør. Jeg så ham brænde udødes legioner af i retfærdig ild, før han overhovedet trak klingen. Desværre er dit greb om historien ... mangelfuldt.",
    [1834452147] = "Og? Og hvad??",
    [4101398148] = "Iiiiiih! Mig løb!",
    [2019721052] = "Huha! To ildagtige personligheder. I får mange skænderier, men jeres kærlighed brænder lige så hedt!",
    [1695411415] = "Yip! Mig dræb!",
    [3882297282] = "Yonn Dybskær kan findes inde i det store telt i det nordvestlige hjørne af Blodhov-landsbyen.",
    [2064120660] = "Du opfører dig som om det her er det bedste skrammel jeg nogensinde har set. Jo, det er ok, men jeg ser ting der er lige så 'ok' hver dag. Hør her, finder du en måde at imponere mig på, så lærer jeg dig ting der får dværge til at smile i søvne.",
    [2547635183] = "Troede du virkelig, at du havde en chance?",
    [1707237064] = "Har du tænkt dig at blive udstopper?  Jeg kan ikke lide folk, der tror, de kan stoppe og montere mig, fordi de tror, jeg er død.  Nej?  Godt!  Led efter Rand Rabarber i en lejr sydøst for byen.  For at komme til ham, tag vejen sydøst ud af Gryde-by og drej til venstre ved krydset.",
    [2416593529] = "Du er en tosse, snart uden sit liv. Nej?",
    [203521095] = "Du er en lille myg for Rådskov!  Dø!",
    [1368229554] = "Du er allerede død.",
    [506039913] = "Du er en agent for deres onde gud, tosse.  Jeg skal se dig ødelagt!",
    [430479891] = "Du er en usædvanlig fortryller. Hinsides mine lærerevner, frygter jeg. Søg Kitta Ildvind ved Azoras Tårn. Kun hun kan nu kvalificere sig som din instruktør.",
    [3013189494] = "Du er en inspiration for os alle, herre.",
    [2570746797] = "Du er hinsides mit niveau af ekspertise. Georgio Bolerojakke, mesteren hos Duncans Tekstiler om hjørnet, kunne hjælpe dig med at avancere dine færdigheder.",
    [1758264220] = "Du er hinsides mine begrænsede evner. Søg nattenissen Åndetil på Håndværkernes Terrasse i Darnassos. Hun kan lære dig mere. Jeg ønsker bare, at jeg kunne tage med dig.",
    [3477298334] = "Du er bestemt langt hjemmefra, $r.",
    [1119623217] = "Du er bestemt ikke din far, insekt. Hvis det interesserede mig, ville jeg knuse dig med blot ét hug af mine klør. Vend Shan'do Stormrasen over til mig, så skånes dit ynkelige liv sammen med dit folks liv.",
    [472122053] = "Du overrasker mig konstant med, hvad et menneske kan overleve.",
    [4108839902] = "Du er da konge af Gordøk!  Du er nummer ET!",
    [1288035602] = "Du er erklæret en trussel!",
    [1967980791] = "Du er afskediget, $n.",
    [1220387276] = "Du er pligtopfyldende ved at spørge, $c, men alle Hordens samlinger er fuldført. Vi venter nu på, at Alliancens hegemoni afslutter deres, og så bliver alle transporteret til Silitus i nærheden af Cenarion-fæstningen.",
    [4159429226] = "Du er tilgivet...",
    [1966745700] = "Du har været heldig at komme til Darnassos, hvor du kan finde en så dygtig Jæger som Jokaste blandt vores trænere.  Jeg opfordrer dig til at besøge hende i Cenarion-enklaven og søge hendes undervisning.",
    [3791780368] = "Du er fri for Hans kontrol. Og selvom du vil blive dømt af mindre væsener, har du i det mindste chancer, som Svøben ikke har!",
    [522639274] = "Du kommer til at elske den her historie, $r. Se, sagen er den her. Så snart Malygøs havde ladet mig med at beskytte scepter-skåret, vidste jeg, at jeg var dømt til en evighed af hovedpine og smerte.$B$BAlt, hvad jeg ønsker, er at studere disse magirige kyster og tage stilling til, hvilke artefakter der måtte være tilbage fra Sønderrivelsen. Du ved, der var engang en blomstrende Højfødt-civilisation her! Du behøver ikke fortælle mig, at der må ligge nogle solide magiske genstande her omkring, $r. Jeg kan lugte det!",
    [861044523] = "Du skal over til Gamlebyen og kigge forbi Det Beskyttende Skind, hvis du er ude efter at lære flåning, makker.",
    [2078504623] = "Du er faktisk modig, når du vil trodse rædslerne bag denne dør.",
    [1007050467] = "Du er virkelig mægtig, $n. Kom til mig, hvis det er mere arbejde, du søger.",
    [590051900] = "Du er venlig at søge mig op, men dine færdigheder er hinsides mine egne. Snak med Sylvanna Skovmåne, lige derovre. Hun har ledt efter en anden elev.",
    [1935680663] = "Du leder efter Uthan Stillvand.  Du finder ham vest for landsbyen, hvor han fisker ved Stentyr-søen.",
    [1686717336] = "I er mine nu, børn.  I vil vokse op og blive en stærk del af Horden!",
    [2456929334] = "Du er min nu.",
    [2253270373] = "Du er min, skrækhest!  Din ånd er nu bundet til mig!",
    [536496231] = "Du er ingen match for Sortklippe-orkerne!",
    [391316236] = "Du er ingen match for Hordens styrke!",
    [2437465199] = "Du er ikke kendt af mit folk.  Kodo-oksen er et mægtigt ridedyr, og den er et produkt af kærlighed og omsorg fra mit folk; sådan noget gives ikke til fremmede.  Indtil Tordenklippes ældste anser dig for at være en ven, kan jeg ikke tilbyde dig salg af kodo-oksen.",
    [4272710062] = "Du er ikke kendt af mit folk.  Kodo-oksen er et mægtigt ridedyr, og den er et produkt af kærlighed og omsorg fra mit folk; sådan noget gives ikke til fremmede.  Indtil Tordenklippes ældste anser dig for at være ophøjet, kan jeg ikke tilbyde dig salg af kodo-oksen.",
    [410142809] = "Du er ikke klar. Tal med Betty Kvinde, hun står ved trappen derovre. Kom tilbage til mig, når du har opnået en højere oplysning.",
    [3686981077] = "Du prøver ikke at dræbe ambolten med din hammer, du prøver at skabe et våben, du kan dræbe dine fjender med. Lad mig vise dig, hvad du gør galt.",
    [3940664835] = "Du er ikke min tid værd, $n!",
    [3257090810] = "Du er ikke stærk nok endnu, $c.  Gå videre.",
    [2923114901] = "Du er nu klar til at følge stien, der forbinder dit liv med mit eget, om så kun for en kort stund. Men vi må sikre os, at du forstår de ting, åndene taler om.",
    [948001871] = "Du er ret nysgerrig, selvom sådan nysgerrighed skjuler en generel mangel på forståelse.  Jeg siger det, fordi hvis du havde et bestemt formål med at være her, ville spørgsmålet, du stiller, virke meningsløst. $B$BMed det sagt, ønsker jeg dig en god dag.",
    [1889864568] = "Du er klar til større ting! Se Franklin Lødsen, til højre for mig. Han vil vejlede dig herfra.",
    [4287372305] = "Du er termineret.",
    [2265414132] = "DU ER TABERNE!",
    [2058055327] = "DU ER TABEREN. BU.",
    [2334322698] = "DU ER VINDEREN!",
    [2396442030] = "Du er for sent!! Jeg... må... adlyde!!",
    [1972706083] = "Du er virkelig en målbevidst elev. Jeg vil med glæde give dig undervisning!",
    [1450555207] = "Du er svag.",
    [4283491498] = "Du er velkommen, hav en god dag.",
    [705228934] = "Du er godt på vej, $n.  Men du har stadig meget at lære.  Den sydlige Ødemark kan være, hvor din næste lektion ligger.",
    [1236335561] = "Du spørger til Cenarus' Sønner, Remulos og Zætar.$B$BMin far, Remulos, var stærk og smuk, og min onkel, Zætar, var meget snu og spinkel af bygning. Selvom de blev respekteret næsten lige meget, følte Zætar altid, at han aldrig rigtig kunne måle sig med den herlighed og opmærksomhed, han troede Remulos havde.$B$BEfter mine søstre og jeg blev født, satte Zætar sig, blindet af misundelse, for at overgå sin bror... Han var skaberen af sin egen undergang. Sorgen, den har bragt mig, er aldrig blevet mindre, selv om tiden går...",
    [1399109916] = "Du bliver død snart!",
    [569376818] = "Du er for bange!  Mig finde dig!",
    [2777058931] = "Du skal passe på dig selv, $c. Respekter vores måder, ellers kommer en forbandelse over dig og dine.",
    [4055251943] = "Du gør klogt i at tage op til Stormvind i Dværgekvarteret, hvis du vil lære at udvinde malm.  Sikkert kan en af dværgene derinde lære dig erhvervet.",
    [1105148810] = "Du må hellere bakke mig op i den her!",
    [4138780610] = "Du må hellere holde mig tilbage, ellers får $n nogle fængselshus-tæsk.",
    [1875356912] = "Du er en stor boss nu!  Du er konge!  Hyldest til Konge $n, Konge af Gordøk!$B$BNu da du er da boss, skal alle håndlangere give dig tribut!  Du lod nogle være i live, ja boss?",
    [253748197] = "Din store gnavpot! Hvem har sat dig til det her?",
    [1580390456] = "Du bragte forsyninger fra fjenden!  Hah! Godt gået, $n!",
    [4240725624] = "Kan du lave mad?  Det kan jeg også!  Er der en opskrift, du kan lære mig?",
    [1479192922] = "Du kan regne med mig, Helt.",
    [3762392740] = "Du kan regne med mig, Jeztør.",
    [399369504] = "Du kan finde en postboks lige uden for Tordenklippe Bank på den nedre bakke.",
    [4111208622] = "Du kan finde en postboks lige hen'over ved Stenild-værtshuset.  Den ligger lige nord for Jernsmedes porte.",
    [2405732721] = "Du kan finde Aldwin Lattersen ved Stormvinds Besøgscenter i Handelsdistriktet.",
    [2669113370] = "Du kan finde passage til Theramøre fra denne kaj.  Hør mine ord, de lande er sjældent sikre at rejse i for folk fra Alliancen.  Pas på hvor du træder – og på din ryg.",
    [1040684115] = "Du kan finde Radnål i gang med sit håndværk uden for sit hjem ved vejen til Darnassos.  Du burde kigge forbi og se, hvad han kan lære dig.",
    [2433984204] = "Du kan finde Garvysa stående uden for Alkymi-behov i Magikerkvarteret.",
    [2573023989] = "Du kan finde grifonmesteren på den nordøstlige vold med udsigt over Heltenes Dal.",
    [3049734210] = "Du kan finde Vance Underdunkel ovenpå i et værelse på Galgeenden Kro i den sydøstlige del af Gryde-by.",
    [3287623357] = "Du kan gå og fortælle Tykfrakke, at det er her Defias-banden gemmer sig, $n.",
    [3580721116] = "Du kan lære af mig på et tidspunkt... men ikke endnu! Hvorfor starter du ikke med at snakke med Sprite Springfjeder til højre for mig her? Du kan melde dig hos mig, når du har fået våde fødder!",
    [667290736] = "Du kan lære at sy dig sammen i Orgrimgrad.  Det ligger mod nord.  Måske kan en af Orgrimgrad-fodsoldaterne hjælpe dig.",
    [3061101637] = "Du kan hente dine kærlighedsbreve uden for banken midt i Styrkens Dal.",
    [1890082005] = "I kan lege mere i morgen. Kom nu indenfor.",
    [1650076888] = "Kan du se mig? Ved du, hvor meget jeg bliver ignoreret heroppe, bare fordi ingen kan se mig? Hvor er det forfriskende endelig at have nogen at snakke med!$B$BSå du må være sendt af et levende medlem af mit tidligere lejesoldatkompagni, ikke sandt? Selvfølgelig er jeg det!$B$BMen nok med tom sladder, der er en hel masse arbejde for dig og mig, hvis vi skal rette tingene op og returnere Herre Valtalaks ånd til ham!",
    [3930573648] = "Du må gerne takke mig når som helst for at gøre dit liv mere spændende.",
    [2438578548] = "Du kan stole på, at Dyreven passer godt på alle dine kæledyr.  Han holder til i Cenarion-enklaven, hvor jægerne samles.",
    [3888104737] = "Du kan som regel finde Broder Vilhelm bagved smedjen, hvor han bytter historier med Lyrie.  Han er altid klar til at lære medkorsridderer nye færdigheder.",
    [2350096601] = "Du kan ikke slippe væk fra en kriger fra Horden! Tag den! Og den!",
    [1281083874] = "Du kan ikke gemme dig for os.  Gør dig klar til at brænde!",
    [3995094117] = "Du kan ikke studere mine teknikker, før du har lært det grundlæggende. Tal med Kamarie, hvis du er interesseret i træning.",
    [2546953824] = "Man kan ikke lære en gammel hund nye kneb.  Det var i hvert fald det, nogen engang fortalte mig.  Heldigvis for dig har jeg opdaget, at det er usandt.$b$bDog har kæledyr en tendens til at blive modstandsdygtige over for teknikken, og jeg skal bruge mere mad hver gang for at holde dem glade.  Det betyder, at du skylder mig flere penge, jo flere gange du afskoler det samme kæledyr.$b$bNå, vil du have, at jeg begynder at afskole?",
    [1409784100] = "Du kan ikke besejre Frostulv-klanen!",
    [1235594412] = "DU KAN IKKE BESEJRE DEN LEVENDE FLAMME! KOM I MINE HÅNDLANGERE AF ILD! KOM FREM, I HADSKABNINGER! DIN MESTER KALDER!",
    [1924639278] = "Du kan ikke gemme dig for mig!",
    [3498386319] = "Du kan ikke gemme dig for mig, skurk. Jeg kan lugte din frygt.",
    [3305859780] = "Du kan ikke gemme dig for os, lille korsridder!",
    [2122207267] = "Du kan ikke ride på et ridedyr i den skikkelse.",
    [2735593679] = "Du kan ikke redde ham!",
    [1783145313] = "Du bærer Svøbens fordærv.  Gør dig klar til at træde ind i den Tvistende Nether.",
    [3176703488] = "Du skuffede da ikke! Nu hvor vi har fået det overstået, kan din undervisning begynde!",
    [4119328591] = "Du udfordrer Den Blå Drageflugts ladning? DØD, utøj.",
    [1472985634] = "I udfordrede os, og vi er kommet. Hvor er denne mester, I taler om?",
    [1597464990] = "I snød!",
    [1545133598] = "Du tjekker fronten!",
    [627030012] = "Du kommer til os med titel, og derfor vil vi lytte, men prøv ikke vores tålmodighed, $c.  Rådet har ingen tid til tom sladder fra én som dig.",
    [117677108] = "Du kommer til forkert sted. Tal med ekspert Gudan derovre. Du lærer mere af ham.",
    [3755864796] = "Du bladrer videre i dagbogen og leder efter oplysninger, der kan hjælpe dig i jagten på den stjålne kiste.$B$BMod bogens sidste sider ser du i rød blyant en note fra Jakob langs siden af en side. Der står: \"Gammelt hjem nær Stenrøsesøen... gnoller vil fungere perfekt som livvagter.\"$B$BDer er ingen grund til at tro, at kisten er der, men der ser ikke ud til at være andre spor.",
    [4277197298] = "Kunne du ikke klare en enlig nattenisse-præstinde?",
    [917051269] = "Du da chef nu, ja?  Længe leve da ny konge!$B$BKræg lad dig kigge på Gordøk-sprut.  Oger-sprut er bedst af al sprut, og Gordøk-sprut er bedst af al oger-sprut!  Måske du køber noget fra mig, ya chef?!",
    [353535416] = "Du da mand nu, hund!",
    [3077050306] = "Du da stærk en nu!  Hyldest til da ny konge af da Gordøk!",
    [2293856799] = "Tør du udfordre mig? Gør dig klar til en evighed af rædsel.",
    [2002382721] = "Du tør besudle Frostmanke-fæstningen, $R. Gør dig klar til at dø!",
    [387676408] = "Tør du besudle denne hellige jord?",
    [3464351257] = "Tør I forstyrre vores arbejde her?! Mesteren vil ikke være tilfreds. Tag jer tid til at gøre jer klar... når vi vender tilbage, vil der ikke være andet end død og ødelæggelse i vores kølvand!",
    [259836628] = "Tør du blande dig i dette væsens prøve? Kampen må udkæmpes alene! I skal alle lide for denne ubetænksomhed.",
    [614250633] = "Tør I afbryde vores bøn? Udfør henrettelse på dem!",
    [1959737831] = "Tør du sætte fod i Ravnehold-herregården, orm?",
    [75324608] = "Tør du sætte fod på Håkkaris hellige jord? Håndlangere af Hakar, tilintetgør de vantro!",
    [3017109029] = "Tør du spilde blod på neutral grund? UD! UD, siger jeg!",
    [4134920488] = "Tør du røre mig?!",
    [3926656710] = "Tør du!  Det er udskammeligt!  Jeg forbander dig, $c.  Jeg forbander dig med... død!",
    [357812000] = "Tør du! Føl nu min vrede, $r.",
    [2183075295] = "Du ønsker at forme Moder Jords knogler til værktøj, der kan hjælpe Horden.  Godt, godt.  Følg stien nordpå ud af Blodhov-landsbyen, indtil du når elevatoren, der fører til toppen af Tordenklippe.  En Bluffvagt dernede kan hjælpe dig yderligere.",
    [1458026161] = "Du gjorde et fremragende stykke arbejde, Spionbot! Glad for at have dig tilbage hos mig!",
    [2138472664] = "Du gjorde det... du har slået Baron Flodfarer ihjel!  Sølvdæmringen skal høre om dine tapre bedrifter!",
    [3083749540] = "I skuffer mig, elever!",
    [116721708] = "Du skuffer mig, Tælan. Jeg havde planer for dig... storslåede planer. Ak, det var kun et spørgsmål om tid, før din snavsede blodlinje ville indhente dig.",
    [3080969112] = "Du gør godt arbejde, men det er lidt ruskende i kanterne. Bare rolig, det kommer med øvelse. Apropos, hvad med at vi kigger på det, du har arbejdet med?",
    [1199256695] = "Du hører ikke til her! Oldtidens Folk, rejs jer mod disse indtrængere!",
    [3706587674] = "Du hører ikke hjemme i disse haver. Din krop skal nære vores dejlige skabninger!",
    [1111879428] = "Din hund! Nu fanger jeg din sjæl i et fragment og giver den til min drilling som legetøj!",
    [2698642819] = "Du forventer da ikke, at jeg giver alle mine hemmeligheder fra mig?",
    [2071045099] = "I kæmper ikke for jer selv længere, maddiker! I kæmper for Dronningen nu, så vis mig noget, der er værdigt til hende!",
    [971277425] = "Du har ikke mave til grifonridt, hva'? Heldigvis for dig har vi et alternativ, hvor du kan holde fødderne på jorden... mere eller mindre. Det er gnomernes personbefordrer, Dybløb-sporvognen. Praktisk placeret bagerst i Dværgekvarteret.",
    [3018161484] = "Du ligner ikke en elev...",
    [1616609598] = "Du ser ikke meget ud for mig, men hvem ved, måske gemmer der sig en fortryller derinde et sted!",
    [1905874305] = "Du har ikke noget imod, at jeg lige stopper her et øjeblik, vel?",
    [1389725735] = "Du har endnu ikke færdighederne til at studere hos mig. Gå hen og tal med Doktor Martin Felben derovre, eller gå op ad rampen mod sydøst og se Doktor Sump. De er De Forladte, som kan give dig den træning, du har brug for.",
    [975245953] = "Finder du den, så beholder du den! Fortæl ikke nogen, at Rin'skold snakkede med dig!",
    [40527495] = "I tosser tror, I kan besejre mig så let? Stå over for Nathrezimmernes sande magt!",
    [1799147203] = "I tosser! Bliv ved med at kæmpe, hvis det er jeres ønske! Med hvert slag falder flere af jer, og de udøde rækker svulmer op!",
    [4215989763] = "Du fandt en nøgle? Nå, er det DEN nøgle? Altså, er det nøglen til at låse disse lænker op? Tja, $G herre : frue;, der er kun én måde at finde ud af det på!",
    [2153556192] = "Du befriede Kirit fra hans lidelse? Utænkeligt -- og nu har Trebør sendt dig herhen for at lære om dæmoner og deres håndlangere?$B$B<Lorumus ler.>$B$BVær taknemlig for, at de arkane smerter endelig er forsvundet, $r.",
    [265492066] = "Kom ned derfra med det samme! Jeg vil ikke have, du klatrer op på den ting. Det er ikke sikkert.",
    [4189177871] = "Du gå Det Kongelige Kvarter. Se Ridder Malorie Hjulmager. Han skræmmende.",
    [1570770704] = "Du gå til indre ring i Apotekerium. Lavinia Krage er der.",
    [1693543037] = "Du har den!",
    [1085408924] = "Du fik mig godt, boss! Hvordan kom du forbi Glip'kik?? Jeg er klog nok dog, jeg holder øje næste gang! Har har!$B$BIngen kommer forbi Glip'kik mere. Glip'kik lover det!",
    [699305919] = "Du har spørgsmål, men de er for store for mig at besvare, $n. Du skal have et ord med orken Hjelmak i Slæbet i Orgrimgrad. Han hjælper dig nok.",
    [661542151] = "Du har udseendet af en, der længes efter eventyr. Jeg fik nok af det, da vi trolde kom hertil. Nu tager jeg én dag ad gangen, og jeg træner andre folk til at klare eventyrene for mig.",
    [2702719698] = "Du leder ånderne i stålet til at beskytte og forsvare med langt mere færdighed, end jeg nogensinde kunne. Eleven har overgået læreren, og nu må jeg sende dig dertil, hvor din uddannelse kan fortsætte. $n, du skal opsøge Shayis Stålraseri i Orgrimgrad. Hun er den fineste Rustningssmed, jeg nogensinde har kendt, og hun kan lære dig meget.",
    [3610301510] = "I så hende? Jeg så ikke Darsy. Jeg undrer mig over, hvor hun er i aften.",
    [1142462145] = "Du har <snøfte> hjulpet Kløvtand mere, end jeg nogensinde havde drømt om, $r.$B$BTak.$B$BSå længe jeg forbliver fange her, må du bringe mig blodfragmenter fra Børsterygge-tornesvinene, og jeg vil velsigne dig med Agamaggans kraft.",
    [411191265] = "Har du en skattekiste? Lad mig se! Fint, find Zandø'zan i Skyggeklyngen. Led efter tunnelen, der går ned i Slæbet, for at finde den.",
    [1256512501] = "Du er kommet længere, end jeg kan lære dig. Rejs nu til Ørnerede-toppen i Bagland og tal med dværgen Drakk Stenhånd. Hans arbejde er storslået, langt bedre end mit eget.",
    [3157344530] = "Har du nogen anelse om, hvor længe jeg har ventet her? Og hvor er middagen? Al den tid spildt og intet at vise for det?",
    [3358826053] = "Du har været væk alt for længe, Malfurion. Freden mellem Azerots børn er i bedste fald skrøbelig. Hvad med min far? Hvad med din bror? Har du nogen nyheder?",
    [2716420273] = "Du er dømt til døden for forbrydelser mod Mørkejern-nationen!",
    [4012322019] = "Du er bestemt kommet langt i din træning. Der er kun én instruktør, der kan træne dig videre. Find Buzzek Vinkelsving i Gadgetbyen!",
    [4107671084] = "Du har udfordret De Syv, og nu skal du dø!",
    [1445474111] = "Du har valgt klogt, $n. Søg Kergal Blodøkse op på Jægerhøjen. Han vil assistere dig på din rejse til Krigssang-Gulch.",
    [837071186] = "Du er kommet langt, rejsende. Der er én opgave mere, du skal udføre...",
    [2095325301] = "Er du kommet for at lære krigskunsten, $r? Du er kommet til det forkerte sted.",
    [4079599864] = "Er du kommet for at høre om slag, der er vundet og tabt på denne mark? Der er ingen vindere her...",
    [68594184] = "Du er kommet til mig for undervisning, og til gengæld har jeg en tjeneste at bede dig om. Sørg for, at den bliver gjort, så bliver du belønnet.",
    [1819328353] = "Er du kommet for at lege? Så lad os lege!",
    [533315121] = "Du er kommet for langt til at fejle. Stå tilbage, dødelige.",
    [3406267619] = "Du har fuldført Terøns mission, og jeg sætter pris på alt, du har gjort, $n.",
    [1124662449] = "Du har fuldført opgaven!",
    [2985673175] = "Du har vist færdighed i at lære vores håndværk. Har du også viljestyrken til at fuldføre en mission på mine vegne?",
    [150644349] = "Du har forstyrret min hvile, $c. Stå nu over for min vrede!",
    [457472569] = "Du har gjort et enestående stykke arbejde, soldat! Kavaleriet er klar til at ride på din kommando.",
    [1994451707] = "Du har gjort det godt, $n. Fortsæt din søgen efter viden, og husk den historie, du har lært.",
    [1004819194] = "Du har gjort det godt, rejsende. Jeg er stolt over at kalde dig min elev!",
    [4212065342] = "Du har fortjent retten til at træne hos en højere instruktør. Gå hen og se min ven Rokkik derovre.",
    [1961276309] = "Du har svigtet ham, dødeligesss... Farvel!",
    [2155402396] = "Du har ikke formået at beskytte mig mod aberne!",
    [1197490913] = "Du har fejlet!",
    [803937833] = "Du har kæmpet hårdt for at invadere høsterens rige.",
    [2074587055] = "Du har kæmpet godt, ånd. Jeg beder dig tildele mig styrken i din krop og styrken i dit hjerte.",
    [1467443770] = "Du er gået til store længder, fremmede, og du har min taknemmelighed. Jeg lovede at fremme din træning, og nu vil jeg holde det løfte.",
    [2938406728] = "Du har et stort potentiel, men du må først opnå forståelse, du må acceptere ånderne og lytte til deres kald. Først da vil du være rustet til den vej, du skal følge. Gå og tal med Tråg, jeg tror måske, at I kan lære meget af hinanden.",
    [2660048567] = "Du har rystet klyngen, og sporerne har gjort dig syg!",
    [4111760494] = "Du har lært alt, hvad jeg på nuværende tidspunkt kan lære dig, Læge $n. Vend tilbage, når din praksis er udvidet, så vil jeg træne dig i de mere avancerede medicinske kunster.",
    [3965692884] = "Du har lært meget, men jeg fornemmer, at der er mere, ånderne har tilbage at lære dig. Jeg kan sætte din fod på stien, men jeg kan ikke lede dine skridt. Gå og find Sarru Stålraseri i Orgrimgrad, den næste etape af din rejse begynder der.",
    [3812128862] = "Du har lært meget, mere end jeg kan lære dig. Gå til Jakob Van Brunt, han vil lære dig det, jeg ikke kan.",
    [542961572] = "Du har lært grundprincipperne i at brygge eliksirer, men videre studier kræver større engagement. Bevis din hengivenhed ved at udføre en opgave for mig.",
    [1386515398] = "Du har lært godt, mit barn. Gå til Undergrunden, find en smed ved navn Jakob Van Brunt. Han kan lære dig meget, som jeg ikke kan. Jeg forstår, at han tilbringer sin tid ved Krigernes træningshal og smeder deres våben og rustninger.",
    [1352554326] = "Du har mistet forstanden, Skurkius. Du taler i gåder.",
    [972426650] = "Du har gjort vores fjender til dine egne. Jeg deler gerne vand med dig.",
    [358805967] = "Du har min dybeste taknemmelighed, $N. Jeg takker dig.",
    [2110214305] = "Du har mit ord på, at jeg finder en brug for din krop, efter jeg har dræbt dig, $r.",
    [1954136835] = "Du er næsten nået til toppen af din træning. For at blive den største fortryller, du overhovedet kan være, må du søge én instruktør mere. Hendes navn er Anora, og du kan finde hende i Uldhulen.",
    [3141670469] = "Har du brug for mine færdigheder som alkymist, ja?",
    [751960855] = "Du har ingen forretning hos mig, lille en.",
    [3104930842] = "Du aner ikke, hvilke rædsler der venter forude. Du har set intet! Naxxrammas' frosne hjerte venter dig!",
    [2935454353] = "Du har ikke levet, før du har gravet dybt ned i jorden.",
    [2159509415] = "I har ikke set det sidste til mig, dårer! Alt skal blive forbrugt til sidst!",
    [2909149530] = "Du har endnu ikke fortjent retten til at træne hos mig. Se Tund først, henne ved bordet. Kom tilbage, når han siger, at du er klar!",
    [1273911149] = "Du har endnu ikke lært det grundlæggende, vandrer. Har du talt med min assistent, Lalina Sommermåne? Måske skulle du det.",
    [3655562923] = "Du har kun lige begyndt at se Øjets kraft, $c. Hvis du vil fremme Øjets evner, så er der en opgave, du må fuldføre.",
    [727867228] = "Du er vokset fra enhver lære, jeg kan give. Gå med Moder Jords velsignelse. Søg tyrefolket Tærn i butikkerne i den nordvestlige del af Tordenklippes centrale plateau. Lad dig vejlede af hans visdom.",
    [1176247883] = "Du har slidt din velkomst op!",
    [1284763012] = "Du har bestået din prøve, godt gået! Din træning kan nu fortsætte.",
    [3702521158] = "Du er nået til nye højder på din vej mod mestring. Lad os se, om vi kan tage dig endnu længere...",
    [2308876581] = "Er du kommet tilbage for at fuldføre jobbet? <Lathorik ler.> Obsidiøn, rejs dig og tilintetgør dem!",
    [506723871] = "Du har vist mig din længsel og betalt med ædelsten.  Jeg vil lære dig...",
    [3343308417] = "Du har et vist talent, det er sandt, men hvert øjeblik jeg bruger på at lære dig, er et øjeblik mere, de udøde tilbringer i pine. Bevis for mig, at du er min tid værd.",
    [2180376356] = "Du har fremkaldt mig, tåbe! Nu DØ!",
    [1779676749] = "Du har udseendet af en $g mand : kvinde; der søger viden. Måske søger du smedekunstens lærdomme og hammeren. Måske kan jeg vejlede dig ad den vej. Men kun når du har accepteret åndene og lyttet til deres kald.",
    [2210670065] = "Du må passe på, når du tænder fyrværkeri, når du ikke kan mærke dine fingre...",
    [2154631604] = "Du er virkelig blevet en af de fineste skrædder i branchen! Tillykke, jeg er stolt af at have været din instruktør!",
    [1929367405] = "Du har virkelig udmærket dig i din viden om fortryllelse. Der er meget mere at lære, hvis du er villig. Tal med Talentdan på Håndværkernes Terrasse i Darnassos.",
    [4140670354] = "Du er virkelig blevet mere snedig, $n.",
    [438040901] = "Du har spildt din tid og min ved at komme til mig for træning, $n. Jeg har ingen tid til at lære grundlæggende færdigheder. Vi kæmper en krig her, og dette er en af frontlinjerne. Undlad at vende tilbage til mig, før du er bedre forberedt.",
    [251392107] = "Du har arbejdet dig op... nu er det tid til at se bossen. Gå til Josef og sig, at du er klar.",
    [3389319108] = "Du har ikke levet, før du har set ned over verden fra ryggen af en vindrytter.",
    [4277699725] = "Hører du det? Jeg tror, de kommer nærmere...",
    [2569821144] = "Du hørte ham, rejsende. Tal igen med mig, når du er klar til at tale med Bælgrum.",
    [4112438707] = "Du hørte krigsherren, maddiker! MARSCH!",
    [2951450869] = "Du holder ondskab i dine hænder, tåbe! ANGR!",
    [1685270099] = "Du holder min faders klinge, $n. Mine soldater er dine at styre, min $g Herre:Dame;. Tag dem... før dem... De urene må renses. De skal renses for deres fordærv.",
    [1468930240] = "Du ærer mig med din tilstedeværelse, $r. Desværre er det for sent for mig. Jeg forlader denne verden snart, men... jeg ved så meget. Så meget er gemt i dette hoved af mig. Så meget, der kunne hjælpe denne verden med at værge sig mod bæsterne i denne fordærvelsens citadel.$B$BMåske hvis du er en herre i et håndværk... Ja, måske ville du tage den viden, jeg besidder, og bruge den til at redde denne verden.",
    [2112840015] = "Du ærer dyrenes ånder, du må slagte, ved ikke at lade dem gå til spilde.  Aska Tågeløber vil vise dig hvordan.  Hun har et køkken oppe i højhuset.",
    [2792951481] = "Du ærer os med din tilstedeværelse, min herre.",
    [3223846131] = "Du holdt mig i den celle for længe, monster!",
    [3201638866] = "Du dræbte Spøgelsesylen.  Du er sgu en rigtig hingst!",
    [48179295] = "Du ved nok til at være farlig, men du ligner stadig en, der trænger til træning, synes jeg $n.",
    [3735743864] = "Det ved jeg godt, dødelige; jeg opgiver en hel del foregivender her, og det anbefaler jeg dig også at gøre.$B$BDu er kommet hertil, fordi du tydeligvis ved, at det, du besidder, samlet op under dine handlinger i Det Sunkne Tempel i Atal'algrytten, har bragt dig til mig med et formål.  Dette formål er at lægge min medarbejder... min bror, til hvile.  Han er fanget i et mareridt inde i selve Drømmen.  Han kan ikke bryde fri alene.",
    [2811698656] = "Du kender mig som den Overlegne Kommandør for Kalimdørs Magt.",
    [2540988639] = "Du ved ikke, hvad du gør!  Vi må ødelægge dig for dit eget bedste.",
    [3473746634] = "Du ved, at der er krokodilisker i kanalerne. De blev bragt hertil fra sumpen som kæledyr, men blev smidt i kanalerne.",
    [3670347058] = "Ved du, hvem der virkelig kan vise dig nogle ting? Nogg! Gå og find ham i Orgrimgrad.",
    [2799398770] = "Ved du, hvem der er virkelig klog? Nogg! Endda klogere end mig. Du skal sige til Nogg, at Tund sendte dig! Du finder ham ved kontrolpanelet derovre.",
    [540590729] = "Ved du, hvorfor orkøjne gløder røde? Det er fordi, de drikker blod!",
    [476409988] = "Du ved, jeg har altid ønsket at blive Prospektor, men jeg blev født med hoved for tal, og Klan besluttede, at jeg bedst kunne passe på bøgerne! Pugge, pugge, hver dag af min ungdom...",
    [801616418] = "Du ved, jeg kunne gennembore en ork eller flække en troll.  Jeg kunne endda skære mine initialer ind i en ogers side, men jeg kan simpelthen ikke holde ud at flå et dyr.  Hvordan kan det være, hva'.  \n\nNå, hvis du har mave til det, så gå og se Maris Kornlager i Det Beskyttende Skind i Gamlebyen.",
    [1975102806] = "Du ved, denne bro er ret stor, til at bare os 6 bygger den. Man skulle tro, at de havde ansat flere folk.",
    [1267959035] = "Du mangler takt, kommandør. Det er ikke overraskende. Men du har ret i, at Horden vil blive tvunget til at handle. Men ikke kun Horden. De kommer allerede – helte fra hele verden.",
    [1629128801] = "Du lærer hurtigt, og det er ikke en dårlig ting. Bare sørg for at gøre jobbet ordentligt, så længe det tager. Nu frygter jeg, at jeg må sende dig til Snerren for at lære mere. Lær det, han kan lære dig, men lyt ikke til hans vrede ord. Han bliver sådan, når Sarrus døtre griner af ham.",
    [894858380] = "Kan du lide slik?  Jeg kan lide slik.",
    [2645773733] = "Kan du lide tæppet? Jeg dræbte og flåede udyret selv. Må alle kentaurerne falde lige så nemt.",
    [4177401141] = "Du låste den forkerte marskal inde, $n. Gør dig klar til at blive ødelagt!",
    [2160346687] = "Du ser lidt fortabt ud.  Hvem leder du efter?",
    [4085797764] = "Du ser ud til at have brug for hjælp, hvordan kan jeg hjælpe dig?",
    [2088180462] = "Du ser ud, som om du er rejst langvejs fra, $r.",
    [1531734785] = "Du leder efter Josef Gregoriansen.  Han er i Magikvarteret på den indre ring, ved den grønne kanal.",
    [2325931462] = "Du leder efter Martha Alliestjerne.  Hun står på den indre ring i Apotekerium.",
    [3620817087] = "Du leder i Apotekerium.  Det er dér Doktor Herbert Halsøje og Doktor Sump praktiserer.",
    [3334812747] = "Du ligner den type jeg bør holde øje med min pengepung omkring. Er der noget jeg kan hjælpe dig med?",
    [3174447755] = "Du ser ud til at trænge til noget arbejde, $gkarl:dame;. Du bør stige om bord i sporvognen og besøge min bror, Monty, ved Dybløbs-sporvognsdepotet i Jernsmede. Jeg er sikker på at han har noget du kan lave.",
    [3605533058] = "Du ser ud til at have brug for passage over Det Store Hav. Nå, du er kommet til det rette sted, for her er kajpladsen for Jomfruens Lyst, det fineste passagerskib der sejler disse farvande. Når hun ankommer, skal du bare klatre om bord, og næste ting du ved, er at du soler dig på Kvælerdorns sandede strande.",
    [2769779120] = "Du ser ud til at være faret vild.",
    [438719937] = "Du ser ud til at have fået knust hjertet. Kom tilbage når du ikke er så ked af det.",
    [3617480589] = "Du ser faret vild ud.  Jeg kan hjælpe.",
    [213697379] = "Kigger du på mig, $gdreng:pige;?",
    [2775654010] = "Leder du efter modig?  Nå, du har ikke hørt mig sige det her, men... måske hvis du spørger Kronkryster oppe i tårnet, så vil han fortælle dig det...",
    [3632627235] = "Er du faret vild?",
    [1872148832] = "Du klarede den! Storartet! Marskal Windsor har ventet på dig. Vil du have mig til at signalere til ham nu?",
    [275507676] = "Du klarede den?! Jeg er overrasket over at Kinelori ikke bremsede dig mere end det. Kin, her er dine sokker. Giv mig det du fandt ins",
    [1211261365] = "Du laver en perfekt lille hat, $r!",
    [3356587112] = "Du kan finde opbevaring til dine jordiske ejendele i Darnassos Bank, som ligger midt i vores vidunderlige by.",
    [1887168490] = "Du har måske lykkedes med at stoppe os denne gang, men vi vender tilbage -- det kan vi love dig!",
    [1808846891] = "Du må lade mig blive her -- jeg ønsker at være alene i mine sidste øjeblikke.",
    [3757871676] = "Du må ikke passere.  Du er ikke af vores slægt, og du har heller ikke udstedt udfordringen.",
    [4027802827] = "Du kan søge efter Martin Lindsø inde i Synets Pøle, under Åndsopstigningen.  Han vil hjælpe dig på vej til Arathi-bækkenet.",
    [3141950487] = "Du kan skille dig af med dine jordiske ejendele i Tordenklippe Bank på den nedre højderyg.",
    [2245085709] = "Du må gerne tale rent ud, Neeru...",
    [1877017658] = "Du kan måske vinde på slagmarken et kort øjeblik... men du kan ikke håbe på at vinde over Svøben!",
    [1248034698] = "Du tror måske du har vundet, ormer, men mod Svøbens magt findes der ingen sejr for de levende! Du har ikke set det sidste af os!",
    [1003588584] = "Mener du at fortælle mig at du sælger frøer?",
    [4263113121] = "Mener du at du ikke kan lugte røgen fra dværgesmedjerne herfra?  Nå, du skal lede efter Therum Dybsmedje hvis du vil lære smedekunst.  Han er nede i Dværgekvarteret, som ligger lige nord for Katedralpladsen.",
    [3032079048] = "Mener du, du ved det ikke? Sværdet du bærer på ryggen - det er kendt som Askebringer; opkaldt efter sin oprindelige ejer.",
    [602751628] = "Mener du...",
    [1483716879] = "Du nævnte to resultater når Jordvæsnerne destabiliseres.  Hvad er det andet?",
    [2777446677] = "Du ødelægger blot et billede, tåbe. Jeg vil jage dig til tidernes ende.",
    [481697501] = "Du forlænger blot det uundgåelige, $r. Bukk under. Hun vil befri din vildledte sjæl.",
    [4140055607] = "Roder du med Silas, roder du med mig.  Hav en god dag.",
    [2749608794] = "Du kan måske slå mig, men Defias VIL tage Stormvind tilbage!",
    [2582868187] = "Du må være desperat for at vandre rundt i Ødelandene, $c.  Desperat ligesom mig.$B$BEller også er du måske her fordi du er skør.  Skør, ligesom mig.",
    [3886575712] = "Du må lede efter Smed Argus.  Han har normalt opsyn med smedjen i Guldshire, hvis du har brug for lidt træning.",
    [540329790] = "Du må vælge en mere erfaren lærer, for du har overgået mine evner. Jeg råder dig til at tale med Lilyssia Nattevind her: hun har meget viden at tilbyde.",
    [13233196] = "Du må fortsætte! Deres beslutsomhed svækkes. Drik af min kraft og bliv fornyet igen!",
    [1776109766] = "Du må gøre det jeg ikke kunne: Red bønderne der blev hugget ned mens de flygtede fra Stratholm.$B$BDe vil gå mod lyset, du skal sikre deres overlevelse. Falder der for mange, vil vores forbandede eksistens fortsætte - og du vil have fejlet.$B$BHver evne, bøn og besværgelse du har lært, vil blive sat på prøve. Må Lyset beskytte dig, $n.",
    [3725912671] = "Du må gøre hvad du mener er rigtigt, Marcus. Vi tjente sammen under Turalyon. Han gjorde os begge til de mænd vi er i dag. Tog han fejl med mig? Tror du virkelig at min hensigt er at skade vores alliance? Ville jeg skamme vores helte?",
    [56155559] = "Du må finde en måde at vise at I begge kæmper for samme side. Selvom Tømmerkæbe måske angriber dig nu, vil du finde en vej, hvis du er flittig.$B$BDu må huske at ethvert angreb direkte på Tømmerkæbe-pelsbolgene vil hindre dine chancer for at vinde dem som allierede betydeligt.$B$BEt godt sted at starte ville være Dødtræ-pelsbolgene, der findes mange steder i Ondskoven. Disse pelsbolge er fjender af Tømmerkæbe-stammen, og at slagte dem vil forbedre dit forhold til Tømmerkæbe betydeligt.",
    [4212023190] = "Du må finde en blandt staklerne i citadellets nedre del, som har opnået et Usmykket Opstigningssegl. Det er en stor ære for et af de mindre væsener at opnå denne genstand, for det er det første skridt til at få adgang til den øvre citadel og blive en af Nefarians elitevagter - Sortehånd-legionen. Find en sådan genstand og bring den tilbage til mig, så jeg kan undersøge dens egenskaber. Jeg vil vide hvordan jeg skal gå videre, når min inspektion af seglet er færdig.",
    [1309323603] = "Du må høre min historie, før vi kan fortsætte, $n. Den vil være til stor nytte for dig i fremtiden.",
    [4053451890] = "Du må forlade baren!",
    [2110522215] = "Du må lytte, unge $c.  Lyt til hviskene i mørket, for de tilbyder vejledning i disse urolige tider.",
    [962033962] = "Du må ikke kalde vores gud frem!",
    [2306527272] = "Du må redde ham!",
    [3282053963] = "Du må redde os!",
    [1772368050] = "Du skal gå til Apotekerium på den indre ring.  Det er dér Martha Alliestjerne lærer dig at plukke blomster.",
    [131335552] = "Du skal være æret hos dværgene i Jernsmede, før jeg vil lære dig ridning, $c.",
    [890485730] = "Du skal være æret hos De Forladte i Undergrunden, før jeg vil lære dig ridning, $c.",
    [2070282423] = "Du skal være æret hos gnomerne fra Nisseborg-eksilerne, før jeg vil lære dig hvordan man styrer en Mekanostrider, $c.",
    [512237985] = "Du skal være æret hos menneskerne i Stormvind, før jeg vil lære dig ridning, $c.",
    [4261271555] = "Du skal være æret hos nattealferne i Darnassos, før jeg vil lære dig ridning, $c.",
    [546571888] = "Du skal være æret hos orkerne i Orgrimgrad, før jeg vil lære dig ridning, $c.",
    [2556753036] = "Du skal være æret hos tyrefolket i Tordenklippe, før jeg vil lære dig ridning, $c.",
    [2068239061] = "Du skal være æret hos trollene i Mørkspyd-stammen, før jeg vil lære dig ridning, $c.",
    [3978119010] = "Du skal have et venligt forhold til dværgene i Jernsmede, før jeg vil lære dig ridning, $c.",
    [1787488969] = "Du skal have et venligt forhold til De Forladte i Undergrunden, før jeg vil lære dig ridning, $c.",
    [2740362442] = "Du skal have et venligt forhold til gnomerne fra Nisseborg-eksilerne, før jeg vil lære dig hvordan man styrer en Mekanostrider, $c.",
    [2462670335] = "Du skal have et venligt forhold til menneskerne i Stormvind, før jeg vil lære dig ridning, $c.",
    [2684132216] = "Du skal have et venligt forhold til nattealferne i Darnassos, før jeg vil lære dig ridning, $c.",
    [1190438808] = "Du skal være venlig over for orkerne i Orgrimgrad, før jeg lærer dig en ridefærdighed, $c.",
    [238294732] = "Du skal være venlig over for tyrefolket i Tordenklippe, før jeg lærer dig en ridefærdighed, $c.",
    [1094664544] = "Du skal være venlig over for trollene i Mørkspyd-stammen, før jeg lærer dig en ridefærdighed, $c.",
    [4202896115] = "Du skal blive stærkere, $c, før du kan hjælpe os i Alterac-dalen.",
    [2078031839] = "Du skal finde Sort.  Led efter ham inde i kasernen på østsiden af Barberbakken.",
    [4227117] = "Du skal lytte lidt bedre til åndernes vejledning, unge. Din vej ligger hos en anden, Tråg Stenhov i Tordenklippe. Måske kan I lære noget af hinanden.",
    [1730003737] = "Du skal lære af en, der ved mere end jeg gør. Gå og snak med Josef Gregoriansen i Undergrunden. Nå, hvad laver du stadig her?",
    [2532898381] = "Du skal gøre dine sting mindre, $n. Så glipper færre ting ud af dine kogere og ammunitionspunge. Og ingen kan lide en klumpet tunika.",
    [1001634527] = "Du skal begynde at lære ting, der ligger uden for min ekspertise! Snak med Lilliam Gnistspinder foran teltet der. Han sætter dig på den rette kurs!",
    [1355200188] = "Du ikke udfordre mig, tøsedrenge!  Jeg da konge nu, og jeg bliver konge FOR EVIGT!!!",
    [2099012130] = "Du ikke tage lys!",
    [3988441084] = "Du ikke gå glip af Armand Cromvel i Magikvarteret.  Han stå på kajen.",
    [4265209574] = "Du udskyder kun det uundgåelige!",
    [236708192] = "I udenbys pak skal betale for at trænge ind på vores land!",
    [2895961625] = "Du havde nok ikke regnet med at finde mig i denne hule, vel?$B$BMit navn er Jens D., og jeg kan ikke rigtig fortælle dig meget om, hvordan jeg kom hertil, men det, jeg kan fortælle dig, er, at denne hule nu er mit hjem!$B$BJeg bruger min tid på at studere de mærkelige krystaller, der kan findes over hele krateret.",
    [2750801220] = "Du satte stykket på en småfisk og lagde småfisken et sted i havet mellem her og Østkongerigerne? Og denne småfisk har særlige kræfter?",
    [4260659761] = "Du kæmpede godt, Edvard. Lad os se, om Kahilo kan tage dem.",
    [2410011515] = "I pøbel, kom i gang med arbejdet.  Skibet skal være færdigt snart.",
    [982996588] = "Du kræver undervisning af en ægte herre! Gå til Darl Stak i Tarrenmølle og omfavn din skæbne!",
    [4046671118] = "Du risikerer at ødelægge os alle, $r! Du skal udslettes!",
    [58614706] = "Du sagde, du ville have den tilbage. Hvad betyder det?",
    [2068154177] = "Du skræmte fiskene væk!  Hvad vil du?",
    [967995231] = "Du skreg som en lille pige, det morsomste jeg nogensinde har set.",
    [480183369] = "I skarn er slet ikke min tid værd.  Ødelæg dem, min flok!",
    [817998538] = "Du ser store hulelignende tunneler og gange reflekteret inde i krystallen. Du genkender området som Lavakernen.",
    [4078909146] = "Du ser den svage kontur af en humanoide figur inde i kapslen; nu ved du, at dette netop er det sted, du skal være.  Selvom du tror, du til sidst kan åbne kapslen, sidder den stadig tæt lukket, selv for dine kraftigste forsøg på at åbne den.",
    [1449181085] = "Se, alt du skal gøre er at smede Svovlon-hammeren og finde dig selv Svovlras' Øje. Kombiner Svovlras' Øje med Svovlon-hammeren, så bliver den til Svovlras! Nu vil jeg ikke tynge dig med teknisk information om, hvor eller hvordan eller hvornår du kan få et Svovlras' Øje. Jeg er sikker på, du nok skal finde ud af det. Bare skriv under på kontrakten her, så vores aftale er bindende, og vores forretning er gjort.",
    [1967200081] = "Du søger en højere viden. Sypa er velsignet med sådan viden. Hun burde stå et sted i nærheden...",
    [242166055] = "Du søger en skurk?  Jeg tror, Janok ville passe til den beskrivelse.  Hvorfor går du ikke og taler med ham nede ved kroen i Dolanår.",
    [2233550856] = "Du søger død?",
    [3821912543] = "Du søger Grol'dar og Mørkeild-enklaven?  Find dem i den underjordiske hule kaldet Skyggeklyngen.  Der er to tunneler, der fører ned i hulen, en lige syd for Visdommens Dal og den anden fra Slæbet.",
    [1140320540] = "Du søger Kardris Drømmesøger.  Hun og den anden shaman er i indgangsrummet til Traels Fæstning i Visdommens Dal.",
    [1434690517] = "Søger du nogen, der holder af dyr?  Så burde du lede efter Seriadna udenfor kroen i Dolanår.  Hun er den, du søger.",
    [3493963354] = "Søger du hjælp fra en druide?  Så burde du opsøge Kål ved Månebrønden lige syd for kroen i Dolanår.",
    [2177743061] = "Søger du skeptersplinten, som er betroet Den Blå Flyvnings beskyttelse?$B$B<Azurøs ser ud til at smile.>",
    [1062529930] = "Du søger at lokke generalen for Frostulv-legionen ud af hans fæstning? UHØRT!",
    [3081490315] = "Søger du at skade mig, $r?",
    [2075513861] = "Du søger at sænke vores globale forsvar for at tækkes en paranoid magistrat og en lejr af rakkerpak, der sikkert lider af hedeslag.",
    [2613528769] = "Søger du at lokke mig fra mit æggekuld? Du skal betale for din frækhed!",
    [9345310] = "Du virker selvsikker. Du har vel ikke noget imod en prøve på dine evner?",
    [3963295845] = "Du skulle være blevet hjemme.",
    [1714962538] = "Du burde ikke være her! Dræb dem!",
    [3558466912] = "Du burde tale med Vinstone. Jeg hører, han leder efter tyve med din færdighed.",
    [2496073874] = "Du viser dig at have lidt værdi alligevel. Lystra tilkalder en overraskelse til vores unge rekrutter.",
    [2093017447] = "Du viser visdom ud over dine år, $c.  Tak. Du finder vores slagmester, Lylandrys, stående ved krigsbordet i Våbenhallen. Hun kan hjælpe dig med at rejse til Krigssang-Gulch.",
    [1655919260] = "Du viser visdom ud over dine år, $c. Tak. Du finder vores slagmester, Lylandrys, stående ved krigsbordet i Våbenhallen. Hun kan hjælpe dig med at rejse til Krigssang-Gulch.",
    [3275427848] = "Du så lille og pjusket... du ikke gøre gode tjenere for Kormøk!",
    [75455196] = "I ynkelige sække af maddikekød kan gøre det bedre end det, så bevis det nu!",
    [1175396904] = "I reservedele!  Vi laver flere Svøben i nekropolen.",
    [2213783109] = "Du har stadig lektioner at lære, før jeg må begynde din træning. I mellemtiden kan Vahn i Tordenklippe måske hjælpe dig.",
    [3930228119] = "Du overgav dig.  Jeg vinder.",
    [327655363] = "Pas godt på dig selv! Jeg smutter væk herfra.",
    [1920706217] = "Du fortæller en utrolig historie, Skønbanks. Hvad med klingen? Er den ude over forløsning?",
    [1747353340] = "Hov, du der!  Ja, dig!  Du ser tørstig ud.  Kom herhen, jeg har lige præcis det, du har brug for!",
    [572222598] = "Hov, du der!  Du ser rask ud... vi har brug for din hjælp til at forsvare Sydstranden!$B$BDe forbandede De Forladte er helt oprørte, fordi det er Helligaftens Ende.  Deres \"fejring\" vil uden tvivl føre dem lige til vores dørtrin.  Hvis du har tid, kunne vi virkelig bruge din hjælp!",
    [1032200686] = "Hov, du der! Tjek den lyd.",
    [2275076871] = "Hov, du der. Du er velkommen til at tage indholdet af min kedel. Det skulle have været anden fase af min plan - forførende klæder.",
    [388388651] = "Hov, du der... det er i din egen interesse at hjælpe De Forladte i disse dystre tider.  Lyt nøje, for jeg bryder mig ikke om at gentage mig selv.$B$BVi står lige nu i en alvorlig mangel på klæde.  Bandager og simple tekstiler er ved at løbe tør, og donationer modtages for at styrke de hængende lagre.  Du får ikke økonomisk kompensation - deraf navnet donation - men din hjælp vil ikke gå ubemærket hen.",
    [829061860] = "Tror du, du kan tilkalde os? Det er os, der tilkalder, ikke dig! Vi banker dig godt for det og suger marven ud af dine knogler!",
    [1698545083] = "Tror du, du har mod?  Nå, jeg har noget til dig, hvis du har...",
    [2200544903] = "Tror du, du har det, der skal til for at ødelægge Arator-ligaen, $c? Det håber jeg. Hvad er det, du vil have, eller er du bare her for at spilde min tid?",
    [2999201558] = "Tror du, du bare kan gå hen til mig, så begynder jeg at undervise dig? Ha! Du skal betale din kontingent ligesom alle andre!",
    [1703048082] = "Tror du, du er klog nok? Tror du, du har det, der skal til? Lad os finde ud af det!",
    [3124403437] = "Tror du, du har vundet allerede? Måske får du brug for endnu en lektion i smerte!",
    [1916075424] = "Du kastede sidste gang, idiot. Nu er det min tur.",
    [1100583417] = "Du vender kroppen om og ser mærkerne fra klinger og besværgelser på den døde orkkvinde--hendes rustning næsten ødelagt, hendes hår klistret til ansigtet.$B$BIfølge Mankrigs beskrivelse af hende er der ingen tvivl i dit sind om, at dette var hans kone.$B$BHan vil blive oprørt over nyheden, men du er sikker på, at han bør kende sandheden.",
    [1095090265] = "I to er uden tvivl skæbnebestemte elskere, der har fundet hinanden. Der venter jer masser af lykke i fremtiden.",
    [319636970] = "I to vil få mange op- og nedture, men hvis I kan holde ud, vil turen være det værd.",
    [2860995551] = "I tobenninge er ingenting! Mine børn kunne slå jer!",
    [2159233676] = "Du vil have kamp? Kamp skal du få!",
    [3652506333] = "Du vil have et våben, der er en forlængelse af din egen knytnæve? Ja, jeg tror, jeg kan vise dig noget.",
    [4146853989] = "Du vil have min hjælp? Den får du. Hvad har du brug for?",
    [1540758147] = "Du vil have Legendernes Hal. Den ligger højt over Styrkens Dal på vestsiden. Hvis du ikke er officer, kommer du ikke ind, men du kan stadig tale med Sergent Ba'sja udenfor.",
    [3696022893] = "Du vil vide noget om rationsindsamlinger? Meget godt. Sidst jeg hørte, havde Horden forberedt $2095w ud af $2096w magre ulvesteaks. Vi har også pakket $2102w af $2103w plettet gulhale væk og $2105w ud af $2106w bagt laks, der er nødvendige.",
    [1069800140] = "Så skal du tale med Osbjørn. Der findes ingen bedre lærer i snigskjulets kunst i Stormvind end ham. Led efter ham nede i Gamlebyen.",
    [4222550445] = "Vil du træne? Med mig? Fantastisk! Det eneste, der er bedre end at samle kugler og sprængladninger, er at dele den viden med en anden! Lad os komme i gang!",
    [158936156] = "Du vil have Sjamja ved Brændstans Bålsted på den øverste etage i Slæbet. Gå op ad trappen til venstre, når du træder ind i Slæbet fra Styrkens Dal.",
    [1178299235] = "Du spilder min tid, så gå og tal med min elev Basilikum.",
    [624366219] = "Pas på, hvor du træder rundt her, $Gsøn:pige;. Du er måske ikke en del af vores trop, men det betyder ikke, at jeg ikke tager en stok til dig, hvis du falder ud af række!",
    [332488422] = "Du var altid bøvlepetteren i familien, Noggel. Altid!",
    [3593053199] = "Du gjorde klogt i at komme. Min visdom skal blive din.",
    [3292964679] = "Du har ret, Skønbanks. Det er tragisk.",
    [4031183338] = "DU VAR SÅ EN GOD SPORTSMAND SIDST...KOM FREM!",
    [1780340714] = "Du fortalte mig om Den Tilslørede Klinge, og hvordan du tog den forkerte mission.",
    [666713994] = "Du gjorde klogt i at opsøge mig. Jeg vil bede om en lille tjeneste. Til gengæld er der meget, jeg kan lære dig.",
    [123242705] = "Det var du. Øjet tager aldrig fejl.$B$BDu er trods alt en $g præst:præstinde;. En mægtig $g præst:præstinde;, hvis Øjet viste dig denne forfærdelige erindring.$B$BDu er kommet for at finde forløsning, men det indser du selv ikke engang... Gør du?",
    [1752363815] = "Du var ikke energiforbruget værd. <Nathanos spytter.>",
    [904989553] = "Du vil rette dig efter vores regler her, slyngel!",
    [2856311806] = "I skal alle betale dyrt, når jeg vender tilbage fra dybet!",
    [4132785264] = "Du bliver let bytte, $C.",
    [2781063368] = "Du vil blive tilgivet, Eranikas. Elunie vil altid elske dig. Bryd fri af de lænker, der styrer dig!",
    [2156542186] = "Du vil blive fængslet og stillet for retten for landsforræderi, Vindsor. Jeg vil se med glæde, når de afsiger en skyldig dom og dømmer dig til døden ved hængning...",
    [2333460143] = "I vil blive dømt for at besudle disse hellige grunde! Oldtidens Folks love vil ikke blive udfordret! Indtrængere vil blive udslettet!",
    [2431408080] = "Det går nok, Awbi. Dine angribere er blevet elimineret.",
    [827635085] = "Du vil blive sat på prøve mange gange af mørket, der omgiver vores lande, $N. Men for at sikre, at du altid er klar, vil vi ofte bede dig om opgaver, så du er på højden af din egen kraft.$B$BGå med Let, og forbliv dydig.",
    [4062138610] = "Du vil forråde dine venner.",
    [2021748382] = "Du vil dø.",
    [382825842] = "Du vil finde Fineous Mørkvinge hinsides Lovens Ring, i Håndværkshallen. Dræb den elendige køter og hent Jernfel.$B$BTag Jernfel til Tårissans Helligdom, og anbring hammeren på dens rette plads: I hænderne på statuen, der er rejst til min ære.$B$BNår dette er gjort, åbner rummet, hvor jeg opbevarede hovednøglen, sig. Endnu vigtigere: Jernfel vil for evigt forblive i mit greb. Skulle de forsøge at fjerne hammeren, vil både statuen og hammeren splintres og gå tabt for evigt.",
    [4108597174] = "Der findes ingen fred i døden.",
    [2178379991] = "Der findes talrige trænere rundt om Dolanår med årevis af erfaring, som kan undervise dig. Hvilken skal jeg pege dig hen til?",
    [1343392781] = "Du finder Pyall Stilleskridt inde i det store telt i landsbyens nordvestlige hjørne. Han kan lære dig det, du længes efter.",
    [2087523179] = "Du må undskylde mig, Lorakas, jeg taler ikke 'skørt'.",
    [101528713] = "Du beholder alle dine fingre og tæer, ingen grund til bekymring.",
    [1037422883] = "Du vil hjælpe os med at holde os sikre mod den onde frue, ja!",
    [1182283187] = "Du vil få at vide om fristedet, som kun døden kan byde på...",
    [1792759466] = "Du vil lytte til dette, grumme hertug! Jeg er ikke din Tusmørkets Hammers skødehund! Jeg er her for at udfordre dig! Kom! Kom, og mød din død...",
    [1177163384] = "Du vil leve evigt i pine for dette, patetiske hekser.",
    [3712561857] = "Du vil blive et passende offer for Ragnarøs.",
    [867848997] = "Du vil blive et passende offer!",
    [1085939506] = "Du vil blive et passende offer.",
    [852456690] = "Du må finde Nat Lommetyv i Støvsumpen for at blive bare lidt bedre end, du er lige nu.",
    [651491804] = "Du må åbne Ondhundsporer-sættet og læse instruktionsmanualen. Fremkald udyret, når du er i nærheden af klippejætternes halvø, syd for her.",
    [860016680] = "I vil aldrig besejre os!",
    [4159828672] = "Du vil aldrig stoppe De Forladte, $r. Den Mørke Dame skal få dig til at lide.",
    [769792967] = "I vil aldrig vække drømmeren!",
    [3796985501] = "Du vil ikke blive skuffet, rejsende. Skrædderi er et glædeligt forehavende.",
    [1035214465] = "I vil ikke besudle vores hellige land!",
    [2635491362] = "I vil ikke besudle disse mysterier!",
    [3344653716] = "Du vil ikke undslippe døden!",
    [3286237114] = "Du vil ikke undslippe din skæbne, Onyksia. Det er blevet profeteret - en vision, der genlyder fra de store haller i Karazhæn. Det ender nu...",
    [869524822] = "Du når aldrig til skovens kant, Krav.",
    [436878186] = "Du stopper mig ikke fra at flygte herfra, $r!",
    [2351400817] = "Du stopper ikke vores voksende skygge, $c. Nu... tilmeld jer os! Tilmeld jer rækkerne af De Udvalgte!",
    [2473716312] = "Du kommer til at betale for det...",
    [3882080163] = "Du skal betale for det, du har gjort mod Tre, $r!",
    [3713932608] = "Du skal betale den ultimative pris for denne frækhed, lille skadedyr. Din sjæl er min!",
    [936291610] = "Du vil omkomme her. <Dit sind fyldes med syn af kaos og ødelæggelse.>",
    [4202617581] = "Du skal lide evigt, $r.",
    [2848685586] = "Du skal lide under dette nederlag, Nefarian!",
    [2373410819] = "Du kommer nok til at snakke til sidst. Du kan lige så godt spytte det ud nu.",
    [4093434614] = "Du vinder, $n. Du vinder!",
    [427961954] = "Du ønsker at bistå Skænderne i deres kamp mod Arator-ligaen i Arathi-bækkenet? Fint, så skal du spørge Martin Lindsø om hans bistand. Led efter ham i Synets Pøle.",
    [4043617870] = "Du ønsker at hjælpe De Forladte i deres kamp mod menneskerne i Arathi-bækkenet? Så gå til Modighedens Hal og tal med Deze Snebane.",
    [1381816489] = "Du ønsker at høre om stenen? Følg mig.",
    [4288218050] = "Du ønsker at lære det gamle håndværk? Du ønsker at smelte mørkt jern?$B$BStil mig, $r. Vis mig et offer, så overvejer jeg det!",
    [2892024973] = "Du finder ikke bedre priser nogen steder!",
    [992327805] = "Du lærer ikke noget nyt af mig; du ved allerede for meget. Hvis du vil have mere træning, så tal med tyrefolket Ula i de nordvestlige butikker på Tordenklippes midterste plateau. Hils hende fra mig, hva'?",
    [3002908461] = "Du ødelægger ikke mine lande, din bundfald!",
    [871297474] = "Du arbejder med maskiner så længe, at du nogle gange glemmer de rigtige hjerter.",
    [2558334089] = "Du leder sikkert efter Mi'Lynn, hvis du har nogen som helst håb om at lære at blive skrædder. Hun bor på Håndværkernes Terrasse i det nordøstlige Darnassos.",
    [1264834466] = "Du ville jo ikke have hjulpet Sortklippe-legionen, hvis vi bare havde bedt om din bistand, vel?",
    [1720820762] = "Du! $n! Hvad laver du og vanker rundt i landsbyen sådan her? Der er Alliance-fjender i Alterac! Vi må drive dem ud!$B$BVores forsyninger er for små til at starte et stort landangreb, så tal med vores kvartermester. Han fortæller dig, hvordan du kan øge vores forsyningsgrund.",
    [1947448388] = "Du! Skriv dig ind i slagsmålet!",
    [3034470600] = "Du! $R! Kom herhen. <snøfter>$B$BTiden er knap, og min ende <snøfter> er nær. Kløvtand skal vinde; du skal se. <snøfter>$B$BMin fangst kan stadig bistå <snøfter> mit folk. Barbermanke-stammen er mægtigere end Børsterygerne!$B$BHorden vil finde ud af, hvem der står bag overfaldene på deres folk. Du <snøfter> skal bistå Kløvtand til gengæld for den information, kun jeg kender. Kløvtand kan hjælpe dig! <snøfter> Men du skal hjælpe Kløvtand.",
    [2617018102] = "Du må hellere ikke lave ballade, $n!",
    [2306565284] = "Du må hellere ikke sladre om mig!",
    [2920938367] = "Du finder Carolai Anis, der forsøger at sprænge sit hus i byens nordvestlige ende. Hvorfor går du ikke hen og ser, om du kan hjælpe hende?",
    [711102953] = "Du finder Ældre Grumtotem ved Lariss-pavillonen i Vildalas.",
    [3822492521] = "Du finder Ældre Stjernelysning uden for portene til Zul'Gurb i Kvælerdorn-dalen.",
    [3554821428] = "Du finder Kroværtinde Renee inde i Galgeenden Kro i den sydøstlige ende af gaden, der løber gennem byen.",
    [3275549814] = "Du finder ikke et finere rottespyd på denne side af Khaz Mødan!",
    [752297461] = "Du finder en af dem uden for Orgrimgrads Bank midt i Styrkens Dal.",
    [2773372000] = "Du finder den kobold og hans legetøjsbutik i Æresdalen.",
    [826823839] = "Du finder Magiker-træneren, Cain Ildsang, oppe på trappeafsatsen ved Galgeenden Kro, som ligger i den sydøstlige ende af Gryde-by. Jeg gætter på, at han checkede ind for sent til at få et værelse.",
    [2702768981] = "Du finder Vindrytter-mesteren i Orgrimgrad. Gå nordpå ad vejen for at komme derhen, og spørg en Orgrimgrad-fodsoldat om yderligere vejvisning.",
    [3441007723] = "Du bliver nødt til at være tålmodig med mig, $n. Jeg har min Spionbot inde og arbejde på en meget delikat sag. Jeg er hos dig om et sekund.$B$BÅh, og gør mig en tjeneste, prøv at undgå at lade Lescovær se dig... vi er lige ved at overfalde ham.",
    [3776262172] = "Du må give mig et øjeblik, $c, slangefolkene angriber os lige nu. Jeg taler med dig, så snart angrebet er overstået!",
    [2704241599] = "Du holder de onde folk væk, ikke?",
    [1617918632] = "Du må hen til Orgrimgrad for det. Følg bare vejen nordpå ud fra Barberbakken gennem kløften, så kommer du frem til den. Når du er der, så spørg en af deres fodsoldater om yderligere vejvisning.",
    [3970123551] = "Du må bevise din værdighed, før jeg giver mine hemmeligheder væk! Jeg har lige den rette prøve til dig...",
    [3895984819] = "I kommer aldrig til at få mig ud af min bunker, hedninge!",
    [3211409375] = "Du forlader aldrig dette sted i live.",
    [3972496921] = "Du finder ikke en større vidensskat end i Det Kongelige Bibliotek i Stormvind!",
    [3785153504] = "Du skal betale for at tvinge mig til at gøre det her!",
    [1556267868] = "Du skal betale for det!",
    [1433316674] = "Du kommer til at fortryde dagen, du krydsede mig, $n.",
    [494350304] = "Du vil gerne lære af Sjamja. Gå til Brændstans Bålsted på den øverste etage af Slæbet ved at tage trappen til venstre, når du kommer ind fra Styrkens Dal.",
    [3874668172] = "Du er en tåbe, der burde lytte til mine advarsler. Ingen er usårlig. Du ville være klog at huske det lille råd.",
    [4291614340] = "Du er jæger? Nåh, under alle omstændigheder finder du Tottar gemt for solen inde i hulen i byens sydvestlige hjørne.",
    [3315484067] = "Du er læderarbejder af profession, ikke? Det er den svage lugt af garvede huder, jeg ville genkende hvor som helst.$B$BMin far plejede at tale om en berømt håndværker, der boede i Sydvind-landsbyen for århundreder siden. Det er en skam, at stedet ligger i ruiner nu.",
    [1227777489] = "Du er altid velkommen her, $n. Tak for grinet -- og bekymr dig ikke om Darl, han fik lige, hvad han havde fortjent!",
    [2182236136] = "Du er alkymist? Det er jeg også. Måske kan du lære mig det, du ved...",
    [1604758778] = "Du er Astor Hadrøn, ikke?",
    [686325689] = "Du er vågen?? Din kurering må have virket! Tak, $n.",
    [2046450794] = "Du er allerede tilbage! Hvad kan jeg gøre for dig nu?",
    [2198937581] = "Du er bedre til det her job end mig! Du vil have en med endnu mere erfaring, end jeg har. Det må være Åndetil, en nattenisse-dame, der bor på Håndværkernes Terrasse i Darnassos.",
    [1861075141] = "Du er bedre til det her job end mig! Du vil have en med endnu mere erfaring, end jeg har. Det må være Doktor Herbert Halsøje, en udød, der arbejder i Apotekeriet i Undergrunden.",
    [2995202364] = "Du er kun orm under mine fødder. Tør du udfordre mig?",
    [3066927555] = "Du er død, ikke begravet. Vis mig nu dit bedste!",
    [204315941] = "Du klarer dig meget godt i skrædderkunsten, må jeg indrømme. Nu skal vi se, hvor god du VIRKELIG er...",
    [3342414197] = "Du er fyret! <Hoste... Kork rømmer sig.> Jeg mener, hjælp!",
    [238942107] = "Du er fri, Dugal! Forsvind herfra!",
    [4018683264] = "Du bliver varmere... 7039 grader Krakkenhed!",
    [930216528] = "Du er færdig, Mulvi!",
    [2020865575] = "Det skal nok gå fint.",
    [91276172] = "I skal betale for denne skandale! Vagter!",
    [3014359625] = "Du duer til ingenting, Ribbly.  Nu er det tid til at betale for din ondskab!",
    [3236227371] = "Du duer til ingenting, Ribbly. Nu er det tid til at betale for din ondskab!.",
    [783118611] = "Så du er her for at hjælpe med det tunge læder til Ahn'Kiraj-krigsindsatsen, $c? Godt, godt. Som du kan se, har jeg samlet $2066w, men vi får brug for $2067w samlet. Det er en masse flåning, min ven, så jeg håber, din kniv er skarp. Læderet går til alle slags formål, til at fremstille vores krigsmateriel og sikre vores succes.",
    [4051329162] = "Jagter du Dødsspænde, $n?  Du overrasker mig.  Jeg mistede to af mine mænd til hende alene i denne uge.  Lad os håbe, din held er bedre end deres.",
    [2935552524] = "Du gør hende ondt!",
    [299894641] = "Du er sindssyg.",
    [1833615979] = "Du er vild med læder, hva'?  Lyder som om du bør tale med Simon Garver nede i Gamlebyen.  Han driver en butik dér, der hedder Det Beskyttende Skind.",
    [1223892726] = "Du laver sjov, ikke? Jeg tror, du leder efter den ANDEN lille karl, Thonys Søjlesten. Han er nedenunder. Og nu: smut!",
    [3086026273] = "Du kommer lige til tiden, $c.  Mærker du jorden ryste under dig?$B$BNoget nærmer sig fra bistokken.  Tag plads ved fodsoldaterne, $n.  Jeg regner med dig!",
    [111180327] = "Du laver sjov, ikke? Okay, okay, bare ingen panik. Heldigvis, da jeg fortryllede den med komponenten, du hentede, tilpassede jeg mig den også. Jeg burde kunne finde den og tilkalde den, uanset hvor du har efterladt den.$B$BEr du sikker på, at du har tabt den? Har du kigget i alle dine tasker og i banken?",
    [1449629849] = "Du ser lidt fortabt ud.  Kan jeg hjælpe dig med at finde noget?",
    [1784367842] = "Du leder efter Lau'Tikki.  Du finder ham på Mørkspyd-tråden, ude forbi Sen'jin-landsbyen mod syd.",
    [1194061094] = "Du leder efter Mishiki-Blomsten.  Hun har en hytte mod syd i Sen'jin-landsbyen.",
    [1065976808] = "Du leder efter Tajjin.  Find hende i kasernen på byens østside.",
    [732258098] = "Du leder efter Urtrun Klanbringer i Hordens Ambassade.  Find den på vestsiden af Styrkens Dal.",
    [1771053099] = "Det finder du på.",
    [1251209471] = "Du holder aldrig op med at jagte mig, vel?  Fint, men du får mig ikke ned uden kamp!",
    [1101502867] = "Du er ingen heksemester, og jeg har ingen tid til dig.  Forsvind!",
    [3469810997] = "Du er ikke druide!",
    [1149898204] = "Du slutter dig ikke til nogen, Tordsen..",
    [1980152802] = "Du spilder ikke kun dine medstuderendes tid, du spilder også min.",
    [4081214832] = "Du tøjer den, $n.",
    [4141642949] = "Sælger du kølnvand og parfume?",
    [3835352889] = "Du tager godt form, $n. Jeg har hørt gode ting...",
    [3264234603] = "Er du stadig her?  Din dumdristighed er morsom!  Sølvdæmringens tøs behøver ikke lide forgæves.  Forlad stedet med det samme, så skåner jeg hende!",
    [3896064897] = "Du er sød at spørge, $c, men vi har alt det lette læder, vi behøver. Måske er en af de andre, der har ansvaret for indsamlingen her omkring, i behov for din hjælp?",
    [2216521717] = "Du taler til den forkerte ork. Jeg træner ikke nybegyndere. Snak med unge Vuut derovre... og brug små ord.",
    [4145279314] = "Sig mig det! Det er endnu mærkeligere, når man tager i betragtning, at Brand, Rudgar, mig og abe tilsammen kender 38 forskellige sprog, inkl. en lille smule Titan - både Vanerne og Æsirne.$B$BUanset hvad hun klikkede og klakkede om, var det i hvert fald ikke med nogen „til stede“. Så nikkede hun og gik til offensiven! Angreb os lige ud!",
    [1120787561] = "Du er den bedste, $n - tak fordi du gik pudsen for mig!",
    [19914377] = "Ingen årsag! Jeg må videre... pas på jer alle sammen.",
    [3096607645] = "Du arbejder dig op... højere end mig, på nuværende tidspunkt! Du bør tale med Kildespindel Sprudlegear i Jernsmede! (Han'll? Hun'll?) kan vise dig mere, end jeg nogensinde kunne!",
    [520786755] = "Du har accepteret min overgivelse.",
    [2433264776] = "Du har allerede lært alt, jeg kan lære dig, $n. Tal med nattenissen Lilyssia Nattevind i Magikerkvarteret i Stormvind, hvis du vil fortsætte dine studier. Jeg har hørt, at hun er en god lærer.",
    [770179078] = "Du har vredet mig for sidste gang, $n!",
    [3076472646] = "Du er blevet en ret så rask jæger, $n! Du har ikke blot vist dine færdigheder, du har også besejret Darl, hvilket giver dig ekstra punkter i min bog!$B$BDu er altid velkommen her.",
    [4255074429] = "Du er blevet MALEDE!",
    [1089930742] = "Du har været en utrolig stor hjælp! Disse knogler vil låse op for så meget ny information og hjælpe mig med at fremme min forskning.",
    [2493335774] = "Du er blevet tilkaldt af Lago Sortskruen, hekselærermester i Jernsmede. Du gør klogt i straks at melde dig hos ham. Du finder ham i distriktet Det Forladte Hulrum i byen.",
    [910042497] = "Er du kommet for at blive trænet, så du kan videregive det til dine kæledyrer?",
    [2289857045] = "Du er kommet længere end de fleste, $n. Respekter elementerne omkring dig, så klarer du dig langt bedre end de fleste.",
    [1636948157] = "Du har overbevist mig om dine intentioner, $n, og du har min tak, fordi du var villig til at hjælpe medlemmerne af mit tidligere lejesoldat-kompagni, Den Tilslørede Klinge.$B$BLad os se, hvad der står næst på vores liste over ting at gøre?",
    [1520558321] = "Du har ødelagt for meget af mit arbejde!  Gør dig klar til at slutte dig til dem i Nether!",
    [1972667917] = "Du har gjort alt, hvad jeg har bedt dig om, $n. Der er virkelig intet mere for dig her. Hvis du er interesseret i at fortsætte din karriere som agent for Thorium-broderskabet, så tal med Lokhtøs Mørkhandler i Dyster Slurk i Sortklippe-dybderne.$B$BFarvel!",
    [23205397] = "Du har gjort det, $n! <Den underligt velkendte stemme lyder til at komme fra fiolen!> Skynd dig tilbage! Faldout'et forbliver kun stabilt i tredive minutter.",
    [1724233047] = "Du har penge, og vi har mad.  Hvad venter du på?!",
    [2349101151] = "Du har mere mod end hjerne, når du kommer til mig uden den rette træning. Gå og tal med nogen tættere på dit niveau, som orken Kamarie, der bor i Trækket i Orgrimgrad.",
    [3395813068] = "Du har fanget min opmærksomhed.",
    [4216439218] = "Du har et virkeligt talent og en passion for at lave eliksirer. Der er dog én lille sag, jeg gerne vil have dig til at tage dig af.",
    [1977188884] = "Du har noget, jeg har brug for, Astor. Og det tager jeg nu.",
    [3841655324] = "Du har fået styr på det. Jeg kan ikke lære dig mere, men tal med Arthur Mørk, en De Forladte, der arbejder i Skurkekvarteret i Undergrunden. Sig, at jeg sendte dig.",
    [498272951] = "Har du hørt om Sporvognen?  For en tur den der er!  Du finder den i Dværgekvarteret, længere tilbage.  Og sørg for at holde arme og ben inde i sporvognen, mens sporvognen er i forslag.",
    [2476345128] = "Du har blandet dig i vores planer for sidste gang, tossede $c!",
    [1502898294] = "Du har fået en god start, men du har stadig meget at lære, $n.",
    [1462538021] = "Du har truffet den rigtige beslutning, $c.  Du finder vores slagmester, Glordrum Stålskæg, i Våbenhallen.  Held og lykke, $n!",
    [2448971633] = "Du har ikke rigtig haft en hest, før du har taget tøjlerne i en fint opdrættet Barak Tor'olsk bjergvæder, min ven. Kig gerne på disse fine følgesvende, enhver eventyrer er velkommen. De vil tjene dig godt, tro mig.",
    [3093890987] = "I har plyndret vores skatte alt for længe. Gør jer klar til at møde jeres vandgrav!",
    [3790618150] = "Du har brugt din tid på at studere det grundlæggende. Nu er det tid til at hæve indsatsen.",
    [301992973] = "Du har virkelig overgået dig selv denne gang, fru Kamrene. Ikke en plet skimmel at finde!",
    [2062479252] = "Du har genvundet et par ynkelige territorier. Patetisk. Snart vil de igen være vores!",
    [3142702524] = "Du har ødelagt dine egne lande, du får ikke ødelagt mine.",
    [347715431] = "Du har tjent vores sag med stor loyalitet, $n. Lad mig give dig en uendelig kilde til vores elementare kvintessens.",
    [567028103] = "Du har begyndt på en ærefuld vej, $n. Mine forfædre respekterer din villighed, men du får ikke min godkendelse, før du har fulgt mine opgaver til ende.$B$BDu ved, hvad du må gøre, hvis du vil bevise, at du er jæger i ånden.",
    [2346698487] = "Du, i harmoni med naturen, og kun dine evner til at overleve. Sådan har Moder Jord tænkt det sig. Du vil skulle finde Ond på Jægerhøjen.",
    [331465025] = "Du, soldat, rapporter tilbage til Kargat med det samme!",
    [834269495] = "Du skal også tjene!",
    [3361051043] = "Du... er den næste.",
    [879012604] = "Du... dør nu!!",
    [1131330043] = "Du... Rammen! Hvordan? Du må ikke... Den... Ødelæggeren...",
    [1802039263] = "Dig?$B$B<Lorakas griner.>$B$BDet tvivler jeg på.$B$BJeg står i disse ruiner og drømmer. Drømmer om den dag, hvor jeg fanger den elendige tyv Gorahammer Ambolt-revne.$B$BVi havde en aftale, ham og jeg. En aftale, han brød. Forrådt.",
    [2796975711] = "Dine handlinger skammer os alle, $c. Det gør ondt inde i mig, når jeg slår dig bevidstløs.",
    [1733191157] = "Dine handlinger skammer os alle, $c. Det smerter mig at slå dig bevidstløs!",
    [1645637209] = "Dine handlinger vil ikke blive tolereret!",
    [908473110] = "Din rustning er klar, $n.",
    [957387705] = "Din rustning ser skræmmende ud. Er du også skræmmende?",
    [3335524434] = "Dine angreb bremses af kulden, tror jeg!",
    [2069158947] = "Dine angreb er svage! Gå og øv dig på nogle kaniner, og kom tilbage, når du er stærkere.",
    [3484706512] = "Din base er tabt, dødelige! Af dens aske skal liv opstå!",
    [2076765756] = "Din base er tabt, pinlige dødelige!",
    [3088692491] = "Din kamp her er blot den mindste partikel i en verdensomspændende invasion, unge! Det er på tide, at du lærer om de magter, du står over for!",
    [1392887291] = "Dit blod skal være katalysatoren for De Gamle Guders tilbagevenden!",
    [646572329] = "Dit blod flyder til menneskehedens bedste, kætter!",
    [934810462] = "Din krop ser slidt ud, og din ånd er træt. Hvil dig under vores tag, og lad Elunie lede dine drømme.",
    [1849838246] = "Din trældom er ved at ende, Dom'rel. Jeg udfordrer dig!",
    [645438488] = "Dine knogler vil knække under min støvle, $r!",
    [2609968575] = "Din hensynsløse arrogance!",
    [2870940232] = "Din hjerteløse ligegyldighed over for Gurubashi-imperiets suveræne magt er blevet noteret. Indbyggerne i Zul'Gurb er blevet advaret om din tilstedeværelse.",
    [2211882694] = "Din læreevne har overgået min. Du bør tale med Bøna Vinterhov derovre for videre undervisning. Vær dog venlig ikke at tage for meget af hendes tid. Hun har brug for sin hvil.",
    [3708866593] = "Din udfordring er mislykket!",
    [4005607888] = "Din selvtillid er velbegrundet, rejsende. Nu kan din sande uddannelse begynde!",
    [2023240808] = "Dit mod vil svigte.",
    [3360838551] = "Din nuværende dygtighed overgår min undervisningsevne. Du bør spørge nærmere hos min gnome-kollega Trixie Hurtigskifte i Jernsmede!",
    [2657598319] = "Din død skal ikke have været forgæves, Tælan. En ny Orden er født i dag... en Orden, som vil vie sig til at udslukke det onde, der plager denne verden. Et ondt, der ikke kan gemme sig bag politik og høflighedsfraser.",
    [2621536081] = "Dine døde nærer min styrke!",
    [2288695167] = "Dine skiver er nu klar! Aktiver Norgannøns Skiver igen for at hente dem!",
    [2509022786] = "Dine skiver vil blive returneret til dig, når du har adgang til soklen.",
    [3312959878] = "Din uddannelse er næsten færdig. Én sidste opgave er alt, der står mellem dig og kulminationen af al din indsats...",
    [2108092340] = "Din uddannelse skrider godt frem. Du bør være stolt af dine præstationer.",
    [512833676] = "Dine bestræbelser er fuldstændig meningsløse, tosser! I vil aldrig kunne besejre mig!",
    [4036682308] = "Dine bestræbelser vil vise sig frugtesløse. Ingen skal stå i vejen for os!",
    [1823654058] = "Dit ærinde må betyde meget, $c, når det fik dig så dybt ud i sumpen...",
    [3161889869] = "Din eksistens er anerkendt. <Relikken forvandles til støv. Dit hoved dunker af nyvunden visdom. Noget ondt lurer i bjergets hjerte.>",
    [1988784320] = "Dine øjne vil lave flotte glaskugler!",
    [3354890113] = "Din familie siger hej, Ribbly. Og de vil have dit hoved!",
    [2038174805] = "Din skæbne er beseglet!",
    [3854618362] = "Din skæbne er beseglet, Glædiana! Du skal betale for dine overtrædelser mod Herre Valtalak!",
    [3717240972] = "Din skæbne er beseglet, Mokkevar! Du skal betale for dine overtrædelser mod Herre Valtalak!",
    [999007791] = "Dit dæmoniske våben er klar, $n.",
    [3988931043] = "Din lod er kastet, $c. I de næste par timer vil du finde din ånd i takt med din sande natur. Vær forsigtig, for din lykke - og din skæbne - er aldrig så klar, som du måske tror.$B$BHvis du har lyst til et lille glimt af noget at grubler over i din fremtid, så sig endelig til. Jeg vil gerne give dig en skriftlig spådom, forudsat at du har plads i din beholdning. Den er trukket ud fra den indsigt, du har vist, da du besvarede mine spørgsmål.",
    [962985205] = "Dine venner vil forlade dig.",
    [3854009188] = "Din fremtid er tåget. Koncentrer dig, og spørg igen.",
    [1814525554] = "Dine guder kan ikke redde dig nu, $c.",
    [4022902664] = "Dit hjerte vil eksplodere.",
    [640699857] = "Din Horde er intet mod Kolkarerne!",
    [2953489000] = "Din frækhed er forfærdelig, tosse! Jeg skal fråse i din sjæl!",
    [1444745904] = "Din afbrydelse koster mig dyrebar tid, så det bedre være godt.",
    [3897811255] = "Dit fængsel er vores!",
    [4209967122] = "Din slags?",
    [3241340311] = "Din viden er stor, rejsende. Du må lære af en, der er klogere end jeg. Mange historier er blevet fortalt om Josef Gregoriansens visdom. Du kan finde ham i Undergrunden.",
    [552039013] = "Din viden er mangelfuld. Vend tilbage til mig, når dine færdigheder i smeltning er vokset!",
    [4062074952] = "Din viden om eliksirer har overgået min, men du har stadig meget at lære. Gå op ad trappen mod sydøst og se Doktor Sump. Han vil lære dig ægte lidel--øhm. Han er en De Forladte, som vil træne dig videre.",
    [1573288066] = "Din leder har til huse ved dørtrinnet til Naxxrammas. Tror du ikke, han mærker presset?",
    [203454699] = "Dit liv er et passende offer for min herre, $c.",
    [2875297927] = "Dit liv er forbrudt!",
    [2418128083] = "Dit liv er mit!",
    [3930380262] = "Din blanderi ender her, $n! Herre Valtalak skal have sin hævn!",
    [967442341] = "Din blanderi i dæmoniske anliggender ender NU, dødelige! Stå over for den store fordærver - Xandiviøs!",
    [3673067815] = "Dit budskab nåede os, kommandør, men vores engagement her er på ingen måde godkendt af Storslået Korsfarer.",
    [1842776341] = "Dit sind er uskarpt. Gemmer du noget for mig?",
    [1555482108] = "Dine forrådnede rester skal tjene MIG som et vidnesbyrd om, hvad der sker, når man er dum nok til at trænge ind i mit domæne!",
    [1029701697] = "Dit navn vil blive husket gennem tidernes ende, $n. Søg Taim Vredetotem på Jægerhøjen, så hjælper han dig på vej til Alterac-dalen.",
    [1054419826] = "Dit næste valg venter.$B$BDu alene har besejret et forfærdeligt udyr, der har hærget landskabet, og tog dets øre som trofæ. Senere får du at vide, at din herre havde udlovet en dusør for udyrets død, og at en venlig, men fattig ridder, som du kender, forsøger at forsørge en familie med sparsomme midler og gør krav på udyrets fældning som sin egen. Du har ingen reel brug for penge selv, men du ved, at den fattige ridder lyver til egen personlige vinding.$B$BTag dit valg.",
    [2993969655] = "Dit næste valg venter.$B$BDu er på et diplomatisk hverv for din herre i et grusomt land, der i øjeblikket er i krig med dit. Krigen har været dyr for begge sider. Din opgave er at sikre en fred, der er ærefuld for begge folk.$B$BVed en diplomatisk middag hører du herskeren over det modsatte land hånligt fornærme din velvillige herre. Du er ret sikker på, at herskeren mente at sige det uden for din hørevidde, men ikke desto mindre har han besudlet din herres ære.$B$BTag dit valg.",
    [77821097] = "Dit næste valg venter.$B$BDu er din herres edsvorne bøddel. En mand er blevet sendt til dig for henrettelse som forræder mod herren og dit folk. Du kender denne person som en nær, dydig ven, der en dag forsvandt på mystisk vis. Du ved også, at de forbrydelser, manden blev dømt for, angiveligt førte til mange uskyldige civilisters død. Da han får øje på dig, tigger han om sit liv og hævder, at en højere myndighed har stillet ham i en falsk situation.$B$BTag dit valg.",
    [3042414024] = "Dit næste valg venter.$B$BDin bror søger at slutte sig til den prestigefyldte militære orden, som du allerede er en del af. Selvom du er sikker på hans engagement og loyalitet, er det hans talent og evne til at udføre ordenens strenge opgaver, du sætter spørgsmålstegn ved. Selvom du ikke er sikker på, at han kan leve op til udfordringen i ordenen - og dermed sætte dig og andre i fare - er du sikker på, at dit ord alene kan lukke ham ind eller holde ham ude.$B$BTag dit valg.",
    [1015871880] = "Jeres gamle liv, jeres dødelige begær betyder intet... I er nu disciple af herren, og I vil tjene sagen uden spørgsmål! Den største herlighed er at dø i herrens tjeneste!",
    [452607523] = "Min egen styrke nærer mig, $n!",
    [2855530542] = "Din smerte ender snart!",
    [787870196] = "Din vej er stødig, $n, for Washte Pawnes beslutsomhed er med dig.",
    [3673339605] = "Dit kæledyr er vidunderligt, Gerard, men hun har nok brug for et halsbånd med en klokke, tror jeg.",
    [380796617] = "Dine ubetydelige magier er ingen udfordring for Svøbens magt!",
    [849989264] = "Dine eliksirfærdigheder er langt over mine. Søg den udøde Doktor Herbert Halsøje i Apotekeriet i Undergrunden. Han har evnen til at træne dig videre, og du kan selv se hans folks elendighed på nært hold.",
    [3427381366] = "Dine forberedelser er fuldendt. Alt, der nu står mellem dig og din frygtross, er ritualet for Større Fremkaldelseskreds og bindingen af frygtrossens ånd...",
    [219807968] = "Din tilstedeværelse styrker vores nerver, $G Mester:Dame; $n.",
    [3944780501] = "Din jagt på at lære Drakonisk er forgæves, dødelige. Og hvorfor i alverden skulle du ønske at lære at tale det gamle sprog? Virkelig forbløffende...",
    [1822250584] = "Dit terrorvælde ender nu! Mød jeres undergang, dødelige!",
    [2647162753] = "Din kåbe er færdig, $n.",
    [345582763] = "Din søgen er næsten fuldført. Søg din sandhed i indgangsrummet i Traels Fæstning i Visdommens Dal.",
    [4120822053] = "Dine sikkerhedsforanstaltninger har svigtet. Tag dig af denne afbrydelse med det samme!",
    [231499865] = "Din færdighed i at brygge eliksirer må blive større, før du kan blive en af mine elever. I mellemtiden kan Sylvanna Skovmåne eller Milla Smukanker måske hjælpe dig, lige derovre.",
    [791183879] = "Din færdighed viser en varig hengivenhed til vores kunst, men jeg vil se yderligere bevis på din forpligtelse. Jeg giver dig en opgave. Udfør den, så er jeg tilfreds.",
    [2885004194] = "Din færdighed overgår min, men jeg har hørt, at Gamle Mand Hemming i Bytteviken har eksemplarer af \"Aborre og Du\". Det vil helt sikkert hjælpe dig med at øge din færdighed.",
    [3051631380] = "Din færdighed i smedekunst er enestående, $n. Tiden er kommet til at træffe en beslutning. Der er to veje, du kan vælge: Våbensmedens vej eller rustningssmedens kunst.$B$BVær advaret: Når du har valgt at hellige dig en vej, er der ingen vej tilbage. Den disciplin, hver vej kræver, giver ingen plads til hybrider.",
    [2754511667] = "Din færdighed er ikke ringe. Eftersom du tilsyneladende har tilstrækkelig erfaring, er der en sag, hvor jeg har brug for din bistand.",
    [2500415084] = "Dine færdigheder er uden for min rækkevidde. Det er tid for dig at møde nye udfordringer. Talentdan vil hjælpe dig med at forberede dig. Han står ved bordet derovre.",
    [987359634] = "Dine færdigheder udvikler sig pænt. Snart driver du din egen læderbutik. Jeg bliver glad for hjælpen, $n. Mine hænder er kun så hurtige, ved du nok? Der er så meget arbejde at gøre!",
    [2304355797] = "Dine færdigheder er utilstrækkelige til at lære det, jeg underviser i. Prøv i stedet at tale med Mok derovre. Han kan hjælpe dig, indtil du er klar til mere avancerede lektioner.",
    [1759335945] = "Dine færdigheder bliver virkelig ekstraordinære. Nu, lad os fortsætte din træning...",
    [3053161519] = "Dine færdigheder har overgået mine, unge. Gå og se Ula, som har en butik på Tordenklippes centrale plateau. Hun kan give dig den vejledning, du søger.",
    [4118808919] = "Dine færdigheder i alkymi er endnu ikke høje nok til at drage fordel af min undervisning. Måske hvis du taler med mig senere...",
    [794276802] = "Dit kranium skal pynte vores ritualalter!",
    [2001527404] = "Dine kranier skal jeg knække med hele Sortklippes styrke.",
    [1043442090] = "Din sjæl er bundet til mig nu!",
    [230255704] = "Din sjæl er dømt!",
    [664253955] = "Din sjæl er min, svagling.",
    [1319215595] = "Din ånd er ren, $n.",
    [3198651058] = "Dine ånder er svage, og dine slag er endnu svagere!",
    [1928724682] = "Dit stål er stærkt, din færdighed endnu stærkere. Tag dit stål og din styrke til min makker Shayis Stålraseri; hendes færdighed i rustningsfremstilling er uovertruffen, selv af mig.",
    [2576718693] = "Din stank vil tiltrække hver eneste drage i flere mil. Fortæl mig, hvad du vil have, og hurtigt.",
    [788122197] = "Din styrke er af bjerget. Din nåde er af vindene!",
    [3184581666] = "Dit talent overgår mit eget, ven. Tal med Tærn her; hans viden om læder er langt større end min. Jeg er sikker på, at han gerne tager imod endnu en elev.",
    [2239779464] = "Dine talenter topper! Du er virkelig inspireret. For at fortsætte din jagt på viden, tal med Georgio Bolerojakke i Stormvind. Han er højt anset og kan videreføre din undervisning.",
    [3398878844] = "Dine talenter i madlavning er lidt for lave. Måske kan jeg lære dig, hvad jeg ved, med lidt øvelse.",
    [2527716357] = "Din opgave er fuldført. Gør dig klar til at møde din undergang.",
    [3407278169] = "Din time er kommet, $n. Mester Kang venter...",
    [1504812283] = "Dit forræderi fremskynder bare din død.  Denne verden vil falde i mørke!",
    [3292242249] = "Din udødhed er ikke enden på dit liv, men begyndelsen. Det er op til dig at bestemme, hvor din skæbne ligger nu.",
    [1028862467] = "Din forståelse af læder er dybere end min egen. Måske burde du besøge Aayndia Blomstervind i byen Stjernelund i Askedalen-skoven. Hun har meget viden at tilbyde en elev med dine talenter.",
    [3975385350] = "Din forståelse af læder er dybere end min egen. Måske burde du besøge tyrefolket Krulmoo Fuldmåne i Taurajo-lejren i Ødemarken. Han har meget viden at tilbyde en elev med dine talenter.",
    [3270366148] = "Din sejr her fremskynder bare din død!",
    [3431949883] = "Din sejr skal blive kortvarig. Dagene for både Alliancen og Horden er ved at være forbi! Næste gang vi mødes, bliver det den sidste.",
    [380922821] = "Din stemme er hæs af at råbe, hva'?  Find Orgrimgrads Auktionshus i Styrkens Dal.",
    [2773784479] = "Dine onde sjæle skal fodre min kraft!",
    [4292269445] = "Din vilje er ikke stærk nok til at manipulere de kræfter, vi kontrollerer, $c.",
    [1870726749] = "Din vilje er stærk, og din hensigt er klar.$B$BMåske er du værdig...",
    [329350340] = "Din verden skal lide en ubarmhjertig ende. Mare kommer efter dig!",
    [3715913145] = "Yserå er mit svar.",
    [825896233] = "Ysidå lever takket være dit mod, $n.  Jeg står dybt i gæld til dig og skal hjælpe dig så meget, som det står i min magt.",
    [3745357165] = "Lækkert. Jeg har stor kærlighed til stegt Slettegænger.",
    [725736806] = "Saldimar kunne sikkert lære dig nogle nye besværgelser.  Han har for nylig fået en forkærlighed for at bo på Løvens Stolthed Kro, så du kunne prøve at tjekke et af værelserne og se, om han er der.",
    [3665813423] = "Zandø'zan fra Den Splittede Hånd. Hvordan kan Zandø'zan hjælpe dig? Det kan han ikke! Det vil han ikke!",
    [3398719465] = "Zanzara kan lave de gamle trold-fortryllelser med de rigtige komponenter. Denne magi vil hjælpe dig med at besejre Hakar og hans håndlangere.$B$BJeg beder kun om, at du bringer mig to genstande.",
    [3275514744] = "Madrin ser ud til at have god viden om madlavningens håndværk.  Hvorfor går du ikke hen og ser, om han vil vise dig nogle opskrifter?  Han laver som regel mad henne ved Kroen i Dolanår.",
    [816438285] = "Zajus og hans præster er i Ånde-hytten, som ligger i Ånders Dal.  Led efter den ovenfor søen og mod vest for Styrkens Dal.",
    [1137519107] = "Zoom, zing, og BAM! Han havde måske en kæmpe tohånds-kløver lavet af et bådanker, men efter nogle få velplacerede skær fra min middagskniv var det ham, der gik ned med et brag!",
    [2334090382] = "Zug zug! Glad for at hjælpe!",
    [665828352] = "Zug zug, modige $c!  Jeg har de fineste avlede ulve-ridedyr, du kan kigge på.  Du finder ikke noget andet dyr med så højt niveau af udholdenhed og overlevelsesinstinkt som ulven, nogen steder!  Vær venlig at inspicere dem selv.",
    [2999586084] = "Zug zug, min ven!  Jeg er Kelm Hårdgrynt, hovedleverandøren til Krigssang-forposterne.  Efterhånden som du forbedrer dit ry hos forposterne, vil jeg gøre et fint udvalg af varer tilgængeligt for dig, som du kan bruge inde i Krigssang-Gulch.  Skulle du få brug for reparation af genstande, tilbyder jeg også den slags tjenester.",
    [506879518] = "Zul'Farak",
    [1362898487] = "Zul'Farak - Sergent Blæk - Standardhilsen.",
    [2523087042] = "Zul'Farak - Veglis Sprængsikring - Standardhilsen.",
    [1568181092] = "Zul'Farak i Tanaris-ørknen er Ældre Vildmankes hjem.",
    [2906925419] = "Zul'jin vender tilbage en dag, $r. Husk mine ord. Indtil da holder vi alle vores positioner og gør, hvad vi kan, for at holde skovtrold-bestanden intakt.$B$BMed det sagt, som herre-jæger i Hævnhugtand-landsbyen er det mit ansvar at sikre, at verden omkring os er sikker at bo i.$B$BBæsterne i dette område skal holdes i skak.$B$BLeder du efter arbejde?",
    [1704071083] = "|cff33ccffAlle fire tårne er nu under Alliancens kontrol!|r",
    [651537417] = "|cffff0000Alle fire tårne er nu under Hordens kontrol!|r",
    [2229083849] = "|cffffff00Kronvagtens Tårn er blevet modtaget af Alliancen!|r",
    [1600933117] = "|cffffff00Kronvagtens Tårn er blevet modtaget af Horden!|r",
    [1668601966] = "|cffffff00Østmur-tårnet er blevet modtaget af Alliancen!|r",
    [3684405115] = "|cffffff00Østmur-tårnet er blevet modtaget af Horden!|r",
    [3047195494] = "|cffffff00Nordpas-tårnet er blevet modtaget af Alliancen!|r",
    [474740103] = "|cffffff00Nordpas-tårnet er blevet modtaget af Horden!|r",
    [1063872476] = "|cffffff00Pestskov-tårnet er blevet modtaget af Alliancen!|r",
    [1723939750] = "|cffffff00Pestskov-tårnet er blevet modtaget af Horden!|r",
    [372338438] = "Jeg vil øve mig og blive en kriger ligesom min far!",
    [2728261204] = "...Simson, Jorik, Kamlej...",
    [3205805434] = "<Over-Inkvisitor Skønbanks ryster på hovedet.>$B$BNej, $r; kun én af hans sønner er død. Den anden lever...$B$B<Over-Inkvisitor Skønbanks peger mod himlen.>$B$BYderlandet... Find ham dér...",
    [1100676907] = "<Over-Inkvisitor Skønbanks ryster på hovedet.>$B$BNej... Han stod i baggrunden og så på, mens de udødes legion faldt over os. Kort efter var mine kræfter opbrugt. Jeg var den første, der faldt... De ville sikkert rive mig fra hinanden lem for lem, mens jeg lå der bevidstløs; men de ignorerede mig fuldstændigt og rettede al deres opmærksomhed mod Højlorden.",
    [2707224933] = "<Tarsiss' øjne lyser op.>$B$BEngang holdt jeg den... Jeg holdt den trods advarslerne fra Kirin Tårn. Jeg holdt den, dødelige... Kraft uden ende. Kraft til at gøre, hvad jeg ønskede, som jeg ønskede. Og lige så hurtigt blev den taget fra mig. Men jeg havde smagt... Og den smag var alt, der skulle til.",
    [2960032440] = "<Trael ler.>$B$BNoteret... Nu skal du høre efter, $n. Den Sorte Drageflugts yngelmoder, Onyksia, er blevet drevet ud af sin magtposition i Stormvind. Hun er sluppet væk og flygter til sin hule i Støvsumpen.$B$BHun kan ikke få lov til at leve så tæt på vores hovedstæder. Vi må slå til, før vi bliver slået!$B$BJeg vil have hende ødelagt, $n.",
    [711074312] = "En levende legende...",
    [2253255413] = "En hvilsom søvn er sikker i de senge, Krovært Kildemyr holder i Kroen i Dolanår.",
    [1126269314] = "Aaahhh... Endnu en glorværdig sejr for Horden!",
    [2442879322] = "Ah er meget overrasket over, at en med så uagtsom natur er kommet så langt...$B$BJa, du må få en fortryllelse mere, men Mo'ari er meget utilfreds med dine handlinger!$B$BGå, nu.",
    [1260018588] = "Ah, $r... Ah besidder stor viden o' verden og hvordan man skaber fortryllelser a' stor kraft.",
    [39042458] = "Ah, du leder efter Lucan Kordel.  Han driver en butik uden for Magikvarteret på vej til Palisaden.",
    [439587545] = "Ah... heltene. I er vedholdende, ikke sandt? Jeres allierede her forsøgte at måle sin kraft mod min - og betalte prisen. Nu skal han tjene mig... ved at slagte jer.",
    [34721645] = "Ahhhhh!!!",
    [1955504712] = "ØL!",
    [1261215959] = "Jaja, jaja. Under alle omstændigheder, så jeg sneg mig lidt ind i skyggerne.$B$BDet faldt ikke lige i god jord hos Vindsor, for han var jo allerede ekstra sur. Nå, så begyndte han at svinge gamle Jernfjende rundt og skrige som en gal mand af sted mod orkerne.",
    [73666590] = "Anatera!",
    [358030734] = "Og mens dit slappe lig hænger fra tagbjælkerne, skal jeg nyde at vide, at en gal mand er blevet henrettet. Hvilke beviser har du egentlig? Forventede du at komme herind og pege fingre ad kongelige og gå uskadt derfra?",
    [1150543619] = "Og nu ved du alt, hvad der er at vide, dødelige...",
    [1607782799] = "Anu'dorini Talah. Ru shallora enudoril.",
    [2057298398] = "Er ye virkelig spørgin' mig, hvor Smeden er?  Har ye ikke hørt om Den Store Smedje!?  Alle vores bedste smede samles der for at fremstille deres våben og rustninger!  \n\nDen ligger lige midt i Jernsmede, og der finder du en af vores mest geniale smede, Bengus Dybsmedje.",
    [1513132720] = "Aaarrgh!",
    [217364118] = "Som ung nattenisse i Mørkekysten krydsede jeg vejen for en gruppe usle individer kendt som Tusmørkets Hammer. Nogle af dem blev venner med mig, og skamfuldt endte jeg med at forkaste min tro på Elunie og omfavne Tusmørkets Hammers galde.$B$BDet var først, da en vision kom til mig fra Elunie, at jeg vågnede af den sløvhed, jeg var faldet ned i som tilhænger af de gamle guder.$B$BI anger begyndte jeg at arbejde på min bøn til Elunie.",
    [3097031] = "Askebringer...",
    [3366539516] = "Bygget for tolv tusind år siden af en hemmelig sekt af nattenisse-troldmænd blev den gamle by Eldre'Thalas brugt til at beskytte Dronning Azsyras mest værdsatte arkane hemmeligheder. Selvom den blev hærget af verdens Store Sønderrivelse, står meget af den vidunderlige by stadig som det imponerende Rædselshammeren. Ruinernes tre adskilte kvarterer er blevet overrendt af alle slags væsener - især de spektrale højfødte, onde satyrer og brutale oger.",
    [290865221] = "Kan I se jer selv? Det er det mest patetiske forsøg på sværdsvingning, jeg nogensinde har set!",
    [666231621] = "Cenarus kæmper ved min side. Illidan sidder på sin trone i Yderlandet - grublende. Jeg frygter, at tabet til Arthæus blev hans brudpunkt. Galskaben har omfavnet ham, Remulos. Han gentager begivenhederne i sit sind tusind gange om dagen, men i sit sind er han sejrherren, og Arthæus er fuldstændigt besejret. Han er gået for langt, gamle ven. Jeg frygter, at tiden snart kommer, hvor vores bånd sættes på prøve, og det vil ikke være, som det var ved Brønden i Zin-Azsyri.",
    [3122884529] = "Klemens, Bartolomæus, Endermand, Vajles...",
    [4033622157] = "Skabt af de samme ranker som Tornekrattet er Tornehøjene den traditionelle hovedstad for tornesvinenes race. Det udstrakte, tornefyldte labyrint huser en sand hær af loyale tornesvin samt deres ypperstepræster - Dødningehoved-stammen. For nylig er der dog faldet en truende skygge over det primitive hul. Agenter fra den udøde Svøben - ledet af liskken Amnenar Koldebringer - har overtaget kontrollen over tornesvinenes race og forvandlet tornelabyrinten til et bolværk af udød magt.",
    [4249402947] = "Dødsvinge, eller Neltharion som han engang var kendt som, var Aspektet, der legemliggjorde verdens styrke - tildelt næsten grænseløs magt over dette dødelige rige af Titan-formeren kendt som Khaz'gorot: Verdens Smed.$B$BGennem forræderi og svig overtalte den onde de fire andre Aspekter til at indgyde en genstand, kendt som Dæmonsjælen, med deres kræfter - hvilket svækkede dem voldsomt og tvang en splittelse blandt de engang så store Aspekter.",
    [1874036929] = "Dokumenter såsom papirer til klanskabelse kan fås hos Klanlederen i byen Darnassos.",
    [4183669] = "Undlad at komme ud af skyggerne sådan. Næste gang så giv en pige lidt advarsel.",
    [3034093709] = "Elunies hemmeligheder er mange, men de skal ikke deles med hvem som helst.",
    [651999089] = "Nok! Jeg bliver træt af disse distraktioner!",
    [220958389] = "Endelig frigivet fra hans forbandede greb. Far, jeg kommer...",
    [1675009007] = "Fiskeri er bare så behageligt, makker. Ved du? Jeg skylder min lykkesalighed min mentor, den største fisker i hele verden - Nat Lommetyv. Har du hørt om ham, makker?$B$BHvis du leder efter oplysning, så er Nat Lommetyv ham, der skal vise dig vejen.",
    [1346753691] = "ILD! DØD! ØDELÆGGELSE! Krymp, dødelige, for Herrens vrede... NEJ - JEG MÅ KÆMPE MOD DETTE! Aleksstrasa hjælp mig, JEG MÅ KÆMPE MOD DET!",
    [1850826931] = "Tåbelige $n, du tjener mig nu!",
    [3386911582] = "Tilgiv mig, $n! Din død tilføjer kun til min fiasko!",
    [1278715827] = "Frustreret over Dalarn-troldmændenes manglende fremskridt mod de udøde under Den Tredje Krig valgte Ærkemager Arugel at tilkalde de dimensionsfremmede varulve for at styrke sin side, der var ved at tynde ud. Ulvemændene slagtede Svøben, vendte sig derefter hurtigt mod troldmændene selv og lagde belejring under fæstningen tilhørende adelsmanden Baron Silverlaine. Borgen faldt hurtigt i skygge og ruin. Gal af skyld adopterede Arugel varulvene som sine børn og trak sig tilbage til den nyligt døbte 'Skyggetandsborgen'.",
    [270262045] = "Hent nøglen og lås disse kæder op! Hitah'ja Vogteren har den... bagerst i hulen...",
    [682722802] = "Gletsjerkappe.",
    [3218496566] = "Gletsjerhandsker.",
    [2939146395] = "Gletsjervest.",
    [1195528832] = "Gletsjerhåndled.",
    [481953492] = "Hilsner, ven!  Kan jeg interessere dig for nogle ektoplasmiske kondensatorer?  Eller måske en pæn omnidirektionel spektral assimilator?",
    [1752301301] = "Grrrrr!",
    [2569266463] = "Hej der! Mit navn er Jenna! Og dit?",
    [2804864609] = "Hej?",
    [1472757389] = "Hip hip... arrrrr...",
    [1562106178] = "Hm...",
    [3792393908] = "Hmm...",
    [4081484039] = "Hup...Hup...Bløøøøh!",
    [1145357242] = "Jeg er slangekongen! Jeg kan gøre hvad som helst!",
    [4172006234] = "Jeg beder jer, dødelige - FLYGT! Flygt, før jeg mister al kontrol! Den sorte ild raser i mit hjerte! JEG MÅ- frigive den!",
    [936266888] = "Jeg gider ikke høre det, $n. Nej, der er ingen måde, du får lov til at komme ind i Svidningskløften. Umuligt. Det sker ikke. Hvor mange gange skal jeg sige det - jeg kan ikke lukke dig ind! Taler du ikke fælles tungemål? Er du en ork i forklædning? N-E-J. NEJ!$B$BHvis jeg lader dig komme ind, så må jeg lukke alle ind. Snart vil dine nære venner også ville ind, så deres fjerne slægtninge, så deres venner, og så videre og så fremdeles. Sidste gang det skete... ja, vi taler ikke om den sidste gang, det skete.",
    [1032228369] = "Jeg har ikke tid til at passe børn! Gå og tal med min assistent, Uthrar!",
    [3564508659] = "Jeg havde det hele!  Jeg havde det hele, og så mistede jeg det.  Tabt... alt væk... ligesom... mit sind.  Mit sind er som... ost.  Jeg kan lide ost.",
    [2023282617] = "Jeg har lige færdiggjort en ny dimensionel imploder, der vil gøre mig rig ud over mine vildeste kobold-drømme!   Alt, hvad jeg skal gøre, er at få en dygtig Nisse-ingeniør til at bygge en dimensionel rivemaskine, der forbinder til den, og prøve den!",
    [1153173812] = "Jeg lytter og lytter, men jeg hører ikke de ånder, Kårn taler om.",
    [3894111643] = "Jeg formåede at opdage, at visse dele af hjernen, når de fjernes eller stimuleres, gør et emne langt mere føjeligt.",
    [4273509177] = "Størstedelen af min våbentræning fik jeg af Ilenia Månebrand på Krigerens Terrasse.  Du gør klogt i at opsøge hende, hvis du ønsker at lære at bruge et nyt våben.",
    [2943317465] = "Jeg er en simpel mand, der kender et par ting om skrædderi, men du har brug for mere hjælp, end jeg kan give. Jeg har hørt om en nattealf, der er en ret dygtig skrædder. Han holder til i Stormvind, i Magi-distriktet.",
    [3149733647] = "Undskyld, jeg har det lidt travlt lige nu med at smede hestesko til Verner Osgod i Søshire.",
    [3865163640] = "Jeg har ventet...$B$B<Rumlat hoster.>$B$BUndskyld, gammel vane. Jeg er Rumlat fra Jordringen.",
    [3952181185] = "Jeg kom, ligesom mange andre, for at bistå mine druidekolleger, da krigen brød ud.$B$BNu hvor Ahn'Kiraj-portene er åbne, er det gået op for mig, at der stadig er meget arbejde at gøre.  Jeg har besluttet at blive i Silitus og gøre mit bedste for sagen, $n.",
    [4221710589] = "Jeg... jeg er slemt såret...",
    [1378867376] = "Jeg...har...fejlet.",
    [3855438323] = "Isbane-armbeskyttere.",
    [2301339153] = "Isbane-brystplade.",
    [3805424618] = "Isbane-handsker.",
    [1276311574] = "Isnende Skæl-armbeskyttere.",
    [255618831] = "Isnende Skæl-brystplade.",
    [4194829816] = "Isnende Skæl-handsker.",
    [1963175954] = "Ishnu-hej... Oshalan tara dørmil... Anu'dorin...",
    [1608825629] = "Isfuglien!",
    [1819527232] = "Det er... som det skal være.",
    [2688510850] = "Det kræver lidt øvelse at komme så tæt på silitiderne uden at blive set.  Jeg anbefaler ikke at prøve det, hvis du kan undgå det.",
    [209033587] = "Tilmeld dig en gruppe, der går til dette fangehul.    <Dette valg placerer dig i en mødesten-kø>",
    [3795867152] = "Beliggende i Dun Frostbakke har Nisseborgen i generationer været gnomernes hovedstad, men den blev for nylig hærget af mutante trogger. I et desperat forsøg på at slå tilbage beordrede Højtinker Mekkatorque en nødudluftning af byens radioaktive affaldstanke. Selvom troggerne blev bestrålet, fortsatte deres belejring uformindsket, og gnomerne var tvunget til at søge tilflugt i dværgebyen Jernsmede, hvor Højtinkeren nu hverver modige sjæle til at hjælpe sit folk med at genvinde deres elskede by.",
    [1338635570] = "Kig op over dig; tara dørmil dorah...",
    [2419641739] = "Vil du tage en gryfontur, hva'? Dungar har sine fugle oppe på voldene i Handelsdistriktet. Husk bare at holde godt fast!",
    [4087463080] = "Malfurjon!",
    [1146595561] = "Mange er kommet til dette fristed, få er gået derfra.",
    [1695927760] = "Marodon er et af de mest hellige steder i Forødelse. Det store tempel/hulerum er begravelsesstedet for Zætar, en af to udødelige sønner født af halvguden Cenarus. Legenden siger, at Zætar og jordelementar-prinsessen Terradras avlede den misdannede kentaurrace. Det siges, at de barbariske kentaurer, da de kom frem, vendte sig mod deres far og dræbte ham. Nogle mener, at Terradras i sin sorg fangede Zætars ånd inde i de snoede huler – og brugte dens energier til et ondskabsfuldt formål.",
    [2747592160] = "Mårtens, Rebløk, Adinaj, Nikesøn...",
    [3828778001] = "Mester-håndværker Omarjon forsvandt bare en nat. Som en prut i vinden... Puf! Væk! Bah, nu er jeg den eneste tilbage til at fremstille varerne til drengene på frontlinjen.",
    [3640748668] = "Mattias fandt mig efterladt for død af Ventureselskabet i Ødemarken. Havde det ikke været for ham, var jeg blevet snigerfoder.",
    [3277583690] = "Min søns sjæl vil ikke finde trøst i denne hule sejr, drage. Jeg vil have ham tilbage. Selvom det tager årtusinder, VIL jeg have min søn tilbage!",
    [3554118050] = "Skurkius' had har gjort mig stærkere end nogensinde! I skulle have flygtet, mens I kunne, dødelige! Sortklippes raseri strømmer gennem mine årer!",
    [913809026] = "Godt forsøgt, men du skal have noget mere erfaring, før du træner med mig! Tilbage i skyttegravene!",
    [1254884250] = "Ingen del af de dyr, vi jager, går til spilde.",
    [1467225969] = "Nej, $n, det gjorde du ikke. Jeg bebrejder dig dog ikke, for dit sind minder meget om mit, dengang jeg var ung: Impulsivt, oprørsk og ofte uden en eneste sammenhængende tanke! Træk, som jeg ikke længere har råd til at vise.$B$BNok klynkeri. $R, jeg har en opgave til dig; en du måske ikke overlever.",
    [3515972057] = "Gå nu tilbage hjem, hvor du hører til!",
    [3709193838] = "Øv! I søger træning i krigerens vej, gør I?  Kelstrøm Stenbryder skal nok få jer igennem jeres øvelser!  Bare marcher jer over til Våbenhallen øst for Jernsmedes porte.",
    [1061621699] = "Åh nej! Vi er løbet tør for tid.",
    [3023891429] = "Gammel konge blev død?  Det' umuligt!",
    [12762344] = "Gamlebyen er stedet, du skal gå hen, hvis du vil finde tyve. Den ligger i det nordøstlige hjørne af Stormvind.",
    [3058179690] = "Engang hovedstad for Mørkejern-dværgene tjener dette vulkanske labyrint nu som Ragnarøs Ildherres magtsæde. Ragnarøs har afdækket hemmeligheden bag at skabe liv af sten og planlægger at bygge en hær af ustoppelige golemer til at hjælpe ham med at erobre hele Sortklippebjerget. Besat af at besejre Nefarian og hans draconiske håndlangere vil Ragnarøs gå til enhver yderlighed for at opnå endelig sejr.",
    [3613828048] = "Engang juvelen i de nordlige Herrelande, er byen Stratholm der, hvor Prins Arthæus vendte sig mod sin mentor, Uther Lysbringer, og slagtede hundredvis af sine egne undersåtter, som man mente havde pådraget sig udødhedens pest. Arthæus' overgivelse til Liskekongen fulgte kort efter. Den ødelagte by er nu beboet af den udøde Svøbe – ledet af den mægtige lisk Kel'Tuzad – og en styrke af Blodrøde Korsfarere, ledet af Storslået Korsfarer Dathrovan. De to sider er låst i konstant, voldelig kamp.",
    [3578333461] = "Sig mig venligst, at du ikke lige har gjort, hvad jeg tror, du lige har gjort. Sig mig venligst, at jeg ikke bliver nødt til at gøre dig ondt...",
    [3090231236] = "Polar-armbeskyttere.",
    [2509384840] = "Polar-handsker.",
    [1182622492] = "Polar-tunika.",
    [4219463395] = "Stoltstød!",
    [1623845067] = "Væddeløb dikterer ikke ære, $r. Mens du opholder dig på min gård, beder jeg dig huske og respektere dette credo.$B$BJeg har kendt orker, der har været lige så ærefulde som de ædleste riddere, og mennesker, der har været lige så nedrige som de mest hensynsløse af Svøben.$B$BMen jeg skal ikke kede dig med fortællinger fra min ungdom! Der er meget arbejde at gøre – hvis det er det, du ønsker.",
    [2723934606] = "Ildsvælget består af et net af vulkanske huler under orkernes nye hovedstad Orgrimgrad. For nylig har rygter spredt sig om, at en kult loyal over for det dæmoniske Skyggeråd har slået sig ned i kløftens ildagtige dybder. Denne kult, kendt som Den Brændende Klinge, truer selve Durdotars suverænitet. Mange mener, at ork-krigshøvdingen Trael er klar over klingens eksistens og har valgt ikke at ødelægge den i håbet om, at dens medlemmer kan føre ham direkte til Skyggerådet.",
    [1877133825] = "For nylig opdagede en nattealf-druide ved navn Naralex et net af underjordiske huler i Ødemarkens hjerte. Da han troede, han kunne bruge hulernes kilder til at genoplive Ødemarkens frodighed, begyndte druiden at udsuge energierne fra den sagnomspundne Smaragdgrønne Drøm. Hans vision blev dog på en eller anden måde til et mareridt, og snart forvandlede Jammergrotterne sig til et hi af ondskabsfulde, dødbringende rovdyr. Det siges, at Naralex stadig opholder sig et sted inde i labyrinten, fanget ud over kanterne af Den Smaragdgrønne Drøm.",
    [3160473040] = "Husk, alle ting hænger sammen. Hvis bæsterne forsvandt fra landet, ville vores art dø af en stor ensomhed i ånden, for det, der sker med bæsterne, sker også med taurerne. Det, der rammer Azerot, rammer alle, der bor på det.",
    [1974162322] = "Renaut...",
    [3990769056] = "Shal myrinan ishnu-dal-dorah...",
    [3915481267] = "Beliggende langs Zoram-strandbredden i Askedalen var Den Sorte Afgrund engang et glorværdigt tempel viet nattealfernes månegudinde Elunie. Men den Store Sønderrivelse knuste templet – og sank det under bølgerne i det Tilslørede Hav. Der forblev det urørt – indtil slangefolk og satyrer, drevet af dets gamle kraft, dukkede op for at udforske dets hemmeligheder. Legenderne fortæller, at det gamle udyr Aku'maj har slået sig ned i templets ruiner.",
    [2407765917] = "Lad mig lige få det her på plads. Du svømmede, nej, du tog rygcrawl i smeltet lava med det her... det her lavadragt af dig? Ja? Og ud af den blå luft slugte dette udyr dig hel?",
    [1885495622] = "Så mange års kamp og slaveri, det føles godt at have et hjem igen.",
    [2970614656] = "Noget plager dette tårn. Jeg er blevet syg, og de andre ansatte i Ventureselskabet, der arbejder i nærheden af eller inde i tårnet, er også blevet syge.$B$BBare i sidste uge døde to af vores patruljerende, kun for øjeblikkeligt at vende tilbage til livet som tankeløse droner!$B$BLivskraften drænes ud af min krop. Jeg kan mærke, at jeg mister kontrollen. Trangene overtager... Ringe trang... *Fizzule slår sig selv i ansigtet* Ikke endnu... Lyt... Min stilling er en magtposition. Den giver mig adgang til nogle følsomme oplysninger.",
    [4149390296] = "Stavron...",
    [3093587720] = "Mod har da ikke sendt dig til mig? Han ved bedre. Du er endnu ikke i stand til at forstå, hvad jeg ville lære dig. Gå hen til min søn Mod, lige derude, og afslut din træning hos ham.",
    [3297504182] = "Søde, søde omfavnelse... tag mig...",
    [3684867955] = "Taurer.",
    [365701110] = "Tak, lyset, at du er her! Jeg ville acceptere hjælp fra en tohovedet oger på dette tidspunkt.\n\nByen er blevet overrendt af trogger! Forsøgene på at udrydde dem resulterede i massiv forurening. Men der er stadig håb.\n\nVores videnskabsfolk, der evakuerede til Jernsmede, arbejder på en kur mod strålesygen. Imens, hvis du kan hjælpe mig med at stoppe troggerinvasionen, kan byen måske erobres igen.",
    [718919600] = "Tak for din hjælp, $n. Jeg ønsker dig held og lykke på dine eventyr.",
    [2612131386] = "Tak, Lasede John. Din historie var meget opløftende og oplysende.",
    [1295482229] = "Rustningen fra Forløsning blev båret af vores mest fromme riddere - rustning værdig selveste Lysbringeren!$B$BTusindvis faldt i den sidste krig; deres klædedragter blev revet af deres lig og ført til den frygtindgydende citadel Naxxrammas.$B$BDet siges, at dødsriddere fra Naxxrammas korrumperer Forløsnings-pladerustningen til eget brug.$B$BSådan en tragedie...",
    [4157024724] = "Askebringeren er død, og der vil aldrig komme en til som ham. Den mindre Mørkrøn er langt fra den mand, hans far var. Det ved du godt, kommandør! Det var jo netop din egen ledelse, der var skyld i Blod-højlord Mørkrøns død.",
    [1935560846] = "Banken?  Åh, I mener Hvælvet!  Der er ingen tryggere plads at opbevare jeres værdisager end Hvælvet. I finder det lige nordøst for indgangen til Jernsmede.",
    [2455461890] = "Skænderen... må advare Trael...",
    [2748744218] = "Alegorns retter er simpelthen dødelige af lækkerhed.  Han har altid travlt med at tilberede nye delikatesser nede på Håndværkerterrassen.  Smag endelig hans Cenarion Grøn-opskrift, hvis han har noget tilbage.  \n\nNu, hvis du ikke har noget imod det, må jeg undersøge denne pludselige bølge af forsvundne hjorte.",
    [58156897] = "Stoffet, vores verden er vævet af, er yderst skrøbeligt. Det kræver blot en smule viden og anvendelsen af netop denne viden for at rive stoffet op. Sådan opstår revner.",
    [2080459783] = "Gordønnierne er en stor oger-stamme, der har kontrol over store dele af skovene i Vildalas. Deres mørke magi siver ud i elementerne omkring dem og skader både miljøet og de væsener, der lever der.$B$BHvis du alligevel beslutter dig for at rejse til Vildalas, så vær opmærksom på disse oger -- de er ret ondskabsfulde, og mange kan svinge kraftfuld mørk magi.",
    [2271481893] = "Det evige stjernelys land, Kalimdør, var en nærende moder for alle sine væsner. Magien fra Evighedens Brønd gennemsyrede landet og gav kraft til mylderet af flora og fauna, der ville gøre verden til deres hjem. Af denne magiske æter blev silitiderne født. Det var gennem silitiderne, at den grublende Gamle Gud ville række ud og forsøge at sønderrive den verden, den engang holdt i sit ubarmhjertige greb.",
    [2812138203] = "Den mægtige fæstning, der er hugget ind i Sortklippebjergets brændende indvolde, blev i århundreder holdt af de skumle Mørkejern-dværge, indtil Nefarian - dragen Dødsvinges snedige søn - tog kontrol over det øverste spir og førte krig mod dværgenes besiddelser i bjergets vulkanske dybder. Da Nefarian indså, at dværgene blev anført af den mægtige ildelementar Ragnarøs, svor han at knuse sine fjender og gøre hele Sortklippebjerget til sit eget.",
    [1309762684] = "Klosteret var engang et center for lærdom og oplysning. Med Svøbens fremmarch under Den Tredje Krig blev det fredelige Kloster omdannet til en højborg for det fanatiske Blodrøde Korstog. Korsfarerne er intolerante over for alle ikke-menneskelige racer, uanset alliance eller tilhørsforhold. De tror, at enhver udefra potentielt er bærer af udødepesten - og skal tilintetgøres.",
    [189063839] = "Navnet Jordsplitter har min familie båret i hundredvis af år. Og ligesom min far og hans far før ham har jeg også arvet retten til at skabe ornaterne til min navnebror.",
    [864555661] = "Nattealfernes hær blev presset tilbage gennem Un'Goro til grænserne af Tanaris-ørkenen. Noget i Un'Goro forhindrede Qiraji i at kunne tage landet. Jeg forstår ikke helt dette ord, men jeg tror, det betyder 'Gudelandene.' Der står, at de ikke kunne 'tage Gudelandene.'",
    [3416709931] = "Ordenen af Den Splittede Hånd eksisterede før Trael og skal eksistere efter Trael.",
    [1892297349] = "Skolomance huser i krypter under Kær Darrow-fæstningen. Engang ejet af den adelige Barov-familie forfaldt fæstningen til ruin efter Den Anden Krig. Da magikeren Kel'Tuzad hvervede tilhængere til sin De Fordømtes Kult, lovede han ofte udødelighed til dem, der tjente hans Liskekonge. Barovs faldt for hans indflydelse og donerede deres fæstning, men kultisterne myrdede familien og gjorde krypterne til en skole i nekromanti. Selvom Kel'Tuzad ikke længere opholder sig der, bliver kultister og instruktører stadig.",
    [900646758] = "Åndene har bragt dig til mig, og derfor føler jeg mig velsignet af dem.",
    [2624780574] = "Stockaden er et højsikkerhedsfængsel, skjult under Kanalkvarteret i Stormvind by. Under ledelse af Fangevogter Thelvand huser Stockaden smådyr, politiske oprørere, mordere og en snes af landets farligste forbrydere. For nylig har et fangeledet oprør ført til fuldstændigt kaos i Stockaden - hvor vagterne er blevet jaget væk, og de dømte render frit omkring.",
    [2077408315] = "Syndikatet består af en flok klodsmajorer - uorganiserede, uduelige og dovne...",
    [2887159330] = "Syndikatet opbevarer mange aflåste kasser med forsyninger på Durnholde-fæstningen i Bakkebrad.",
    [4204889870] = "Jammergrotterne har sin indgang ved Frodigvand-oasen sydvest for Korsvejen i Ødemarken.",
    [1083706315] = "Der er mange steder i Stormvind, hvor man kan få sig en drink, men kun ét, der lader dig overnatte. Gå over til Den Forgyldte Rose i Handelsdistriktet. Jeg har hørt, at prisen for et værelse er rimelig, og lagnerne er rene.",
    [3423240586] = "Disse træer er ret prægtige, ikke?",
    [959330062] = "Denne $n er blevet gal af korruptionen!",
    [3469436220] = "TIMMI!",
    [3226127770] = "At dø i kamp er herligt! Men med det, jeg lærer dig, dør du måske ikke så hurtigt, hm?",
    [3862914540] = "For at komme sikkert ned, sørger jeg for vinger til dem, der har brug for det.",
    [2429776423] = "Tormil, Gamlør, Skæffer, Kauri...",
    [1769206083] = "Trøk, er du sulten? Jeg laver lidt mad, så vi kan spise!",
    [3600486826] = "Uldhulen er et gammelt Titan-hvælv, der har ligget begravet i jorden siden verdens skabelse. Dværgiske udgravninger af byen har for nylig frigivet Titanernes første mislykkede skabninger: troggerne. Sagnene fortæller, at da Titanerne erklærede troggerne-eksperimentet for en fiasko, forsøgte de igen, hvilket resulterede i skabelsen af dværgeracen. Disse hemmeligheder er nedskrevet på de sagnomspundne Norgannøns Skiver - enorme artefakter, der ligger på bunden af den gamle by, beskyttet af gigantiske konstruktioner af levende sten.",
    [2359892274] = "Uuuuuuggggghhhhh....",
    [1088280873] = "Vek'nilask og Vek'lør, kendt som Ahn'Kirajs Tvillingkejsere, så krigen fra helligdommen i deres tempel. De kloge brødre udtænkte en plan for at demoralisere og splitte Hjorthelms styrker.",
    [6595258] = "Hexenmestre, hm.  Nå, du har ikke hørt det fra mig, men jeg har hørt rygter om, at den slags samles på en kro ved navn Det Slagtede Lam i Magikerkvarteret.",
    [4138784718] = "Krigere, kaptajner, fortsæt kampen!",
    [138559681] = "Pas på, hvor du træder, $r. Vi af Broderskabet af Let er ikke lige så milde som vore brødre, når det gælder om at uddele retfærdighed til dem, der vil gøre denne verden ond.$B$BVe over dem, der vil vække Korfaks' vrede.$B$BHvis du ikke har nogen forretning med mig eller de andre medlemmer af Broderskabet, så vær venlig at gå, så vi kan fortsætte vores møde.",
    [280579845] = "Vi ved det ikke.$B$BDe Mørkjernsdværge, der overlevede, trængte ind i bjerget og begyndte at genopbygge deres by.$B$BAf Tårissans aske rejste Sortklippe-spiret sig og den nye Mørkejern-nation. Yderligere befæstninger blev opført i Svidningskløften, i området kendt som Gryden.$B$BHistorier om en gammel ondskab, der kontrollerede Mørkjernsdværgenes rige, begyndte at cirkulere.",
    [1777902144] = "Vi bruger mange dyrepelse og skind i vores skabelser.",
    [2180213803] = "Vi bliver angrebet!  Hold op, I svabere! Slå invaderne tilbage!",
    [163100235] = "Nå, måske er 'betaling' ikke det bedste ord at bruge. Se, da jeg sad fast i maven på det der, begyndte jeg at tænke:$B$BDette væsen lever i hed, flammende magma, og alligevel tager det ikke en brøkdel af skade fra ilden!$B$BHvis bare jeg kunne finde et ukrænket skind fra et af disse udyr. Så kunne jeg tage det med til min kære ven, Malifus Mørkhammer, i Evigblik. Hvis nogen kan gøre noget med skindet fra et udyr som dette, er det ham.",
    [897964096] = "Hvad har du gjort, Isfuglien? Du kæmpede engang med ære, for vores folks bedste... og nu... har du myrdet min dreng...",
    [2179179994] = "Det, jeg tilbyder dig nu, er en sådan klinge - uhærdet, uopvarmet, ubehandlet - den rå og mest basale form.$B$BNu skal du blot finde en drage, der villigt vil fortrylle klingen.$B$BHavde du en evighed at leve i, kunne det måske lade sig gøre; men da du er dødelig og meget vel kan holde op med at eksistere når som helst, kan jeg måske anbefale, at du forsøger at overtale en af de mindre drager til at gøre dit bud.",
    [1128026159] = "Hvornår kommer pappa tilbage fra kampene i Krigssang? Det er så længe siden...",
    [2563353024] = "Hvor er \"Garona: Et Studie i Snigen og Forræderi!\"? Disse tekster skal leveres tilbage!",
    [3251711040] = "Hvor er din frelser? Hvor længe kan du holde stand mod mine angreb?",
    [3865194659] = "Hvorfor ser vi ikke, hvad du er i stand til? Hvis du fuldfører opgaven, vil jeg med glæde videreudvikle din træning!",
    [4147067494] = "Vindsor var særligt sur den dag - og tro mig, for Vindsor er det en monumental bedrift. Han blev ved med at sige, at 'noget føles forkert.' Nå, han tog ikke fejl!$B$BVi var midt i Sortklippebjerget, da de snavsede dyr angreb. Jeg taler selvfølgelig om orkerne. Hør efter, vil du? Alt, man kunne høre, var gryntene og klirren af stål, da de stormede frem mod os.",
    [738533209] = "Vildt.",
    [939154407] = "Gaaaaaaawwwwwnnnn...",
    [289740098] = "Ja, med det samme, mor!",
    [2922318106] = "Ja, det må du godt, Okla. Men gå ikke for langt hjemmefra.",
    [926652820] = "Du er ivrig, og det er godt. Men du er endnu ikke klar til at træne med en som mig.",
    [3526842198] = "Du snakker vrøvl, magiker.",
    [3282878495] = "Du er ikke egnet til at træne med mig, fremmede. Tilbring noget tid med min assistent Jhæg derovre.",
    [3392009475] = "Du har bedst at sætte dig, for det her bliver en lang en.$B$BDa vi først ankom til Silitus, var Dame Mar'alit den første nattenisse fra Cenarion-fæstningen, der sluttede sig til ekspeditionen. Vores rutine var intet usædvanligt: Dan en gruppe, der kan begive sig ud i de forskellige reder og lede efter forsvundne artefakter.",
    [3617250638] = "Du kom lige, da de var ved at kaste mig til fjenderne nedenunder - for det takker jeg dig. Måske kan jeg - nej, vi, af den Blå Flyvning - hjælpe dig yderligere?$B$BDu er kommet så langt, $r, og har risikeret meget. Vil du gå et stykke længere for at kæmpe mod Nefarian og hans Sortklippe-legion?",
    [1238369117] = "I landkrabber er sejere, end jeg troede! Jeg må improvisere!",
    [2730905529] = "Du har måske, hvad det kræver. Lad os finde ud af det!",
    [3076291510] = "Vil du lære at blive skrædder?  Hmmm... Jeg tror, der er en skrædder over i Østdal Tømmerlejr, som måske kan få dig i gang.",
    [2391895296] = "Du vil bringe ham tilbage til denne verden, mester.",
    [1982718180] = "Du finder Sildinær ved Krigerens Terrasse blandt vagterne, hendes skarpe øjne spejder skoven efter fjender, der måtte våge sig ind i vores smukke by.",
    [2360136174] = "%s trækker vejret uregelmæssigt.",
    [3360383171] = "2. kæde, første svar.  TOTALT KNUST~",
    [893357066] = "For blot tre hundrede år siden tilkaldte en hensynsløs dværg ved navn Tårissan mesteren fra sit ildagtige rige. Hans tilbagevenden til denne ussel verden hærgede de omkringliggende lande og skabte denne vulkanske Kerne. Den mægtige Ragnarøs har sovet under dette bjerg lige siden.",
    [3272192740] = "Antion, jeg ser ud til at have tabt det banner, du har skabt til mig.",
    [75304284] = "Antion, jeg ser ud til at have tabt det banner, du har skabt til mig.",
    [148836163] = "AAARRRRRGGGHHH!",
    [4116756182] = "Babba bøjj....",
    [195851761] = "Bethek",
    [2645036425] = "Fortryllings-faget er kunsten at forbedre eksisterende genstande med magi.",
    [4040336035] = "Ophøjet.",
    [2137947332] = "JERN MÆGTIG!",
    [947019456] = "Generisk tekst",
    [1673509626] = "Generisk tekst2",
    [2609360819] = "MÅÅÅÅÅÅÅÅLLLLLLLLLLL!",
    [79343406] = "Hellige Krakkel! Temperaturen er 428.000 grader Krakkenhed!",
    [408974132] = "Æret.",
    [3079699889] = "Jeg er Øglefang. Broder af Brokkigar.",
    [1767657055] = "Jeg må vide noget: Hvordan kom du på toilettet med den ting på?",
    [693394961] = "Jeg tilkalder dig, Sha'ni Stoltstød!",
    [267625997] = "Jeg klarer den ikke... døden kommer...",
    [1800946703] = "Jeg er vendt tilbage til mit gamle hjem, så min viden kan videregives. I modsætning til de tankeløse udøde omkring mig har jeg valgt denne unaturlige tilværelse af egen fri vilje.$B$BSilitiderne er formidable modstandere, $n.  Jeg har lært at respektere dem lige så meget, som jeg foragter dem.$B$BMeget af deres dødbringende evne kommer af styrken og letheden i deres chitin, som jeg har lært at arbejde ind i rustning.  Da vi tilsyneladende har en fælles fjende, skal jeg lære dig mit håndværk.",
    [3155369368] = "Hvis det er nogen trøst, lader jeg cellens dør stå åben. Hvordan du kommer ud, er dit problem. Hej hej, Hårdan.",
    [1051332349] = "Tilmeld dig en gruppe på vej til dette fangehul.    <Dette valg placerer dig i mødestens-køen>",
    [3278729489] = "Lokk'tar Ogar !",
    [863612625] = "Lokk'tar Ogar!",
    [45958211] = "Ser ud til, at I måske har det i jer til en stor smed. Men før jeg lærer jer noget, må jeg vide, at I har, hvad der skal til.",
    [4117092775] = "Mange mener, at staven er et ringere våben. Jeg udfordrer enhver, der mener det, til at bevise deres styrke mod min stav.",
    [2269491356] = "Markedsføring - iKoke Forløsningshilsen (S.H.E. ikke-Quest)",
    [3019336104] = "Flere fanger!",
    [2837089894] = "Min søn kunne designe en hurtigere bil end den klodsede kobold-skraldebunke!",
    [1318386891] = "Åh, jeg elsker et godt slagsmål, men nogle gange har ens fjende en kranie tykkere end et thorium-varmeskjold. Den slags tider kræver en lillebitte smule hjælp.",
    [1892551436] = "Tarmhugger",
    [1738836050] = "Åh, det er bare så forfærdeligt, $g hr:frøken;. Huset Barov var engang fyldt med liv... fyldt med pragt. Herregården var Barov-familiens primære bopæl midt i deres vidtrækkende imperium.$B$BLysen og jeg bemærkede, at efterhånden som dagene gik, blev Barov-familien deprimeret. Modløs. Paranoia og raseri overmandede ofte herren og fruen. Om natten kunne vi høre Barov-familien skændes i deres kamre. Så vidt vi forstod, havde deres grådighed 'brudt dæmningen', så at sige.",
    [2624905707] = "Pelver",
    [756159804] = "Rååååååårrrr!",
    [1860152625] = "Hærger følg $n! Hærger KNUSER krybskytter! KNUS KNUS KNUS! Fortæl Hærger at KNUSE ved at lege med en pind! KNUS!",
    [1512900593] = "Respekteret.",
    [3226762273] = "gemt verdenstilstand er: $2285W",
    [3384367132] = "Noget plager dette tårn. Jeg er blevet syg, og de andre ansatte i Ventureselskabet, der arbejder i nærheden af eller inde i tårnet, er også blevet syge. Lige i sidste uge døde to af vores patruljemænd, bare for straks at vende tilbage som tankeløse droner! Livskraften dræner min krop. Jeg kan mærke, at jeg mister kontrollen. Trangene overtager... Onde trang... Ikke endnu... Lyt... Min stilling er en magtposition. Den giver mig adgang til nogle følsomme oplysninger.",
    [2410711775] = "PRØVE",
    [1400429259] = "PRØVE - død efter angreb $n",
    [3305162390] = "PRØVE - død før angreb $n",
    [2704349078] = "PRØVE - genstart slagmarken.",
    [1407237991] = "Den lange genladning tager lidt tid at vænne sig til, men intet andet er bedre til at indlede en kamp.",
    [737613095] = "Den nærmeste bank, I finder, er Hvælvet i Jernsmede, $gdreng : pige;.",
    [2287730611] = "Ugle",
    [3685704017] = "Overdæk Forfremmelse - Landrø Standard",
    [3199171255] = "Vorfalk",
    [1468664375] = "Vi, hans svorne tjenere, udfører hans vilje og håndhæver hans jernhårde styre. Afskåret fra energierne i hans ildagtige rige er Ragnarøs kun en skygge af sit sande jeg. Han har dog mere end nok styrke til at blive din undergang.",
    [222222675] = "Hvad mener du med, at du ikke ved, hvordan man bruger en økse?",
    [1499295000] = "Jippi, nu går den! Alle har samlet alt, og det hele bliver luftfragtet med zeppelin til Silitus, mens vi taler. Det sidste skulle være der om mindre end $2113w dage. Når det hele er der, og scepteret er samlet, kan krigen mod de beskidte insekter begynde. Som man siger: 'Send det af sted!'",
    [520442700] = "Vauv!",
    [1089071756] = "Du har et talent for ord, Overherre Øglefang.",
